INSERT INTO public.pronunciation_lessons (skill, title, level, difficulty, accent, explain, points, items, caution, is_free, sort_order, status) VALUES
('chunking', 'Thought groups', 'intermediate', 'medium', 'us', 'Break long sentences into short meaning groups with a tiny pause between them. It sounds calm and clear.', ARRAY['Pause at the / marks.', 'Never pause in the middle of a thought group.']::text[], '[{"text": "When I got home, I realized I had forgotten my keys.", "pattern": "When I got home / I realized / I had forgotten my keys."}, {"text": "In my opinion, learning a language takes time and patience.", "pattern": "In my opinion / learning a language / takes time and patience."}, {"text": "If you have any questions, please let me know.", "pattern": "If you have any questions / please let me know."}]'::jsonb, '', true, 1, 'published'),
('chunking', 'Breath groups for longer answers', 'advanced', 'hard', 'us', 'In a two-minute answer, plan where you breathe. Breathe at the end of a group, never in the middle of one.', ARRAY['One breath per group.', 'Drop your pitch slightly at the end of a completed group.']::text[], '[{"text": "The place I''d like to talk about is a small café near my old apartment, which I visited almost every weekend.", "pattern": "The place I''d like to talk about / is a small café near my old apartment / which I visited almost every weekend."}, {"text": "I started learning English at school, but I only became confident when I began speaking every day.", "pattern": "I started learning English at school / but I only became confident / when I began speaking every day."}]'::jsonb, '', true, 2, 'published'),
('chunking', 'Chunking when giving directions', 'beginner', 'easy', 'us', 'Direction-giving is much easier to follow when broken into small chunks with pauses.', '{}'::text[], '[{"text": "Go straight ahead, then turn left at the second light, and it''s on your right.", "pattern": "Go straight ahead / then turn left at the second light / and it''s on your right."}]'::jsonb, '', true, 3, 'published'),
('chunking', 'Chunking in a presentation opening', 'intermediate', 'medium', 'us', 'Presentations sound much more confident when chunked clearly, giving the audience time to process.', '{}'::text[], '[{"text": "Good morning everyone, thank you for coming, and let''s get started.", "pattern": "Good morning everyone / thank you for coming / and let''s get started."}]'::jsonb, '', true, 4, 'published'),
('chunking', 'Chunking in storytelling', 'intermediate', 'medium', 'us', 'Stories flow better and build suspense when chunked at natural narrative breaks.', '{}'::text[], '[{"text": "So one day, I was walking home from work, when I suddenly heard a strange noise behind me.", "pattern": "So one day / I was walking home from work / when I suddenly heard a strange noise behind me."}]'::jsonb, '', true, 5, 'published'),
('chunking', 'Chunking in IELTS-style long answers', 'advanced', 'hard', 'us', 'For Part 2 or Part 3 answers, chunk each supporting reason separately so the examiner can follow your structure.', '{}'::text[], '[{"text": "I think remote work has both advantages and disadvantages, because on one hand it gives people more flexibility, but on the other hand it can make teamwork harder.", "pattern": "I think remote work has both advantages and disadvantages / because on one hand it gives people more flexibility / but on the other hand it can make teamwork harder."}]'::jsonb, '', false, 6, 'published'),
('chunking', 'Chunking with introductory phrases', 'beginner', 'easy', 'us', 'A short introductory phrase is usually its own chunk, set off with a small pause.', '{}'::text[], '[{"text": "Honestly, I don''t really mind either way.", "pattern": "Honestly / I don''t really mind either way."}, {"text": "To be fair, he did apologize afterwards.", "pattern": "To be fair / he did apologize afterwards."}]'::jsonb, '', false, 7, 'published'),
('chunking', 'Chunking a recipe', 'beginner', 'easy', 'us', 'Recipe steps naturally break into chunks at each action — pause briefly between them.', '{}'::text[], '[{"text": "First, chop the onions, then fry them in a little oil, and add the garlic once they''re soft.", "pattern": "First, chop the onions / then fry them in a little oil / and add the garlic once they''re soft."}]'::jsonb, '', false, 8, 'published'),
('chunking', 'Chunking when comparing two things', 'intermediate', 'medium', 'us', 'Comparisons chunk around each side of the comparison, with a small pause before the contrast word.', '{}'::text[], '[{"text": "Living in the city is more convenient, but living in the countryside is much more peaceful.", "pattern": "Living in the city is more convenient / but living in the countryside is much more peaceful."}]'::jsonb, '', false, 9, 'published'),
('chunking', 'Chunking while describing a chart or graph', 'advanced', 'hard', 'us', 'Describing data chunks around each trend or figure, giving the listener time to picture it.', '{}'::text[], '[{"text": "The graph shows a steady increase from 2010 to 2015, followed by a sharp drop in 2016.", "pattern": "The graph shows a steady increase from 2010 to 2015 / followed by a sharp drop in 2016."}]'::jsonb, '', false, 10, 'published'),
('chunking', 'Chunking a formal message read aloud', 'intermediate', 'medium', 'us', 'Reading a formal email or message aloud still needs natural chunking, not a flat word-by-word read.', '{}'::text[], '[{"text": "Dear team, I wanted to let you know that the meeting has been moved to Thursday at 3pm.", "pattern": "Dear team / I wanted to let you know / that the meeting has been moved to Thursday at 3pm."}]'::jsonb, '', false, 11, 'published'),
('chunking', 'Chunking sentences with relative clauses', 'advanced', 'hard', 'us', 'A relative clause (''which...'', ''who...'') is usually its own chunk, set off by small pauses on both sides.', '{}'::text[], '[{"text": "My brother, who lives in Canada, is visiting next month.", "pattern": "My brother / who lives in Canada / is visiting next month."}]'::jsonb, '', false, 12, 'published'),
('chunking', 'Chunking safety instructions', 'intermediate', 'medium', 'us', 'Safety instructions need very clear chunking so each instruction is unmistakable.', '{}'::text[], '[{"text": "In case of fire, stay calm, leave the building immediately, and do not use the elevator.", "pattern": "In case of fire / stay calm / leave the building immediately / and do not use the elevator."}]'::jsonb, '', false, 13, 'published'),
('chunking', 'Chunking practice: sentences that keep growing', 'advanced', 'hard', 'us', 'As a sentence grows longer, the number of chunks grows too — practise adding one chunk at a time.', '{}'::text[], '[{"text": "I like coffee.", "pattern": "1 chunk"}, {"text": "I like coffee, especially in the morning.", "pattern": "2 chunks"}, {"text": "I like coffee, especially in the morning, when I need to wake up properly.", "pattern": "3 chunks"}]'::jsonb, '', false, 14, 'published'),
('chunking', 'Chunking in a job interview answer', 'advanced', 'hard', 'us', 'Structured interview answers chunk around each part of the story: situation, action, result.', '{}'::text[], '[{"text": "In my last role, we had a tight deadline, so I reorganized the team''s priorities, and we ended up delivering two days early.", "pattern": "In my last role, we had a tight deadline / so I reorganized the team''s priorities / and we ended up delivering two days early."}]'::jsonb, '', false, 15, 'published'),
('chunking', 'Chunking parenthetical asides', 'advanced', 'hard', 'us', 'An extra comment inserted mid-sentence is its own chunk, set off clearly on both sides.', '{}'::text[], '[{"text": "My colleague, who''s actually pretty new to the team, handled it really well.", "pattern": "My colleague / who''s actually pretty new to the team / handled it really well."}]'::jsonb, '', false, 16, 'published'),
('chunking', 'Chunking ''not only... but also'' structures', 'advanced', 'hard', 'us', 'Each half of this structure is its own chunk, with a small pause right before ''but also''.', '{}'::text[], '[{"text": "Not only is it cheaper, but it''s also much faster.", "pattern": "Not only is it cheaper / but it''s also much faster."}]'::jsonb, '', false, 17, 'published'),
('chunking', 'Chunking a product demo', 'intermediate', 'medium', 'us', 'Product demos chunk around each feature being shown, pausing to let it land before moving on.', '{}'::text[], '[{"text": "So here you can see the dashboard, and if you click this button, it generates the report automatically.", "pattern": "So here you can see the dashboard / and if you click this button / it generates the report automatically."}]'::jsonb, '', false, 18, 'published'),
('chunking', 'Chunking when explaining rules of a game', 'intermediate', 'medium', 'us', 'Rule explanations chunk around each individual rule so listeners can follow along.', '{}'::text[], '[{"text": "Each player gets seven cards, and on your turn, you either play a card or draw a new one.", "pattern": "Each player gets seven cards / and on your turn / you either play a card or draw a new one."}]'::jsonb, '', false, 19, 'published'),
('chunking', 'Chunking with time clauses (before, after, while)', 'intermediate', 'medium', 'us', 'Time clauses are usually their own chunk, whether they come at the start or end of the sentence.', '{}'::text[], '[{"text": "Before you leave, make sure you lock the door.", "pattern": "Before you leave / make sure you lock the door."}, {"text": "I''ll call you while I''m on my way there.", "pattern": "I''ll call you / while I''m on my way there."}]'::jsonb, '', false, 20, 'published'),
('chunking', 'Chunking practice: even longer sentence buildup', 'advanced', 'hard', 'us', 'A second buildup drill, starting more complex and adding even more chunks.', '{}'::text[], '[{"text": "I work in marketing.", "pattern": "1 chunk"}, {"text": "I work in marketing, mainly on social media campaigns.", "pattern": "2 chunks"}, {"text": "I work in marketing, mainly on social media campaigns, which I''ve been doing for about five years now.", "pattern": "3 chunks"}]'::jsonb, '', false, 21, 'published'),
('chunking', 'Chunking cause and effect', 'intermediate', 'medium', 'us', 'Cause-and-effect sentences chunk around the cause and the resulting effect separately.', '{}'::text[], '[{"text": "Because the flight was delayed, we missed our connection.", "pattern": "Because the flight was delayed / we missed our connection."}, {"text": "The store closed early, so we couldn''t buy anything.", "pattern": "The store closed early / so we couldn''t buy anything."}]'::jsonb, '', false, 22, 'published'),
('chunking', 'Chunking a list of pros and cons together', 'advanced', 'hard', 'us', 'When listing several pros and cons in one breath, each point gets its own small chunk.', '{}'::text[], '[{"text": "It''s affordable, it''s convenient, but the quality isn''t always consistent.", "pattern": "It''s affordable / it''s convenient / but the quality isn''t always consistent."}]'::jsonb, '', false, 23, 'published'),
('chunking', 'Chunking a formal announcement at work', 'advanced', 'hard', 'us', 'Workplace announcements chunk clearly so nobody misses an important detail.', '{}'::text[], '[{"text": "Starting next Monday, the office will be open until 7pm, so please plan your schedules accordingly.", "pattern": "Starting next Monday / the office will be open until 7pm / so please plan your schedules accordingly."}]'::jsonb, '', false, 24, 'published'),
('chunking', 'Chunking when telling someone bad news gently', 'advanced', 'hard', 'us', 'Delivering difficult news benefits from extra-clear chunking, giving the listener time to absorb each part.', '{}'::text[], '[{"text": "I need to tell you something, and I want you to know it''s not your fault, but the project''s been cancelled.", "pattern": "I need to tell you something / and I want you to know it''s not your fault / but the project''s been cancelled."}]'::jsonb, '', false, 25, 'published'),
('chunking', 'Chunking a short tribute or toast', 'advanced', 'hard', 'us', 'A tribute speech chunks around each memory or quality being honoured, with a pause to let it land.', '{}'::text[], '[{"text": "She''s always been there for everyone, she never asks for anything in return, and today we get to celebrate her.", "pattern": "She''s always been there for everyone / she never asks for anything in return / and today we get to celebrate her."}]'::jsonb, '', false, 26, 'published'),
('chunking', 'Chunking while describing a photo', 'intermediate', 'medium', 'us', 'Describing an image chunks around each element you notice, moving from general to specific.', '{}'::text[], '[{"text": "In this photo, there''s a group of friends sitting by the lake, and you can tell they''re having a great time.", "pattern": "In this photo / there''s a group of friends sitting by the lake / and you can tell they''re having a great time."}]'::jsonb, '', false, 27, 'published'),
('chunking', 'Chunking while explaining a historical event', 'advanced', 'hard', 'us', 'Historical explanations chunk around cause, event and consequence.', '{}'::text[], '[{"text": "After years of tension, the two countries finally signed a peace agreement, which changed the region for decades.", "pattern": "After years of tension / the two countries finally signed a peace agreement / which changed the region for decades."}]'::jsonb, '', false, 28, 'published'),
('chunking', 'Chunking while discussing a book or movie plot', 'intermediate', 'medium', 'us', 'Plot summaries chunk around each major turning point in the story.', '{}'::text[], '[{"text": "The main character starts out pretty naive, but after everything that happens, she ends up completely transformed.", "pattern": "The main character starts out pretty naive / but after everything that happens / she ends up completely transformed."}]'::jsonb, '', false, 29, 'published'),
('chunking', 'Chunking during a negotiation', 'advanced', 'hard', 'us', 'Negotiation chunks around your offer and your condition, giving weight to each part.', '{}'::text[], '[{"text": "I could agree to that price, but only if we extend the deadline by two weeks.", "pattern": "I could agree to that price / but only if we extend the deadline by two weeks."}]'::jsonb, '', false, 30, 'published'),
('chunking', 'Chunking describing symptoms to a doctor', 'intermediate', 'medium', 'us', 'Describing symptoms chunks around each separate symptom so nothing gets missed.', '{}'::text[], '[{"text": "I''ve had a headache since yesterday, and this morning I also started feeling a bit dizzy.", "pattern": "I''ve had a headache since yesterday / and this morning I also started feeling a bit dizzy."}]'::jsonb, '', false, 31, 'published'),
('chunking', 'Chunking a travel itinerary', 'beginner', 'easy', 'us', 'Itineraries chunk around each day or destination.', '{}'::text[], '[{"text": "We land on Monday, spend two days in the city, and then head to the coast for the weekend.", "pattern": "We land on Monday / spend two days in the city / and then head to the coast for the weekend."}]'::jsonb, '', false, 32, 'published'),
('chunking', 'Chunking while explaining a budget', 'advanced', 'hard', 'us', 'Budget explanations chunk around each category of spending.', '{}'::text[], '[{"text": "Half of it goes to rent, a quarter goes to savings, and the rest covers everything else.", "pattern": "Half of it goes to rent / a quarter goes to savings / and the rest covers everything else."}]'::jsonb, '', false, 33, 'published'),
('chunking', 'Chunking while comparing job offers', 'advanced', 'hard', 'us', 'Comparing offers chunks around each job''s pros, with a clear pause before the contrast.', '{}'::text[], '[{"text": "The first offer pays more, but the second one has much better work-life balance.", "pattern": "The first offer pays more / but the second one has much better work-life balance."}]'::jsonb, '', false, 34, 'published'),
('chunking', 'Chunking while troubleshooting a problem', 'intermediate', 'medium', 'us', 'Troubleshooting chunks around each thing you''ve already tried.', '{}'::text[], '[{"text": "I''ve already restarted it twice, and I''ve also checked the cables, but it still won''t turn on.", "pattern": "I''ve already restarted it twice / and I''ve also checked the cables / but it still won''t turn on."}]'::jsonb, '', false, 35, 'published'),
('chunking', 'Chunking while narrating a dream', 'intermediate', 'medium', 'us', 'Dream narration chunks around each strange or memorable moment.', '{}'::text[], '[{"text": "I was walking through this huge house, and suddenly all the doors disappeared, and I just woke up.", "pattern": "I was walking through this huge house / and suddenly all the doors disappeared / and I just woke up."}]'::jsonb, '', false, 36, 'published'),
('chunking', 'Chunking while discussing environmental issues', 'advanced', 'hard', 'us', 'Discussing environmental topics chunks around the problem and its consequence, common in IELTS Part 3.', '{}'::text[], '[{"text": "As more forests are cut down, we lose important habitats, and that has a huge impact on biodiversity.", "pattern": "As more forests are cut down / we lose important habitats / and that has a huge impact on biodiversity."}]'::jsonb, '', false, 37, 'published'),
('chunking', 'Chunking while describing a city', 'beginner', 'easy', 'us', 'City descriptions chunk around each feature you mention.', '{}'::text[], '[{"text": "It''s a pretty small city, but it has a really nice old town, and the people are incredibly friendly.", "pattern": "It''s a pretty small city / but it has a really nice old town / and the people are incredibly friendly."}]'::jsonb, '', false, 38, 'published'),
('chunking', 'Chunking while explaining a hobby in detail', 'intermediate', 'medium', 'us', 'Hobby explanations chunk around what you do, why you enjoy it, and how often.', '{}'::text[], '[{"text": "I''ve been into photography for a few years now, mostly landscapes, and I try to go out shooting every weekend.", "pattern": "I''ve been into photography for a few years now / mostly landscapes / and I try to go out shooting every weekend."}]'::jsonb, '', false, 39, 'published'),
('chunking', 'Chunking while discussing childhood memories', 'intermediate', 'medium', 'us', 'Nostalgic storytelling chunks around each remembered detail, common in IELTS Part 2.', '{}'::text[], '[{"text": "Every summer we''d visit my grandparents'' farm, and I remember waking up really early just to feed the animals.", "pattern": "Every summer we''d visit my grandparents'' farm / and I remember waking up really early / just to feed the animals."}]'::jsonb, '', false, 40, 'published'),
('chunking', 'Chunking while explaining a company policy', 'advanced', 'hard', 'us', 'Policy explanations chunk around the rule and its exception or reasoning.', '{}'::text[], '[{"text": "Employees can work remotely two days a week, as long as they''re available for core meeting hours.", "pattern": "Employees can work remotely two days a week / as long as they''re available for core meeting hours."}]'::jsonb, '', false, 41, 'published'),
('chunking', 'Chunking while discussing exam or study strategies', 'intermediate', 'medium', 'us', 'Study-strategy talk chunks around each technique being described.', '{}'::text[], '[{"text": "I usually make flashcards for vocabulary, and then I review them right before bed, since that seems to help me remember better.", "pattern": "I usually make flashcards for vocabulary / and then I review them right before bed / since that seems to help me remember better."}]'::jsonb, '', false, 42, 'published'),
('chunking', 'Chunking while explaining an app feature', 'intermediate', 'medium', 'us', 'Tech explanations chunk around each step or feature.', '{}'::text[], '[{"text": "You just tap the plus icon, choose a category, and it automatically saves your entry.", "pattern": "You just tap the plus icon / choose a category / and it automatically saves your entry."}]'::jsonb, '', false, 43, 'published'),
('chunking', 'Chunking while discussing sports highlights', 'intermediate', 'medium', 'us', 'Sports recaps chunk around each key moment of the game.', '{}'::text[], '[{"text": "They were down by ten points at halftime, but they made an incredible comeback in the final quarter.", "pattern": "They were down by ten points at halftime / but they made an incredible comeback in the final quarter."}]'::jsonb, '', false, 44, 'published'),
('chunking', 'Chunking while giving nutrition advice', 'intermediate', 'medium', 'us', 'Health advice chunks around each recommendation.', '{}'::text[], '[{"text": "Try to eat more vegetables, drink plenty of water, and avoid too much sugar in the evening.", "pattern": "Try to eat more vegetables / drink plenty of water / and avoid too much sugar in the evening."}]'::jsonb, '', false, 45, 'published'),
('chunking', 'Chunking while discussing weather patterns', 'intermediate', 'medium', 'us', 'Weather-pattern discussion chunks around cause and typical result.', '{}'::text[], '[{"text": "Because the city is near the coast, the weather changes really quickly, so it can be sunny one hour and rainy the next.", "pattern": "Because the city is near the coast / the weather changes really quickly / so it can be sunny one hour and rainy the next."}]'::jsonb, '', false, 46, 'published'),
('chunking', 'Chunking during a phone support call', 'intermediate', 'medium', 'us', 'Support calls chunk around each troubleshooting step you ask the customer to try.', '{}'::text[], '[{"text": "Okay, first can you check if it''s plugged in properly, and then let me know what the screen shows.", "pattern": "Okay, first can you check if it''s plugged in properly / and then let me know what the screen shows."}]'::jsonb, '', false, 47, 'published'),
('chunking', 'Chunking a short formal disclaimer', 'advanced', 'hard', 'us', 'Even dense formal text needs clear chunking when read aloud, or it becomes impossible to follow.', '{}'::text[], '[{"text": "This offer is valid until the end of the month, applies only to new customers, and cannot be combined with other promotions.", "pattern": "This offer is valid until the end of the month / applies only to new customers / and cannot be combined with other promotions."}]'::jsonb, '', false, 48, 'published'),
('chunking', 'Chunking while weighing a personal decision', 'advanced', 'hard', 'us', 'Personal decision-making chunks around each factor being weighed, common in IELTS Part 3 discussion.', '{}'::text[], '[{"text": "On one hand, staying here means job security, but on the other hand, moving abroad could open up a lot more opportunities.", "pattern": "On one hand, staying here means job security / but on the other hand, moving abroad could open up a lot more opportunities."}]'::jsonb, '', false, 49, 'published'),
('chunking', 'Final mixed chunking review', 'advanced', 'hard', 'us', 'A closing set — mark where you''d pause before checking the suggested chunks.', '{}'::text[], '[{"text": "Even though it was raining, we decided to go for a walk anyway, since we hadn''t seen each other in months.", "pattern": "Even though it was raining / we decided to go for a walk anyway / since we hadn''t seen each other in months."}]'::jsonb, '', false, 50, 'published'),
('chunking', 'Practice', 'intermediate', 'medium', 'us', 'Master chunking across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "In the early morning / the mist hung over the lake.", "pattern": "In the early morning / the mist hung over the lake.", "note": "Pause between time prepositional phrase and main clause."}, {"text": "If you want to succeed / you must be consistent.", "pattern": "If you want to succeed / you must be consistent.", "note": "Natural break after conditional dependent clause."}, {"text": "The young woman in the red coat / smiled warmly.", "pattern": "The young woman in the red coat / smiled warmly.", "note": "Pause separates long subject noun phrase from the predicate."}, {"text": "Before you sign the contract / read every single page.", "pattern": "Before you sign the contract / read every single page.", "note": "Pause after introductory dependent clause."}, {"text": "Although he was exhausted / he finished the marathon.", "pattern": "Although he was exhausted / he finished the marathon.", "note": "Pause highlights the concession before the result."}, {"text": "According to the latest survey / consumer confidence has risen.", "pattern": "According to the latest survey / consumer confidence has risen.", "note": "Pause after citation phrase."}, {"text": "To be completely honest / I did not expect this outcome.", "pattern": "To be completely honest / I did not expect this outcome.", "note": "Discourse marker chunked separately."}, {"text": "When the bell rang / all the students / hurried into the classroom.", "pattern": "When the bell rang / all the students / hurried into the classroom.", "note": "Three balanced breath groups."}, {"text": "In order to improve your speaking / practice every single day.", "pattern": "In order to improve your speaking / practice every single day.", "note": "Purpose clause followed by imperative action."}, {"text": "As soon as we arrived at the hotel / it started pouring rain.", "pattern": "As soon as we arrived at the hotel / it started pouring rain.", "note": "Pause marks time transition."}, {"text": "The company / which was founded ten years ago / went public yesterday.", "pattern": "The company / which was founded ten years ago / went public yesterday.", "note": "Non-defining relative clause enclosed in pauses."}, {"text": "My older brother / who works in Tokyo / is visiting this weekend.", "pattern": "My older brother / who works in Tokyo / is visiting this weekend.", "note": "Parenthetical clause separated on both sides."}, {"text": "The decision / however difficult / had to be made.", "pattern": "The decision / however difficult / had to be made.", "note": "Contrasting parenthetical phrase set apart."}, {"text": "His primary goal / to become a pilot / required intense discipline.", "pattern": "His primary goal / to become a pilot / required intense discipline.", "note": "Appositive infinitive phrase bracketed by pauses."}, {"text": "The painting / discovered in an old attic / was worth millions.", "pattern": "The painting / discovered in an old attic / was worth millions.", "note": "Participial descriptive chunk."}, {"text": "On one hand / the salary is attractive / but on the other / the hours are long.", "pattern": "On one hand / the salary is attractive / but on the other / the hours are long.", "note": "Four balanced rhetorical chunks."}, {"text": "First / heat the skillet / then / add a spoonful of olive oil.", "pattern": "First / heat the skillet / then / add a spoonful of olive oil.", "note": "Step-by-step procedural chunking."}, {"text": "Neither my parents / nor my siblings / could attend the ceremony.", "pattern": "Neither my parents / nor my siblings / could attend the ceremony.", "note": "Correlative conjunctions create rhythmic pauses."}, {"text": "Not only did he win first prize / but he also broke the record.", "pattern": "Not only did he win first prize / but he also broke the record.", "note": "Inverted parallel structure divided neatly."}, {"text": "Either we leave immediately / or we will miss the boarding call.", "pattern": "Either we leave immediately / or we will miss the boarding call.", "note": "Pause between two urgent alternatives."}, {"text": "Ladies and gentlemen / thank you for coming / this evening.", "pattern": "Ladies and gentlemen / thank you for coming / this evening.", "note": "Public address: vocative chunk, appreciation chunk, time chunk."}, {"text": "I am pleased to announce / that our quarterly profits / have increased by twenty percent.", "pattern": "I am pleased to announce / that our quarterly profits / have increased by twenty percent.", "note": "Formal presentation delivery."}, {"text": "Today / we stand at a critical crossroad / in our history.", "pattern": "Today / we stand at a critical crossroad / in our history.", "note": "Deliberate oratorical phrasing."}, {"text": "The question is not / whether we can do this / but whether we will.", "pattern": "The question is not / whether we can do this / but whether we will.", "note": "Rhetorical antithesis divided into three thought units."}, {"text": "Let us remember / that every great journey / begins with a single step.", "pattern": "Let us remember / that every great journey / begins with a single step.", "note": "Inspirational pacing."}, {"text": "Without hesitation / she dived into the water / and rescued the child.", "pattern": "Without hesitation / she dived into the water / and rescued the child.", "note": "Narrative action chunks."}, {"text": "Under the spreading chestnut tree / the village smithy stands.", "pattern": "Under the spreading chestnut tree / the village smithy stands.", "note": "Poetic prepositional setting."}, {"text": "Far across the valley / a solitary beacon / flickered in the dusk.", "pattern": "Far across the valley / a solitary beacon / flickered in the dusk.", "note": "Atmospheric description in three distinct beats."}, {"text": "With tears of joy in her eyes / she embraced her family.", "pattern": "With tears of joy in her eyes / she embraced her family.", "note": "Emotional adverbial chunk."}, {"text": "Deep in the enchanted forest / ancient trees / whispered in the wind.", "pattern": "Deep in the enchanted forest / ancient trees / whispered in the wind.", "note": "Storytelling pacing."}, {"text": "For further information / please visit our website / or contact customer service.", "pattern": "For further information / please visit our website / or contact customer service.", "note": "Business contact chunking."}, {"text": "Due to unforeseen weather conditions / the flight has been rescheduled.", "pattern": "Due to unforeseen weather conditions / the flight has been rescheduled.", "note": "Official transit announcement."}, {"text": "In case of emergency / proceed calmly / to the nearest exit.", "pattern": "In case of emergency / proceed calmly / to the nearest exit.", "note": "Safety instruction in three clear beats."}, {"text": "Please remain seated / until the aircraft / has come to a complete stop.", "pattern": "Please remain seated / until the aircraft / has come to a complete stop.", "note": "Flight crew announcement."}, {"text": "All passengers traveling with small children / may now board.", "pattern": "All passengers traveling with small children / may now board.", "note": "Boarding gate phrasing."}, {"text": "She took a deep breath / gathered her courage / and stepped onto the stage.", "pattern": "She took a deep breath / gathered her courage / and stepped onto the stage.", "note": "Tricolon of actions."}, {"text": "He opened the envelope / read the letter twice / and smiled quietly.", "pattern": "He opened the envelope / read the letter twice / and smiled quietly.", "note": "Sequential actions split by slight pauses."}, {"text": "We packed our bags / checked out of the room / and called a taxi.", "pattern": "We packed our bags / checked out of the room / and called a taxi.", "note": "Travel sequence."}, {"text": "They bought the land / designed the blueprint / and built their dream house.", "pattern": "They bought the land / designed the blueprint / and built their dream house.", "note": "Three major life steps."}, {"text": "I set the alarm / turned off the bedside lamp / and closed my eyes.", "pattern": "I set the alarm / turned off the bedside lamp / and closed my eyes.", "note": "Bedtime routine chunking."}, {"text": "Whatever happens tomorrow / we gave it our absolute best.", "pattern": "Whatever happens tomorrow / we gave it our absolute best.", "note": "Conditional reassurance."}, {"text": "No matter where you travel / always stay true to your roots.", "pattern": "No matter where you travel / always stay true to your roots.", "note": "Philosophical reminder."}, {"text": "Whenever you feel doubt / remember how far you have already come.", "pattern": "Whenever you feel doubt / remember how far you have already come.", "note": "Encouraging reflection."}, {"text": "Even though the path was steep / nobody complained / along the way.", "pattern": "Even though the path was steep / nobody complained / along the way.", "note": "Overcoming obstacles."}, {"text": "Provided that everyone agrees / we will proceed / with the initial plan.", "pattern": "Provided that everyone agrees / we will proceed / with the initial plan.", "note": "Administrative consensus."}, {"text": "By the time we arrived / the ceremony was over / and everyone had left.", "pattern": "By the time we arrived / the ceremony was over / and everyone had left.", "note": "Complex time relation."}, {"text": "As far as the eye could see / golden wheat / swayed in the breeze.", "pattern": "As far as the eye could see / golden wheat / swayed in the breeze.", "note": "Expansive landscape description."}, {"text": "In spite of their differences / they remained / lifelong friends.", "pattern": "In spite of their differences / they remained / lifelong friends.", "note": "Contrasting relationship."}, {"text": "To master natural English / you need patience / curiosity / and regular practice.", "pattern": "To master natural English / you need patience / curiosity / and regular practice.", "note": "Goal followed by a listed triad."}, {"text": "When the morning sun rose / the birds began their song / welcoming the day.", "pattern": "When the morning sun rose / the birds began their song / welcoming the day.", "note": "Graceful poetic closure."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published'),
('connected-speech', 'Consonant to vowel linking', 'beginner', 'medium', 'us', 'When a word ends in a consonant and the next starts with a vowel, join them into one sound group.', ARRAY['Never stop between the words.', 'The consonant becomes the start of the next word.']::text[], '[{"text": "pick it up", "pattern": "pi-ki-tup"}, {"text": "turn it off", "pattern": "tur-ni-toff"}, {"text": "an hour and a half", "pattern": "a-nou-ran-da-half"}, {"text": "look at it again", "pattern": "loo-ka-ti-ta-gain"}]'::jsonb, '', true, 1, 'published'),
('connected-speech', 'Vowel linking and intrusive sounds', 'intermediate', 'hard', 'us', 'Two vowels meeting need a small bridge: /w/, /j/ or /r/ appears naturally.', ARRAY['go on → go‿w‿on', 'I am → I‿y‿am', 'law and order → law‿r‿and order (British)']::text[], '[{"text": "go on", "pattern": "go-w-on"}, {"text": "I always do", "pattern": "I-y-always do"}, {"text": "the end of it", "pattern": "thee-y-end-of-it"}, {"text": "media event", "pattern": "media-r-event", "note": "Intrusive /r/ is common in British English."}]'::jsonb, '', true, 2, 'published'),
('connected-speech', 'Elision: sounds disappear', 'intermediate', 'medium', 'us', 'In fast speech some sounds simply drop out, especially /t/ and /d/ between consonants.', ARRAY['next day → nex'' day', 'friendship → frien''ship', 'must be → mus'' be']::text[], '[{"text": "next day", "pattern": "nex'' day"}, {"text": "I don''t know", "pattern": "I dunno / I don'' know"}, {"text": "most people", "pattern": "mos'' people"}, {"text": "sandwich", "pattern": "sanwich"}]'::jsonb, '', true, 3, 'published'),
('connected-speech', 'Assimilation: sounds change', 'advanced', 'hard', 'us', 'A sound can change to match the next one, so the mouth moves less.', ARRAY['ten bikes → tem bikes', 'did you → didjou', 'won''t you → wonchou']::text[], '[{"text": "ten bikes", "pattern": "tem bikes"}, {"text": "good boy", "pattern": "goob boy"}, {"text": "did you eat?", "pattern": "di-jou eat?"}, {"text": "won''t you come?", "pattern": "won-chou come?"}]'::jsonb, '', true, 4, 'published'),
('connected-speech', 'Contractions', 'beginner', 'easy', 'us', 'Natural spoken English uses contractions almost everywhere. Full forms sound formal or emphatic.', ARRAY['I am → I''m', 'I will → I''ll', 'do not → don''t', 'would have → would''ve']::text[], '[{"text": "I''m not sure yet.", "pattern": "I''m = I am"}, {"text": "I''ll call you later.", "pattern": "I''ll = I will"}, {"text": "She doesn''t live here.", "pattern": "doesn''t = does not"}, {"text": "We''d have told you.", "pattern": "we''d have = we would have"}]'::jsonb, '', true, 5, 'published'),
('connected-speech', 'Weak forms', 'intermediate', 'medium', 'us', 'Small grammar words lose their full vowel and become a schwa when they are not stressed.', ARRAY['to → /tə/', 'for → /fə/', 'and → /ən/', 'can → /kən/', 'of → /əv/', 'a → /ə/', 'the → /ðə/']::text[], '[{"text": "a cup of tea", "pattern": "a cup /əv/ tea"}, {"text": "fish and chips", "pattern": "fish /ən/ chips"}, {"text": "I have to go", "pattern": "I have /tə/ go"}, {"text": "It''s for you", "pattern": "it''s /fə/ you"}, {"text": "I can help", "pattern": "I /kən/ help", "note": "Stressed ''can'' /kæn/ means emphasis."}]'::jsonb, '', false, 6, 'published'),
('connected-speech', 'Linking identical consonants', 'advanced', 'hard', 'us', 'When one word ends and the next begins with the same consonant sound, don''t say it twice — hold it once, a little longer.', '{}'::text[], '[{"text": "big game", "pattern": "bi-game (one long /g/)"}, {"text": "black cat", "pattern": "bla-cat (one long /k/)"}, {"text": "some more", "pattern": "so-more (one long /m/)"}]'::jsonb, '', false, 7, 'published'),
('connected-speech', 'Linking /r/ in British English', 'advanced', 'hard', 'uk', 'In non-rhotic British English, a silent final ''r'' becomes pronounced when the next word starts with a vowel.', '{}'::text[], '[{"text": "far away", "pattern": "fa-r-away"}, {"text": "here and there", "pattern": "hea-r-and there"}, {"text": "better off", "pattern": "bette-r-off"}]'::jsonb, '', false, 8, 'published'),
('connected-speech', 'Reduced auxiliary verbs in questions', 'intermediate', 'medium', 'us', 'Auxiliary verbs at the start of questions often reduce heavily in fast, casual speech.', '{}'::text[], '[{"text": "Did you eat?", "pattern": "D''you eat? / Ju eat?"}, {"text": "Do you want some?", "pattern": "D''you want some?"}, {"text": "Have you seen it?", "pattern": "Ave you seen it?"}]'::jsonb, '', false, 9, 'published'),
('connected-speech', 'Linking across three-word phrases', 'advanced', 'hard', 'us', 'Longer phrases link across every word boundary, not just the first pair — practise the whole chain.', '{}'::text[], '[{"text": "as soon as possible", "pattern": "a-soo-nas-possible"}, {"text": "one of a kind", "pattern": "wu-nuh-va-kind"}, {"text": "out of order", "pattern": "ou-tuh-vorder"}]'::jsonb, '', false, 10, 'published'),
('connected-speech', 'Connected speech with ''going to''', 'beginner', 'easy', 'us', '''Going to'' before a verb almost always links and reduces in natural speech.', '{}'::text[], '[{"text": "I''m going to leave soon.", "pattern": "I''m gonna leave soon."}, {"text": "What are you going to do?", "pattern": "What''re ya gonna do?"}, {"text": "It''s going to rain.", "pattern": "It''s gonna rain."}]'::jsonb, '', false, 11, 'published'),
('connected-speech', 'Connected speech in fast greetings', 'beginner', 'easy', 'us', 'Very common greeting phrases are almost always run together in natural speech.', '{}'::text[], '[{"text": "What''s up?", "pattern": "Whatsup? / Wassup?"}, {"text": "How''s it going?", "pattern": "Howzitgoing?"}, {"text": "See you later.", "pattern": "See ya later."}]'::jsonb, '', false, 12, 'published'),
('connected-speech', 'Linking with plural and possessive ''s''', 'intermediate', 'medium', 'us', 'The final ''s'' sound links smoothly into the next word''s vowel, just like any other consonant.', '{}'::text[], '[{"text": "my friends and I", "pattern": "my frien-zan-dI"}, {"text": "the books are here", "pattern": "the boo-ksar here"}, {"text": "it''s easy", "pattern": "i-tsee-zy"}]'::jsonb, '', false, 13, 'published'),
('connected-speech', 'Practice: a fast connected-speech paragraph', 'advanced', 'hard', 'us', 'Put it all together — link, reduce and contract naturally across a whole mini-paragraph.', '{}'::text[], '[{"text": "I was gonna call you, but I didn''t have time — I''ll try to get in touch later on, okay?", "pattern": "gonna / didn'' have / I''ll / touch-later-on"}]'::jsonb, '', false, 14, 'published'),
('connected-speech', 'H-dropping in weak pronouns', 'advanced', 'hard', 'us', 'Unstressed ''him'', ''her'' and ''his'' often drop the /h/ sound completely and link to the word before.', '{}'::text[], '[{"text": "Tell him to call me.", "pattern": "Tell-im to call me."}, {"text": "Give her the keys.", "pattern": "Give-er the keys."}, {"text": "Ask his brother.", "pattern": "Ask-is brother."}]'::jsonb, '', false, 15, 'published'),
('connected-speech', 'Glottal stop replacing /t/', 'advanced', 'hard', 'uk', 'Before certain consonants, /t/ is often replaced with a quick catch in the throat instead of a clear tongue-tap.', '{}'::text[], '[{"text": "football", "pattern": "foo''ball", "note": "The /t/ becomes a glottal stop."}, {"text": "Gatwick", "pattern": "Ga''wick"}, {"text": "that one", "pattern": "tha'' one"}]'::jsonb, '', false, 16, 'published'),
('connected-speech', 'Linking -ing forms into the next vowel', 'intermediate', 'medium', 'us', 'An -ing verb ending in a consonant sound links smoothly into a following vowel, just like any other word-final consonant.', '{}'::text[], '[{"text": "going out", "pattern": "goin-gout"}, {"text": "working out", "pattern": "workin-gout"}, {"text": "coming in", "pattern": "comin-gin"}]'::jsonb, '', false, 17, 'published'),
('connected-speech', 'Connected speech in dates', 'intermediate', 'medium', 'us', 'Dates link and reduce heavily in natural speech — ''of'' almost disappears.', '{}'::text[], '[{"text": "the fourth of July", "pattern": "the fourth-uh-July"}, {"text": "the first of the month", "pattern": "the first-uh-the month"}]'::jsonb, '', false, 18, 'published'),
('connected-speech', 'Connected speech with modal + have', 'advanced', 'hard', 'us', 'Modal verbs followed by ''have'' link and reduce so heavily that ''have'' sounds like ''of'' to many learners — that''s just how it''s linked, not actually spelled that way.', '{}'::text[], '[{"text": "I should have known.", "pattern": "I shoulda known."}, {"text": "You must have forgotten.", "pattern": "You musta forgotten."}, {"text": "They might have left already.", "pattern": "They mighta left already."}]'::jsonb, '', false, 19, 'published'),
('connected-speech', 'Connected speech in weather talk', 'beginner', 'easy', 'us', 'Common weather phrases link smoothly across word boundaries just like any other everyday speech.', '{}'::text[], '[{"text": "It''s gonna rain later.", "pattern": "It''s gonna rain later."}, {"text": "It''s kind of cloudy out.", "pattern": "It''s kinda cloudy out."}]'::jsonb, '', false, 20, 'published'),
('connected-speech', 'Linking in business phone phrases', 'intermediate', 'medium', 'us', 'Common office phone phrases link naturally across word boundaries — practise them as whole chunks.', '{}'::text[], '[{"text": "I''ll put you through.", "pattern": "I''ll pu-chu through."}, {"text": "Can I take a message?", "pattern": "Ca-nI take a message?"}, {"text": "He''s out of the office.", "pattern": "He''s ou-tuv the office."}]'::jsonb, '', false, 21, 'published'),
('connected-speech', 'Connected speech practice: a second fast paragraph', 'advanced', 'hard', 'us', 'A second full-paragraph challenge — link, reduce and contract across the whole thing.', '{}'::text[], '[{"text": "I would''ve told you sooner, but I kinda forgot — I guess I''ve had a lot going on lately.", "pattern": "would''ve / kinda / I''ve / going-on"}]'::jsonb, '', false, 22, 'published'),
('connected-speech', 'Linking with ''a lot of''', 'beginner', 'easy', 'us', '''A lot of'' is one of the most common linked phrases in English — practise it as a single unit.', '{}'::text[], '[{"text": "I have a lot of work today.", "pattern": "a-lotta work"}, {"text": "There''s a lot of traffic.", "pattern": "a-lotta traffic"}]'::jsonb, '', false, 23, 'published'),
('connected-speech', 'Connected speech in song lyrics', 'intermediate', 'medium', 'us', 'Song lyrics are full of natural connected speech — great, memorable practice material.', '{}'::text[], '[{"text": "I wanna hold your hand.", "pattern": "wanna hold your hand"}, {"text": "Don''t you wanna dance with somebody?", "pattern": "don-chu wanna dance"}]'::jsonb, '', false, 24, 'published'),
('connected-speech', 'Reduced ''because'' in casual speech', 'intermediate', 'medium', 'us', '''Because'' commonly reduces to ''cause'' or ''cuz'' in relaxed conversation, and links straight into the next word.', '{}'::text[], '[{"text": "I''m tired because I stayed up late.", "pattern": "''cause I stayed up late"}, {"text": "She''s upset ''cause of what happened.", "pattern": "''cause-uv what happened"}]'::jsonb, '', false, 25, 'published'),
('connected-speech', 'Linking with plural verb forms', 'intermediate', 'medium', 'us', 'Verb endings link into the next word exactly the same way noun endings do.', '{}'::text[], '[{"text": "She likes it a lot.", "pattern": "like-si-ta lot"}, {"text": "He works every day.", "pattern": "work-severy day"}]'::jsonb, '', false, 26, 'published'),
('connected-speech', 'Connected speech across a short dialogue', 'advanced', 'hard', 'us', 'Real conversation links across every turn, not just within one speaker''s sentence.', '{}'::text[], '[{"text": "A: Wanna grab a bite? B: Yeah, gimme a sec, I''m almost done.", "pattern": "wanna / gimme / I''m"}]'::jsonb, '', false, 27, 'published'),
('connected-speech', 'Reduced ''them'' as ''em', 'advanced', 'medium', 'us', '''Them'' frequently reduces to ''em (dropping the ''th'') and links straight onto the verb before it.', '{}'::text[], '[{"text": "Tell them I said hi.", "pattern": "Tell-em I said hi."}, {"text": "I already gave them the news.", "pattern": "I already gave-em the news."}]'::jsonb, '', false, 28, 'published'),
('connected-speech', 'Linking with numbers before nouns', 'intermediate', 'medium', 'us', 'Numbers link into the noun that follows exactly like any consonant-to-vowel or consonant-to-consonant pair.', '{}'::text[], '[{"text": "one hour", "pattern": "wu-nour"}, {"text": "eight apples", "pattern": "eigh-tapples"}]'::jsonb, '', false, 29, 'published'),
('connected-speech', 'Linking prepositions of place', 'intermediate', 'medium', 'us', 'Common location phrases link fully across every word boundary — practise them as one chunk.', '{}'::text[], '[{"text": "in front of", "pattern": "in-fron-tuv"}, {"text": "next to it", "pattern": "nex-tooit"}, {"text": "on top of", "pattern": "on-toppuv"}]'::jsonb, '', false, 30, 'published'),
('connected-speech', '''There''s a'' and ''there''s an'' linking', 'beginner', 'easy', 'us', '''There''s'' links tightly onto the word that follows, especially before ''a lot of''.', '{}'::text[], '[{"text": "There''s a lot of traffic today.", "pattern": "There''s-a-lotta traffic today."}, {"text": "There''s an easier way to do this.", "pattern": "There''s-an-easier way to do this."}]'::jsonb, '', false, 31, 'published'),
('connected-speech', 'Negative auxiliary linking', 'intermediate', 'medium', 'us', 'Negative contractions link straight into the next word just like any consonant ending.', '{}'::text[], '[{"text": "I don''t understand.", "pattern": "I don-tunderstand."}, {"text": "It isn''t easy.", "pattern": "it isn-teasy."}, {"text": "We can''t afford it.", "pattern": "we can-tafford it."}]'::jsonb, '', false, 32, 'published'),
('connected-speech', 'Linking numbers with ''and''', 'intermediate', 'medium', 'us', '''And'' between number parts reduces to a quick /ən/ and links both sides together.', '{}'::text[], '[{"text": "one hundred and one", "pattern": "one hundred-ən-one"}, {"text": "two thousand and five", "pattern": "two thousand-ən-five"}]'::jsonb, '', false, 33, 'published'),
('connected-speech', 'Connected speech in casual excuses', 'intermediate', 'medium', 'us', 'Excuse phrases are said fast and casually, with heavy linking and reduction.', '{}'::text[], '[{"text": "Sorry, I gotta run, I''m late for something.", "pattern": "gotta run / I''m late"}, {"text": "I was gonna text you but I forgot.", "pattern": "gonna text / forgot"}]'::jsonb, '', false, 34, 'published'),
('connected-speech', '''Of course'' and ''kind of'' reduced linking', 'intermediate', 'medium', 'us', 'These extremely common phrases reduce and link so much they barely resemble their spelling.', '{}'::text[], '[{"text": "Of course I''ll help you.", "pattern": "uh-course I''ll help you."}, {"text": "It''s kind of a big deal.", "pattern": "it''s kinda-vuh big deal."}]'::jsonb, '', false, 35, 'published'),
('connected-speech', 'Connected speech in fast sports commentary', 'advanced', 'hard', 'us', 'Live commentary links almost every word together at high speed — great advanced listening/speaking practice.', '{}'::text[], '[{"text": "He''s got it, he''s through, and he scores!", "pattern": "got-it / through-and / scores"}]'::jsonb, '', false, 36, 'published'),
('connected-speech', 'Linking with ''going to have to''', 'advanced', 'hard', 'us', 'This whole obligation phrase links and reduces into a single fast chunk in natural speech.', '{}'::text[], '[{"text": "We''re going to have to reschedule.", "pattern": "gonna hafta reschedule"}, {"text": "I''m gonna have to think about it.", "pattern": "gonna hafta think about it"}]'::jsonb, '', false, 37, 'published'),
('connected-speech', 'Casual ''your'' reduced to ''yer''', 'advanced', 'medium', 'us', 'Unstressed ''your'' often reduces to a quick ''yer'' sound and links onto the next word.', '{}'::text[], '[{"text": "What''s yer name?", "pattern": "What''s yer name?"}, {"text": "Is that yer bag?", "pattern": "Is that yer bag?"}]'::jsonb, 'Very informal spoken only.', false, 38, 'published'),
('connected-speech', 'Connected speech in polite offers', 'beginner', 'easy', 'us', 'Everyday offer phrases link smoothly across the whole sentence.', '{}'::text[], '[{"text": "Do you want a cup of coffee?", "pattern": "wanna cuppa coffee?"}, {"text": "Can I get you anything?", "pattern": "Can-I get-choo anything?"}]'::jsonb, '', false, 39, 'published'),
('connected-speech', 'Linking with ''used to'' in narration', 'intermediate', 'medium', 'us', '''Used to'' links tightly and reduces when telling stories about the past.', '{}'::text[], '[{"text": "I used to live in Paris.", "pattern": "I yoosta live in Paris."}, {"text": "We used to go there every summer.", "pattern": "We yoosta go there every summer."}]'::jsonb, '', false, 40, 'published'),
('connected-speech', 'Connected speech with double consonants across words', 'advanced', 'hard', 'us', 'When a word ends and the next begins with a similar (not identical) sound, they still often blend rather than being said as two separate sounds.', '{}'::text[], '[{"text": "good day", "pattern": "goo-day (one held /d/)"}, {"text": "that time", "pattern": "tha-time (one held /t/)"}]'::jsonb, '', false, 41, 'published'),
('connected-speech', 'Connected speech in a customer-service phrase set', 'intermediate', 'medium', 'us', 'Common service-industry phrases link naturally across the whole sentence.', '{}'::text[], '[{"text": "Is there anything else I can help you with?", "pattern": "anything-else / help-you-with"}, {"text": "Thanks for calling, have a great day.", "pattern": "thanks-for / have-a-great-day"}]'::jsonb, '', false, 42, 'published'),
('connected-speech', 'Connected speech: final review paragraph', 'advanced', 'hard', 'us', 'One more full-paragraph challenge pulling together linking, elision, assimilation and weak forms all at once.', '{}'::text[], '[{"text": "I gotta admit, I kinda forgot we were supposed to meet — sorry ''bout that, I shoulda texted you.", "pattern": "gotta / kinda / supposed to / ''bout / shoulda"}]'::jsonb, '', false, 43, 'published'),
('connected-speech', 'Linking with ''as well as''', 'advanced', 'hard', 'us', 'This common linking phrase runs together into one smooth unit.', '{}'::text[], '[{"text": "He speaks French as well as English.", "pattern": "az-well-az English"}, {"text": "It''s fast as well as reliable.", "pattern": "fast-az-well-az reliable"}]'::jsonb, '', false, 44, 'published'),
('connected-speech', '''Except for'' reduced linking', 'advanced', 'hard', 'us', '''Except for'' links tightly, with the final /t/ often barely released before ''for''.', '{}'::text[], '[{"text": "Everyone came except for Tom.", "pattern": "excep-for Tom"}, {"text": "It''s ready, except for the last page.", "pattern": "excep-for the last page"}]'::jsonb, '', false, 45, 'published'),
('connected-speech', 'Connected speech making casual plans', 'intermediate', 'medium', 'us', 'Everyday planning phrases link and reduce heavily in relaxed conversation.', '{}'::text[], '[{"text": "Let''s meet up around seven.", "pattern": "let''s meet-up around seven"}, {"text": "Wanna grab lunch sometime this week?", "pattern": "wanna grab lunch sometime this week"}]'::jsonb, '', false, 46, 'published'),
('connected-speech', 'Linking across a movie-trailer style line', 'advanced', 'hard', 'us', 'Dramatic narration still links every word together — the drama is in the pacing, not gaps between words.', '{}'::text[], '[{"text": "In a world where anything is possible, one man has to make a choice.", "pattern": "in-a-world / anything-is / has-to"}]'::jsonb, '', false, 47, 'published'),
('connected-speech', 'Connected speech with ''gonna'' plus different pronouns', 'intermediate', 'medium', 'us', '''Gonna'' links the same way regardless of which pronoun comes before it.', '{}'::text[], '[{"text": "She''s gonna love this.", "pattern": "she''s gonna love this"}, {"text": "They''re gonna be so happy.", "pattern": "they''re gonna be so happy"}, {"text": "We''re gonna figure it out.", "pattern": "we''re gonna figure it out"}]'::jsonb, '', false, 48, 'published'),
('connected-speech', 'Connected speech: final mixed review', 'advanced', 'hard', 'us', 'One last full-sentence challenge mixing linking, weak forms and reductions together.', '{}'::text[], '[{"text": "I shoulda called you as soon as I found out, but I kinda wanted to check the details first.", "pattern": "shoulda / as-soon-as / kinda / wanted-to"}]'::jsonb, '', false, 49, 'published'),
('connected-speech', 'Final mixed linking review', 'advanced', 'hard', 'us', 'One closing set combining consonant-vowel linking, elision and a weak form all in one line.', '{}'::text[], '[{"text": "I want to ask about it later.", "pattern": "wanna ask-a-bou-tit later"}]'::jsonb, '', false, 50, 'published'),
('connected-speech', 'Practice', 'intermediate', 'medium', 'us', 'Master connected speech across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "turn it on", "pattern": "tur-ni-ton", "note": "Consonant-to-vowel: /n/ links directly into ''it'' and ''on''."}, {"text": "check it out", "pattern": "che-ki-tout", "note": "Consonant /k/ links to ''it'', and flap /t/ links into ''out''."}, {"text": "hold on a minute", "pattern": "hol-do-na-min-ute", "note": "Chained consonant-to-vowel links create seamless flow."}, {"text": "put on your shoes", "pattern": "pu-ton-your-shoes", "note": "Flap /t/ links into ''on''."}, {"text": "tell him the truth", "pattern": "tel-lim the truth", "note": "Pronoun reduction: the /h/ drops in rapid speech."}, {"text": "ask her later", "pattern": "as-ker la-ter", "note": "H-dropping: /k/ links directly into /ɜr/."}, {"text": "give it to me", "pattern": "gi-vi-tə-me", "note": "/v/ links into ''it''; ''to'' reduces to /tə/."}, {"text": "leave it alone", "pattern": "lea-vi-ta-lone", "note": "Smooth linking of final consonants into vowels."}, {"text": "not at all", "pattern": "no-ta-tall", "note": "Classic British or American flap-linked phrase."}, {"text": "first of all", "pattern": "firs-tə-vall", "note": "Seamless consonant-to-vowel cascade."}, {"text": "go out", "pattern": "go-[w]-out", "note": "Intrusive /w/ smooths the transition between two rounded vowels."}, {"text": "do it now", "pattern": "do-[w]-it now", "note": "Intrusive /w/ bridges /uː/ and /ɪ/."}, {"text": "two apples", "pattern": "two-[w]-apples", "note": "Insert a subtle /w/ glide between vowels."}, {"text": "you are right", "pattern": "you-[w]-are right", "note": "Natural /w/ glide connects ''you'' and ''are''."}, {"text": "so easy", "pattern": "so-[w]-easy", "note": "Subtle /w/ glide avoids an abrupt glottal stop."}, {"text": "I see it", "pattern": "I see-[j]-it", "note": "Intrusive /j/ bridges the high front vowels."}, {"text": "she asked", "pattern": "she-[j]-asked", "note": "Natural /j/ glide between /iː/ and /æ/."}, {"text": "three hours", "pattern": "three-[j]-hours", "note": "Subtle /j/ glide prevents hiatus."}, {"text": "they agree", "pattern": "they-[j]-agree", "note": "Diphthong /eɪ/ links via /j/ into /ə/."}, {"text": "we understand", "pattern": "we-[j]-understand", "note": "/j/ glide creates effortless continuity."}, {"text": "clean never", "pattern": "clea(n)ever", "note": "Twin consonant: hold the /n/ slightly longer without releasing twice."}, {"text": "bad day", "pattern": "ba[d]-day", "note": "Geminate /d/: stop the airflow once and release on ''day''."}, {"text": "black coffee", "pattern": "bla[k]-coffee", "note": "Twin /k/: do not release the first /k/ before starting ''coffee''."}, {"text": "hot tea", "pattern": "ho[t]-tea", "note": "Twin /t/: one elongated closure, single release."}, {"text": "stop pushing", "pattern": "sto[p]-pushing", "note": "Twin /p/: hold the lips closed through both words."}, {"text": "nice smile", "pattern": "ni[s]-smile", "note": "Continuous /s/: elongate the friction seamlessly."}, {"text": "some money", "pattern": "so[m]-money", "note": "Twin /m/: hold the nasal murmur smoothly."}, {"text": "part time", "pattern": "par[t]-time", "note": "Single extended stop on the alveolar ridge."}, {"text": "right turn", "pattern": "righ[t]-turn", "note": "Hold the closure on ''right'' and release into ''turn''."}, {"text": "look closer", "pattern": "loo[k]-closer", "note": "Twin /k/: hold velar closure without a separate burst."}, {"text": "what you need", "pattern": "wha-chu need", "note": "Palatalization: /t/ + /j/ merges into /tʃ/."}, {"text": "did you see it", "pattern": "di-joo see it", "note": "Palatalization: /d/ + /j/ merges into /dʒ/."}, {"text": "don''t you know", "pattern": "don-chu know", "note": "/t/ + /j/ blends smoothly into /tʃ/."}, {"text": "would you help", "pattern": "woo-joo help", "note": "/d/ + /j/ blends into /dʒ/."}, {"text": "can''t you hear me", "pattern": "can-chu hear me", "note": "/t/ + /j/ assimilation."}, {"text": "meet you at six", "pattern": "mee-choo at six", "note": "Rapid speech assimilation of /t/ and /j/."}, {"text": "told you so", "pattern": "tol-joo so", "note": "/d/ + /j/ blends into /dʒ/ in conversational speech."}, {"text": "bless you", "pattern": "ble-shoo", "note": "/s/ + /j/ assimilates to /ʃ/."}, {"text": "miss you", "pattern": "mi-shoo", "note": "/s/ + /j/ becomes /ʃ/ in fast speech."}, {"text": "is that your car", "pattern": "is tha-chur car", "note": "/t/ + /j/ palatalization across word boundary."}, {"text": "last night", "pattern": "las'' night", "note": "Elision: /t/ drops between consonants /s/ and /n/."}, {"text": "next door", "pattern": "nex'' door", "note": "Elision: /t/ is omitted between /ks/ and /d/."}, {"text": "fast train", "pattern": "fas'' train", "note": "/t/ is elided before /tr/."}, {"text": "best friend", "pattern": "bes'' friend", "note": "/t/ disappears between /s/ and /f/."}, {"text": "stand there", "pattern": "stan'' there", "note": "/d/ drops between nasal /n/ and dental /ð/."}, {"text": "diamond ring", "pattern": "diamon'' ring", "note": "/d/ drops between /n/ and /r/ in rapid speech."}, {"text": "soft music", "pattern": "sof'' music", "note": "/t/ is dropped between /f/ and /m/."}, {"text": "take a break", "pattern": "tay-kuh break", "note": "Consonant-to-vowel link with reduced ''a''."}, {"text": "step aside", "pattern": "ste-pa-side", "note": "Smooth link of final /p/ directly into initial /ə/."}, {"text": "hand over the keys", "pattern": "han-do-ver the keys", "note": "Consonant-to-vowel link /d/ into ''over''."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published'),
('fluency', 'Natural speaking speed', 'beginner', 'easy', 'us', 'Comfortable conversational English is roughly 120–160 words a minute. Slower is fine; long silent gaps are what hurt.', ARRAY['Speak in chunks, not word by word.', 'Keep moving instead of restarting sentences.']::text[], '[{"text": "I usually get up around seven, have a quick breakfast, and then start work.", "pattern": "3 chunks, one breath each"}, {"text": "It''s hard to say, because it really depends on the day.", "pattern": "2 chunks"}, {"text": "I''ve been learning English for about three years now.", "pattern": "1 chunk"}]'::jsonb, '', true, 1, 'published'),
('fluency', 'Useful fillers and linking ideas', 'intermediate', 'medium', 'us', 'A short natural filler buys thinking time. Silence and ''uhhh'' do not.', ARRAY['Thinking time: well… / let me think… / actually…', 'Softening: I mean… / you know… / basically…', 'Linking: so / because of that / on top of that / that''s why']::text[], '[{"text": "Well, that''s a good question. Let me think for a second.", "pattern": "buy time politely"}, {"text": "Actually, I changed my mind about that.", "pattern": "signal a correction"}, {"text": "I mean, it''s not perfect, but it works.", "pattern": "soften an opinion"}, {"text": "So basically, that''s why I moved to Canada.", "pattern": "link and conclude"}]'::jsonb, 'Use one filler, not five. Repeating ''you know'' every sentence lowers your score in speaking exams.', true, 2, 'published'),
('fluency', 'Self-correcting smoothly', 'intermediate', 'medium', 'us', 'Fluent speakers correct themselves without stopping completely — a small phrase bridges the fix.', ARRAY['I mean...', 'sorry, I meant...', 'or rather...']::text[], '[{"text": "I went there on Tuesday — sorry, I meant Wednesday.", "pattern": "smooth self-correction"}, {"text": "She''s my colleague — I mean, my manager now.", "pattern": "smooth self-correction"}, {"text": "It costs about, or rather, exactly fifty dollars.", "pattern": "smooth self-correction"}]'::jsonb, '', true, 3, 'published'),
('fluency', 'Paraphrasing when you don''t know a word', 'advanced', 'hard', 'us', 'Fluent speakers keep talking by describing around a missing word instead of stopping.', '{}'::text[], '[{"text": "It''s the thing you use to open a bottle... a bottle opener.", "pattern": "describe, then land on the word"}, {"text": "You know, the place where you borrow books... a library.", "pattern": "describe, then land on the word"}]'::jsonb, '', true, 4, 'published'),
('fluency', 'Keeping momentum in long answers', 'advanced', 'hard', 'us', 'In a 2-minute IELTS-style answer, keep adding ideas instead of stopping once you run out of a script.', ARRAY['Add an example.', 'Add a reason.', 'Add a comparison.']::text[], '[{"text": "I really enjoy hiking — for example, last month I went up a mountain near my hometown, which was tiring but incredibly rewarding.", "pattern": "idea + example + result, no stop"}]'::jsonb, '', true, 5, 'published'),
('fluency', 'Avoiding word-by-word translation habits', 'advanced', 'hard', 'us', 'Translating word by word in your head causes hesitation. Practise whole natural chunks instead of single words.', '{}'::text[], '[{"text": "on the other hand", "pattern": "one fixed chunk, not 4 separate words"}, {"text": "as far as I know", "pattern": "one fixed chunk"}, {"text": "to be honest with you", "pattern": "one fixed chunk"}]'::jsonb, '', false, 6, 'published'),
('fluency', 'Recovering from a mistake without stopping', 'intermediate', 'medium', 'us', 'A small grammar mistake doesn''t need a full stop — fluent speakers just keep going.', '{}'::text[], '[{"text": "She go— she goes to work every day.", "pattern": "quick self-fix, keep moving"}, {"text": "I have seen— I saw that movie last week.", "pattern": "quick self-fix, keep moving"}]'::jsonb, '', false, 7, 'published'),
('fluency', 'Fluency in answering unexpected questions', 'advanced', 'hard', 'us', 'When surprised by a question, a short buying-time phrase keeps you fluent while you think.', '{}'::text[], '[{"text": "That''s an interesting question — I haven''t really thought about it before, but I''d say...", "pattern": "buy time, then answer"}, {"text": "Hmm, let me think about that for a moment...", "pattern": "buy time, then answer"}]'::jsonb, '', false, 8, 'published'),
('fluency', 'Strategic pausing vs hesitation', 'advanced', 'hard', 'us', 'A brief, silent pause at a natural chunk boundary sounds confident; a pause mid-chunk filled with ''um'' sounds hesitant.', ARRAY['Pause between chunks, not inside them.', 'A silent pause is often better than a filler.']::text[], '[{"text": "I think... (pause) ...the biggest challenge is time management.", "pattern": "pause between chunks = confident"}, {"text": "I th-th-think the biggest um challenge is uh time management.", "pattern": "pauses inside words = hesitant"}]'::jsonb, '', false, 9, 'published'),
('fluency', 'Signposting language for structured answers', 'advanced', 'hard', 'us', 'Signposting phrases make a long answer easy to follow and sound organized, common in IELTS Part 3.', ARRAY['First of all... / Another point is... / Finally...']::text[], '[{"text": "First of all, it saves time. Another point is that it''s cheaper. Finally, it''s better for the environment.", "pattern": "clear signposted structure"}]'::jsonb, '', false, 10, 'published'),
('fluency', 'Sustaining a two-minute answer', 'advanced', 'hard', 'us', 'Keep a long answer going by adding a reason, then an example, then a result — never just stop after one sentence.', '{}'::text[], '[{"text": "I''d like to talk about my hometown. It''s a small coastal town, which means the weather is mild all year. Because of that, a lot of tourists visit in summer, which has really boosted the local economy.", "pattern": "topic + detail + reason + result, no stop"}]'::jsonb, '', false, 11, 'published'),
('fluency', 'Transition phrases between topics', 'intermediate', 'medium', 'us', 'Smooth transitions keep the flow going when moving from one idea to a related one.', ARRAY['Speaking of which... / That reminds me... / On a related note...']::text[], '[{"text": "Speaking of which, that reminds me of something similar that happened to me.", "pattern": "smooth topic transition"}, {"text": "On a related note, I''ve also noticed the same thing at work.", "pattern": "smooth topic transition"}]'::jsonb, '', false, 12, 'published'),
('fluency', 'Speed control: deliberately slow vs natural fast', 'intermediate', 'medium', 'us', 'Practise the same sentence at two speeds — slow and clear is fine, but avoid a flat, robotic pace either way.', '{}'::text[], '[{"text": "I really enjoy learning new languages.", "pattern": "slow: clear, each word separate but chunked"}, {"text": "I really enjoy learning new languages.", "pattern": "natural: chunked, linked, normal speed"}]'::jsonb, '', false, 13, 'published'),
('fluency', 'Fluency describing a picture or photo', 'advanced', 'hard', 'us', 'Picture description needs constant forward momentum — keep noticing and adding new details instead of stalling.', '{}'::text[], '[{"text": "In this photo, I can see a family having a picnic in the park. They seem to be enjoying the sunny weather, and there''s a dog playing nearby.", "pattern": "keep noticing new details, no stop"}]'::jsonb, '', false, 14, 'published'),
('fluency', 'Fluency summarizing what someone said', 'intermediate', 'medium', 'us', 'Summarizing fluently uses a short lead-in phrase, then the compressed main point.', ARRAY['So basically... / In short... / Long story short...']::text[], '[{"text": "So basically, they''re saying the project is delayed until next month.", "pattern": "smooth summary lead-in"}, {"text": "Long story short, we ended up missing the flight.", "pattern": "smooth summary lead-in"}]'::jsonb, '', false, 15, 'published'),
('fluency', 'Giving a quick opinion without preparation', 'intermediate', 'medium', 'us', 'When asked for an instant opinion, a short buy-time phrase plus a direct answer keeps you fluent.', '{}'::text[], '[{"text": "Off the top of my head, I''d say it''s probably a good idea.", "pattern": "buy time + direct opinion"}, {"text": "My gut feeling is that it won''t work, honestly.", "pattern": "buy time + direct opinion"}]'::jsonb, '', false, 16, 'published'),
('fluency', 'Fluency in quick agreement or disagreement', 'beginner', 'easy', 'us', 'Fast, natural back-and-forth conversation needs quick, confident reactions without long pauses.', '{}'::text[], '[{"text": "Totally agree — that''s exactly what I was thinking.", "pattern": "instant, confident agreement"}, {"text": "I see what you mean, but I''m not totally convinced.", "pattern": "instant, confident disagreement"}]'::jsonb, '', false, 17, 'published'),
('fluency', 'Telling a short story or joke fluently', 'advanced', 'hard', 'us', 'Jokes and short stories need very smooth timing — a bad pause right before the punchline kills the effect.', '{}'::text[], '[{"text": "So this guy walks into a bar, and the bartender says, ''Why the long face?''", "pattern": "smooth setup, no gaps, land the punchline"}]'::jsonb, '', false, 18, 'published'),
('fluency', 'Fluency explaining a process without stopping', 'intermediate', 'medium', 'us', 'Explaining how to do something needs steady forward momentum from step to step.', '{}'::text[], '[{"text": "So basically, you open the app, log in with your email, and then you just follow the steps on screen.", "pattern": "no stops between steps"}]'::jsonb, '', false, 19, 'published'),
('fluency', 'Avoiding literal translation: more chunks', 'advanced', 'hard', 'us', 'More natural fixed chunks to use as whole units instead of building them word by word.', '{}'::text[], '[{"text": "at the end of the day", "pattern": "one chunk, not 6 separate words"}, {"text": "when it comes to", "pattern": "one chunk"}, {"text": "the thing is", "pattern": "one chunk"}]'::jsonb, '', false, 20, 'published'),
('fluency', 'Fluency handling an interruption', 'advanced', 'hard', 'us', 'When interrupted, a fluent speaker briefly yields, then smoothly picks the thread back up.', '{}'::text[], '[{"text": "Sure, go ahead — as I was saying, the main issue is cost.", "pattern": "yield, then resume smoothly"}]'::jsonb, '', false, 21, 'published'),
('fluency', 'Fluency giving quick advice', 'intermediate', 'medium', 'us', 'Quick advice uses a short lead-in and a direct suggestion, without over-thinking.', ARRAY['If I were you... / You might want to... / Why not just...']::text[], '[{"text": "If I were you, I''d just ask for a refund.", "pattern": "fast, direct advice"}, {"text": "You might want to double check that first.", "pattern": "fast, direct advice"}]'::jsonb, '', false, 22, 'published'),
('fluency', 'Fluency expressing empathy', 'intermediate', 'medium', 'us', 'Empathetic responses flow naturally without long pauses, showing you''re genuinely listening.', '{}'::text[], '[{"text": "Oh no, that sounds really stressful, I''m sorry.", "pattern": "smooth, immediate empathy"}, {"text": "That must have been so difficult for you.", "pattern": "smooth, immediate empathy"}]'::jsonb, '', false, 23, 'published'),
('fluency', 'Fluency discussing a hypothetical scenario', 'advanced', 'hard', 'us', 'Hypothetical discussions (''what if...'') need smooth continuation through the imagined consequences.', '{}'::text[], '[{"text": "If everyone worked from home, I think traffic would drop a lot, and people would probably have more free time too.", "pattern": "smooth chain of consequences, no stop"}]'::jsonb, '', false, 24, 'published'),
('fluency', 'Fluency in a debate rebuttal', 'advanced', 'hard', 'us', 'Responding to a counter-argument fluently starts by briefly acknowledging it, then moving straight to your point.', '{}'::text[], '[{"text": "That''s true, but I''d argue the benefits still outweigh the risks.", "pattern": "acknowledge, pivot, no stop"}]'::jsonb, '', false, 25, 'published'),
('fluency', 'Fluent self-introduction', 'beginner', 'easy', 'us', 'A well-practised self-introduction should flow as one smooth unit, not separate rehearsed facts.', '{}'::text[], '[{"text": "Hi, I''m Anna, I''m from Vietnam, and I work as a graphic designer.", "pattern": "one smooth flowing introduction"}]'::jsonb, '', false, 26, 'published'),
('fluency', 'Fluency narrating a personal anecdote', 'advanced', 'hard', 'us', 'A good anecdote flows through setup, event and reaction without breaking momentum.', '{}'::text[], '[{"text": "So last year I went hiking with some friends, and halfway up the mountain it just started pouring rain — we were completely soaked by the time we got back.", "pattern": "setup → event → reaction, no stop"}]'::jsonb, '', false, 27, 'published'),
('fluency', 'Fluency answering a follow-up question', 'intermediate', 'medium', 'us', 'Follow-up questions should be answered immediately by building on what you already said, not restarting from scratch.', '{}'::text[], '[{"text": "A: Why did you choose that career? B: Mainly because I''ve always loved solving problems, so it felt like a natural fit.", "pattern": "instant, builds directly on the question"}]'::jsonb, '', false, 28, 'published'),
('fluency', 'Fluency giving constructive feedback', 'advanced', 'hard', 'us', 'Feedback flows better with a soft opener, the point, then a positive close — all in one smooth run.', ARRAY['One thing I noticed... / Something to think about... / Overall though...']::text[], '[{"text": "One thing I noticed is the pacing felt a bit rushed, but overall it was really well put together.", "pattern": "soft opener → point → positive close, no stop"}]'::jsonb, '', false, 29, 'published'),
('fluency', 'Fluency negotiating a deal', 'advanced', 'hard', 'us', 'Negotiation needs quick, confident responses without long gaps that make you seem unsure.', '{}'::text[], '[{"text": "I could go as low as three hundred, but that''s really my limit.", "pattern": "confident, no hesitation"}]'::jsonb, '', false, 30, 'published'),
('fluency', 'Fluency describing a trend or change over time', 'advanced', 'hard', 'us', 'Describing change over time flows through a sequence of stages without stalling.', '{}'::text[], '[{"text": "Sales started slow, picked up around March, and then levelled off for the rest of the year.", "pattern": "smooth sequence through stages"}]'::jsonb, '', false, 31, 'published'),
('fluency', 'Fluency comparing options and deciding', 'intermediate', 'medium', 'us', 'Weighing options fluently moves smoothly from one option to the other, then lands on a decision.', '{}'::text[], '[{"text": "This one''s cheaper, but that one lasts longer, so I think I''ll go with the second one.", "pattern": "smooth comparison → decision"}]'::jsonb, '', false, 32, 'published'),
('fluency', 'Fluency expressing frustration appropriately', 'advanced', 'hard', 'us', 'Frustration can still sound fluent and controlled rather than broken and hesitant.', '{}'::text[], '[{"text": "Honestly, this is the third time I''ve had to explain this, and it''s getting a bit frustrating.", "pattern": "controlled, fluent frustration"}]'::jsonb, '', false, 33, 'published'),
('fluency', 'Fluency apologizing for a bigger mistake', 'advanced', 'hard', 'us', 'A serious apology flows through acknowledgement, explanation and a fix, without awkward gaps.', '{}'::text[], '[{"text": "I really messed up on this one, and I take full responsibility — here''s what I''m doing to fix it.", "pattern": "acknowledge → own it → fix, no stop"}]'::jsonb, '', false, 34, 'published'),
('fluency', 'Fluency presenting statistics', 'advanced', 'hard', 'us', 'Presenting numbers fluently keeps the story flowing, not just reading digits mechanically.', '{}'::text[], '[{"text": "Revenue grew by fifteen percent last quarter, which is actually our strongest growth in three years.", "pattern": "number + context, no stop"}]'::jsonb, '', false, 35, 'published'),
('fluency', 'Fluency handling an awkward silence', 'intermediate', 'medium', 'us', 'A short, natural phrase can smoothly break an awkward silence instead of an uncomfortable pause.', ARRAY['Anyway... / So... / Well, this is nice.']::text[], '[{"text": "Anyway, how''s everything else been going?", "pattern": "smooth silence-breaker"}, {"text": "So, what do you think we should do next?", "pattern": "smooth silence-breaker"}]'::jsonb, '', false, 36, 'published'),
('fluency', 'Fluency chaining small talk topics', 'intermediate', 'medium', 'us', 'Natural small talk flows from one topic to the next through a light connector.', '{}'::text[], '[{"text": "Nice weather today — speaking of which, are you doing anything fun this weekend?", "pattern": "topic 1 → connector → topic 2"}]'::jsonb, '', false, 37, 'published'),
('fluency', 'Fluency teaching a concept simply', 'advanced', 'hard', 'us', 'Teaching fluently means explaining, then immediately reinforcing with an example, without a gap.', '{}'::text[], '[{"text": "Basically, supply and demand means when something''s rare, people want it more — like how concert tickets get expensive when they''re limited.", "pattern": "concept + example, no stop"}]'::jsonb, '', false, 38, 'published'),
('fluency', 'Fluency expressing hope about the future', 'intermediate', 'medium', 'us', 'Talking about hopes flows smoothly through the wish and the reason behind it.', '{}'::text[], '[{"text": "I''m really hoping things pick up next year, especially since we''ve put in so much work already.", "pattern": "hope + reason, no stop"}]'::jsonb, '', false, 39, 'published'),
('fluency', 'Fluency giving a recommendation', 'intermediate', 'medium', 'us', 'Recommending something fluently moves straight from the suggestion into why it''s good.', '{}'::text[], '[{"text": "You should definitely check out that restaurant — the food''s amazing and it''s not too pricey either.", "pattern": "recommendation + reasons, no stop"}]'::jsonb, '', false, 40, 'published'),
('fluency', 'Fluency sharing good news', 'beginner', 'easy', 'us', 'Sharing exciting news flows with energy and keeps building instead of trailing off.', '{}'::text[], '[{"text": "Guess what — I got the promotion! I still can''t quite believe it, honestly.", "pattern": "energetic, continuous flow"}]'::jsonb, '', false, 41, 'published'),
('fluency', 'Fluency describing a goal or dream', 'intermediate', 'medium', 'us', 'Describing a goal flows from the goal itself into the plan to achieve it.', '{}'::text[], '[{"text": "My goal is to start my own business someday, so right now I''m just focusing on saving up and learning as much as I can.", "pattern": "goal + plan, no stop"}]'::jsonb, '', false, 42, 'published'),
('fluency', 'Fluency explaining a decision you made', 'advanced', 'hard', 'us', 'Justifying a decision flows through the reasoning without sounding defensive or hesitant.', '{}'::text[], '[{"text": "I decided to turn down the offer, mainly because the commute would''ve been way too long for what it was worth.", "pattern": "decision + reasoning, no stop"}]'::jsonb, '', false, 43, 'published'),
('fluency', 'Fluency expressing regret', 'advanced', 'hard', 'us', 'Expressing regret fluently moves through the wish and the reason without dwelling awkwardly.', '{}'::text[], '[{"text": "Looking back, I wish I''d started learning earlier, but I guess it''s never too late.", "pattern": "regret + silver lining, no stop"}]'::jsonb, '', false, 44, 'published'),
('fluency', 'Fluency closing a conversation smoothly', 'beginner', 'easy', 'us', 'A smooth close wraps up naturally instead of just abruptly stopping.', '{}'::text[], '[{"text": "Well, it''s been great talking to you — let''s definitely catch up again soon.", "pattern": "smooth, natural close"}]'::jsonb, '', false, 45, 'published'),
('fluency', 'Fluency resuming a topic after a distraction', 'advanced', 'hard', 'us', 'After a brief distraction, a fluent speaker picks the exact thread back up without losing momentum.', ARRAY['Anyway, back to what I was saying...']::text[], '[{"text": "Sorry, where was I? Right — anyway, back to what I was saying about the schedule.", "pattern": "brief break, smooth resume"}]'::jsonb, '', false, 46, 'published'),
('fluency', 'Fluency expanding a short yes/no answer', 'intermediate', 'medium', 'us', 'A fluent speaker never just says ''yes'' or ''no'' alone — they immediately add a reason or detail.', '{}'::text[], '[{"text": "Yeah, definitely — I think it''s one of the best decisions I''ve made, actually.", "pattern": "yes + immediate detail"}, {"text": "Not really, no — I''ve always preferred working alone.", "pattern": "no + immediate detail"}]'::jsonb, '', false, 47, 'published'),
('fluency', 'Fluency handling a sudden topic change', 'advanced', 'hard', 'us', 'When a conversation suddenly shifts topic, a fluent speaker adapts instantly instead of freezing.', '{}'::text[], '[{"text": "Oh, that reminds me — did you hear about the new office opening downtown?", "pattern": "instant, smooth pivot"}]'::jsonb, '', false, 48, 'published'),
('fluency', 'Fluency giving genuine praise', 'beginner', 'easy', 'us', 'Genuine praise flows warmly and specifically, not just a flat single word.', '{}'::text[], '[{"text": "Honestly, that was one of the best presentations I''ve seen — really well organized.", "pattern": "warm, specific, flowing praise"}]'::jsonb, '', false, 49, 'published'),
('fluency', 'Fluency resolving a customer complaint', 'advanced', 'hard', 'us', 'As a service agent, a fluent resolution moves smoothly from empathy to action, without sounding scripted.', '{}'::text[], '[{"text": "I completely understand the frustration, and I''m going to sort this out for you right now — let me just pull up your account.", "pattern": "empathy → action, no stop"}]'::jsonb, '', false, 50, 'published'),
('fluency', 'Practice', 'intermediate', 'medium', 'us', 'Master fluency across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "Learning a new language is less about perfection and much more about making genuine human connections.", "pattern": "Smooth continuous flow connecting clauses.", "note": "Speak without hesitations between ''perfection'' and ''and much more''."}, {"text": "If you listen closely to native speakers, you will notice that their words blend effortlessly into continuous melodies.", "pattern": "Connected glide across commas.", "note": "Keep vocal tone resonant throughout the entire sentence."}, {"text": "Consistent daily practice, even for just fifteen minutes, delivers far better results than cramming once a week.", "pattern": "Dynamic flow over parenthetical ''even for just fifteen minutes''.", "note": "Link ''delivers'' cleanly into ''far better results''."}, {"text": "Confidence grows not from never making mistakes, but from communicating freely despite them.", "pattern": "Antithetical balance with smooth delivery.", "note": "Contrast ''not from'' and ''but from'' fluidly."}, {"text": "Reading aloud every morning trains your tongue, lips, and jaw muscles to produce English sounds automatically.", "pattern": "Smooth articulation of listed muscular organs.", "note": "Glide through the coordinate nouns without stopping."}, {"text": "The greatest obstacle to fluent speaking is often the inner voice that worries about grammatical precision.", "pattern": "Continuous rhythm across complex subject.", "note": "Deliver ''is often the inner voice'' as one breath unit."}, {"text": "When you shadow authentic audio, your mouth gradually internalizes the authentic rhythm and music of the language.", "pattern": "Melodic delivery mirroring the topic.", "note": "Connect ''internalizes the'' smoothly."}, {"text": "Pronunciation is like playing a musical instrument: muscle memory and ear training must develop together.", "pattern": "Balanced flow with slight colon pause.", "note": "Transition effortlessly across the colon."}, {"text": "Every conversation you engage in brings you one step closer to your ultimate personal and professional goals.", "pattern": "Forward momentum building toward ''goals''.", "note": "Keep pitch moving forward without faltering."}, {"text": "Embrace every opportunity to speak English, whether you are ordering coffee or presenting in a boardroom.", "pattern": "Smooth delivery across contrastive settings.", "note": "Flawless glide between ''coffee'' and ''or presenting''."}, {"text": "Public speaking becomes vastly easier once you shift your focus from your own anxiety to the message your audience needs.", "pattern": "Sustained breath management across 20 words.", "note": "Maintain steady tempo without rushing."}, {"text": "A clear, well-paced explanation always triumphs over a rushed monologue delivered at lightning speed.", "pattern": "Contrast in cadence matching the meaning.", "note": "Pronounce ''lightning speed'' with deliberate crispness."}, {"text": "By pausing strategically before important keywords, you give your listeners time to absorb and appreciate your ideas.", "pattern": "Intentional pacing and controlled breath support.", "note": "Practice breathing before ''you give your listeners''."}, {"text": "Effective communicators know when to speak up boldly, and just as importantly, when to listen with full attention.", "pattern": "Graceful symmetry across both clauses.", "note": "Link ''just as importantly'' effortlessly."}, {"text": "The secret to speaking naturally is letting your thoughts guide your breath rather than worrying about isolated words.", "pattern": "Continuous stream of thought.", "note": "Connect ''guide your breath'' without any break."}, {"text": "Traveling abroad pushes you out of your comfort zone and forces you to adapt quickly to unfamiliar accents.", "pattern": "Dynamic travel narrative.", "note": "Seamless linking across ''forces you to adapt''."}, {"text": "When you immerse yourself in diverse cultures, you begin to see the world from wonderfully unexpected perspectives.", "pattern": "Rich multi-syllabic vocabulary spoken fluidly.", "note": "Articulate ''wonderfully unexpected perspectives'' smoothly."}, {"text": "Language is the living bridge that allows people from completely different backgrounds to find common ground.", "pattern": "Warm metaphorical delivery.", "note": "Deliver ''living bridge that allows'' in a single wave."}, {"text": "Navigating a foreign subway station during rush hour tests both your vocabulary and your situational awareness.", "pattern": "Everyday experiential fluency.", "note": "Keep the cadence steady from start to finish."}, {"text": "Sharing a meal with local hosts often leads to the most memorable and spontaneous conversations of any journey.", "pattern": "Comfortable, engaging conversational tempo.", "note": "Smoothly connect ''spontaneous conversations''."}, {"text": "In today''s interconnected global economy, clear cross-cultural communication is an invaluable superpower.", "pattern": "Professional business fluency.", "note": "Pronounce ''cross-cultural communication'' with clean transitions."}, {"text": "Collaborating effectively with international colleagues requires empathy, active listening, and concise articulation.", "pattern": "Balanced executive delivery.", "note": "Glide across the three coordinate qualities."}, {"text": "A concise email that gets straight to the point saves everyone time and prevents unnecessary misunderstandings.", "pattern": "Crisp, businesslike flow.", "note": "Smooth linking across ''unnecessary misunderstandings''."}, {"text": "Negotiating successfully is rarely about winning an argument; it is about finding a solution that benefits both parties.", "pattern": "Semicolon transition with authoritative calm.", "note": "Maintain professional poise across both halves."}, {"text": "Delivering constructive feedback requires a gentle touch and a genuine desire to see your teammates flourish.", "pattern": "Warm leadership cadence.", "note": "Connect ''gentle touch and a genuine desire''."}, {"text": "Critical thinking enables you to evaluate complex claims objectively rather than accepting simple answers at face value.", "pattern": "Academic analysis with smooth phrasing.", "note": "Articulate ''complex claims objectively'' with clarity."}, {"text": "The rapid advancement of artificial intelligence is fundamentally transforming how we learn, work, and create.", "pattern": "Modern tech topic delivered at steady pace.", "note": "Link ''how we learn, work, and create''."}, {"text": "Scientific progress relies on rigorous experimentation, honest peer review, and a willingness to question assumptions.", "pattern": "Authoritative scientific cadence.", "note": "Smooth triad across the coordinate objects."}, {"text": "Understanding climate patterns helps us develop sustainable strategies to protect vulnerable coastal communities.", "pattern": "Environmental science topic with rich flow.", "note": "Glide through ''sustainable strategies''."}, {"text": "Curiosity and intellectual humility are the cornerstones of any lifelong journey of personal discovery.", "pattern": "Reflective academic pacing.", "note": "Deliver ''cornerstones of any lifelong journey'' smoothly."}, {"text": "Nothing beats the serene feeling of sipping hot tea on a rainy afternoon while lost in a captivating novel.", "pattern": "Cozy lifestyle narrative.", "note": "Gentle, relaxing tempo matching the mood."}, {"text": "Maintaining a healthy sleep routine dramatically improves your daytime energy, focus, and overall well-being.", "pattern": "Wellness topic with steady rhythm.", "note": "Sustain clear breath across the final list."}, {"text": "Spending time in nature has been proven to lower stress hormones and restore mental clarity almost immediately.", "pattern": "Calm, reassuring delivery.", "note": "Link ''restore mental clarity'' seamlessly."}, {"text": "Cooking a wholesome meal from scratch can be an incredibly mindful and rewarding way to unwind after a busy day.", "pattern": "Warm conversational flow.", "note": "Glide effortlessly through ''mindful and rewarding way''."}, {"text": "Cultivating gratitude each morning sets an optimistic and resilient tone for whatever challenges lie ahead.", "pattern": "Uplifting mindfulness cadence.", "note": "Pronounce ''optimistic and resilient'' with fluid grace."}, {"text": "The author paints a vivid portrait of a forgotten city lost beneath centuries of shifting desert sands.", "pattern": "Literary eloquence.", "note": "Sustain a rich, imaginative tone throughout."}, {"text": "Her music blends classical orchestration with contemporary beats to create an entirely fresh auditory experience.", "pattern": "Artistic review pacing.", "note": "Smooth transitions across musical terms."}, {"text": "Architectural marvels remind us that human ambition can turn sheer imagination into enduring monuments.", "pattern": "Elevated philosophical tone.", "note": "Deliver ''sheer imagination into enduring monuments'' cleanly."}, {"text": "A photograph captures a fleeting split second and transforms it into an everlasting piece of personal history.", "pattern": "Poetic reflection.", "note": "Link ''fleeting split second'' without hesitation."}, {"text": "Great storytelling has the unique power to transcend generations and speak directly to the universal human spirit.", "pattern": "Resonant conclusion.", "note": "Deliver ''universal human spirit'' with heartfelt resonance."}, {"text": "Even when faced with sudden obstacles, remaining adaptable allows you to discover creative and unexpected workarounds.", "pattern": "Resilient mindset narrative.", "note": "Smooth connection through ''creative and unexpected workarounds''."}, {"text": "Patience is not merely the ability to wait, but how you conduct yourself while working toward long-term goals.", "pattern": "Philosophical nuance.", "note": "Emphasize ''how you conduct yourself'' fluidly."}, {"text": "Every small habit you build today compounds over months and years into profound personal transformation.", "pattern": "Self-development pacing.", "note": "Maintain forward momentum toward ''transformation''."}, {"text": "True mastery in any discipline comes from falling in love with the repetitive daily fundamentals of the craft.", "pattern": "Insightful coaching delivery.", "note": "Connect ''repetitive daily fundamentals'' smoothly."}, {"text": "You do not need to see the entire staircase to take the very first courageous step forward.", "pattern": "Inspirational metaphor.", "note": "Deliver with calm conviction and continuous flow."}, {"text": "Overcoming the fear of speaking in public is a journey that transforms your self-perception forever.", "pattern": "Empowering personal growth cadence.", "note": "Flawless glide through ''transforms your self-perception forever''."}, {"text": "When you speak from personal experience, your words carry an authenticity that no rehearsal can fabricate.", "pattern": "Honest, direct communication tone.", "note": "Deliver ''carry an authenticity'' with grounded resonance."}, {"text": "The English language belongs to whoever uses it to connect, inspire, and share their unique human story.", "pattern": "Inclusive global perspective.", "note": "Glide smoothly across ''connect, inspire, and share''."}, {"text": "Never apologize for having an accent; it is simply proof that you were brave enough to learn a second language.", "pattern": "Uplifting affirmation for all language learners.", "note": "Speak with genuine warmth and unwavering confidence."}, {"text": "Keep practicing every day, celebrate your progress, and trust that your dedication will lead to total fluency.", "pattern": "Triumphant finale.", "note": "End on a high, encouraging, and decisive note."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published'),
('intonation', 'Falling intonation', 'beginner', 'easy', 'us', 'Your pitch drops at the end. It sounds finished, certain and confident.', ARRAY['Statements', 'WH- questions', 'Commands', 'Completed thoughts']::text[], '[{"text": "I live in Toronto.", "pattern": "I live in To-RON-to ↘"}, {"text": "Where do you work?", "pattern": "WHERE do you WORK ↘"}, {"text": "Close the door, please.", "pattern": "CLOSE the DOOR ↘"}, {"text": "That''s all for today.", "pattern": "that''s ALL for to-DAY ↘"}]'::jsonb, '', true, 1, 'published'),
('intonation', 'Rising intonation', 'beginner', 'easy', 'us', 'Your pitch goes up at the end. It sounds like a question, a check or an unfinished thought.', ARRAY['Yes/no questions', 'Checking information', 'Surprise', 'Lists before the last item']::text[], '[{"text": "Are you coming?", "pattern": "are you COMing ↗"}, {"text": "Really?", "pattern": "REAL-ly ↗"}, {"text": "You paid a hundred dollars?", "pattern": "a HUNdred DOLlars ↗"}, {"text": "I bought bread, milk, and eggs.", "pattern": "BREAD ↗ MILK ↗ and EGGS ↘"}]'::jsonb, '', true, 2, 'published'),
('intonation', 'Rise-fall and fall-rise', 'advanced', 'hard', 'us', 'These two patterns carry attitude: surprise, doubt, politeness or a hidden ''but''.', ARRAY['Rise-fall ↗↘ = strong feeling, surprise.', 'Fall-rise ↘↗ = doubt, politeness, ''yes, but…''']::text[], '[{"text": "You''re joking!", "pattern": "you''re JOKing ↗↘", "note": "Rise-fall: real surprise."}, {"text": "That was amazing!", "pattern": "a-MAZ-ing ↗↘"}, {"text": "Well, maybe.", "pattern": "MAY-be ↘↗", "note": "Fall-rise: I am not convinced."}, {"text": "I could come, but…", "pattern": "I COULD come ↘↗", "note": "Fall-rise leaves it open."}]'::jsonb, '', true, 3, 'published'),
('intonation', 'Question tags: checking vs asking', 'intermediate', 'medium', 'us', 'The same tag question can mean two different things depending on whether your pitch rises or falls at the end.', ARRAY['Falling tag = I''m almost sure, just confirming.', 'Rising tag = I''m genuinely not sure, really asking.']::text[], '[{"text": "It''s cold today, isn''t it? ↘", "pattern": "falling", "note": "I''m sure — just making conversation."}, {"text": "You locked the door, didn''t you? ↗", "pattern": "rising", "note": "I''m genuinely unsure — please confirm."}, {"text": "She''s from Spain, isn''t she? ↘", "pattern": "falling", "note": "Confirming what I already believe."}]'::jsonb, '', true, 4, 'published'),
('intonation', 'Or-questions: two different meanings', 'advanced', 'hard', 'us', '''Or'' questions change meaning completely depending on the final pitch movement.', ARRAY['Rising on the last option = yes/no question about both together.', 'Falling on the last option = choose one of the two.']::text[], '[{"text": "Do you want tea or coffee? ↘", "pattern": "falling on ''coffee''", "note": "Choose one: tea, or coffee."}, {"text": "Do you want tea or coffee? ↗", "pattern": "rising on ''coffee''", "note": "Asks: do you want a drink at all (either one)?"}]'::jsonb, '', true, 5, 'published'),
('intonation', 'Exclamations', 'beginner', 'easy', 'us', 'Exclamations use a big pitch jump to show strong feeling — surprise, excitement or admiration.', '{}'::text[], '[{"text": "What a beautiful view!", "pattern": "WHAT a BEAUtiful VIEW ↗↘"}, {"text": "How amazing is that!", "pattern": "how aMAZing is THAT ↗↘"}, {"text": "Wow, I can''t believe it!", "pattern": "WOW, I can''t beLIEVE it ↗↘"}]'::jsonb, '', false, 6, 'published'),
('intonation', 'Lists with more than two items', 'intermediate', 'medium', 'us', 'Every item in a list rises except the last one, which falls to show the list is finished.', '{}'::text[], '[{"text": "I need apples, bananas, oranges, and milk.", "pattern": "AP-ples ↗ ba-NAN-as ↗ O-ran-ges ↗ and MILK ↘"}, {"text": "We visited Paris, Rome, and Berlin.", "pattern": "PAR-is ↗ ROME ↗ and Ber-LIN ↘"}]'::jsonb, '', false, 7, 'published'),
('intonation', 'Echo questions for surprise', 'advanced', 'hard', 'us', 'Repeating part of what someone said, with a sharp rise, shows surprise or disbelief.', '{}'::text[], '[{"text": "A: I moved to Iceland. B: You moved WHERE? ↗", "pattern": "sharp rise on ''where''"}, {"text": "A: I quit my job. B: You did WHAT? ↗", "pattern": "sharp rise on ''what''"}, {"text": "A: It cost two thousand dollars. B: TWO THOUsand? ↗", "pattern": "sharp rise on the number"}]'::jsonb, '', false, 8, 'published'),
('intonation', 'Polite requests with fall-rise softening', 'advanced', 'hard', 'us', 'A gentle fall-rise on a request sounds more polite and less like a demand.', '{}'::text[], '[{"text": "Could you help me? ↘↗", "pattern": "fall-rise = extra polite"}, {"text": "Would that be okay? ↘↗", "pattern": "fall-rise = softening"}, {"text": "Do you think you could? ↘↗", "pattern": "fall-rise = tentative, polite"}]'::jsonb, '', false, 9, 'published'),
('intonation', 'Intonation in giving choices', 'intermediate', 'medium', 'us', 'Offering two or more options in a sentence uses rise-then-fall, just like a two-item list.', '{}'::text[], '[{"text": "You can pay by card or cash.", "pattern": "by CARD ↗ or CASH ↘"}, {"text": "We can meet today or tomorrow.", "pattern": "toDAY ↗ or toMORrow ↘"}]'::jsonb, '', false, 10, 'published'),
('intonation', 'Intonation for genuine uncertainty', 'intermediate', 'medium', 'us', 'A rising or level pitch on a statement (instead of falling) signals you''re not fully sure.', '{}'::text[], '[{"text": "I think it''s around five o''clock? ↗", "pattern": "rising = uncertain"}, {"text": "Maybe it was last Tuesday? ↗", "pattern": "rising = unsure"}, {"text": "I guess that''s right? ↗", "pattern": "rising = tentative"}]'::jsonb, '', false, 11, 'published'),
('intonation', 'Intonation in greetings', 'beginner', 'easy', 'us', 'A warm, falling intonation on greetings sounds friendly and confident.', '{}'::text[], '[{"text": "Good morning!", "pattern": "good MORning ↘"}, {"text": "Nice to see you!", "pattern": "NICE to SEE you ↘"}, {"text": "How are you doing?", "pattern": "how are you DOing ↗", "note": "Rising here sounds casual and friendly, not like a real question."}]'::jsonb, '', false, 12, 'published'),
('intonation', 'Intonation for sarcasm and irony', 'advanced', 'hard', 'us', 'Sarcastic tone usually exaggerates the pitch and stretches the stressed word longer than normal.', '{}'::text[], '[{"text": "Oh, great. Another meeting.", "pattern": "oh, GREAT ↘ (flat, exaggerated)", "note": "The word ''great'' is stretched and falls hard — the opposite of sincere."}, {"text": "Yeah, that''s exactly what I wanted.", "pattern": "YEAH ↘ (sarcastic fall)"}]'::jsonb, '', false, 13, 'published'),
('intonation', 'Intonation in giving good news vs bad news', 'intermediate', 'medium', 'us', 'A wide pitch range signals good news; a narrower, lower range signals bad news.', '{}'::text[], '[{"text": "Guess what — I got the job!", "pattern": "wide range, rising energy ↗↘"}, {"text": "I''m sorry, but we didn''t get approved.", "pattern": "narrow, low, mostly falling ↘"}]'::jsonb, '', false, 14, 'published'),
('intonation', 'Intonation across a whole IELTS-style answer', 'advanced', 'hard', 'us', 'A long spoken answer should still fall clearly at the very end of each main idea, even with several sentences.', '{}'::text[], '[{"text": "I think travelling is important because it broadens your perspective, and it also helps you understand other cultures better.", "pattern": "IMportant ↘ ... PERspective ↗ ... CULtures BETter ↘"}]'::jsonb, '', false, 15, 'published'),
('intonation', 'Declarative questions (statement form, question meaning)', 'advanced', 'hard', 'us', 'A statement with rising intonation can become a genuine question without changing the word order at all.', '{}'::text[], '[{"text": "You''re leaving already? ↗", "pattern": "rising = surprised question"}, {"text": "This is your first time here? ↗", "pattern": "rising question"}, {"text": "You forgot your passport? ↗", "pattern": "rising = shocked question"}]'::jsonb, '', false, 16, 'published'),
('intonation', 'Intonation reading out numbers and phone numbers', 'beginner', 'easy', 'us', 'Each group of digits rises slightly except the very last group, which falls to show you''ve finished.', '{}'::text[], '[{"text": "five five five ↗ one two three four ↘", "pattern": "555 ↗ 1234 ↘"}, {"text": "My number is oh two one ↗ five five five ↘", "pattern": "grouped, last group falls"}]'::jsonb, '', false, 17, 'published'),
('intonation', 'Intonation in warnings', 'intermediate', 'medium', 'us', 'Warnings often use a sharp rise-fall on the danger word to grab attention immediately.', '{}'::text[], '[{"text": "Be careful, it''s hot!", "pattern": "be CAREful, it''s HOT ↗↘!"}, {"text": "Don''t touch that wire!", "pattern": "DON''T touch that WIRE ↗↘!"}]'::jsonb, '', false, 18, 'published'),
('intonation', 'Intonation for reassurance', 'intermediate', 'medium', 'us', 'A calm, gently falling pitch with a soft final tone sounds comforting and reassuring.', '{}'::text[], '[{"text": "Don''t worry, everything will be fine.", "pattern": "don''t WORry, everything will be FINE ↘", "note": "Soft, gentle fall — not sharp."}, {"text": "It''s okay, take your time.", "pattern": "it''s oKAY, take your TIME ↘"}]'::jsonb, '', false, 19, 'published'),
('intonation', 'Intonation when giving a compliment', 'beginner', 'easy', 'us', 'Genuine compliments use a warm rise-fall to sound sincere rather than flat or sarcastic.', '{}'::text[], '[{"text": "You did a great job!", "pattern": "you did a GREAT job ↗↘!"}, {"text": "I love your new haircut.", "pattern": "I LOVE your new HAIRcut ↗↘."}]'::jsonb, '', false, 20, 'published'),
('intonation', 'Intonation closing small talk politely', 'beginner', 'easy', 'us', 'Ending a conversation politely uses a gentle, falling, friendly tone.', '{}'::text[], '[{"text": "Well, it was great catching up.", "pattern": "well, it was GREAT catching UP ↘"}, {"text": "Anyway, I should get going.", "pattern": "anyWAY, I should GET going ↘"}]'::jsonb, '', false, 21, 'published'),
('intonation', 'Intonation while negotiating', 'advanced', 'hard', 'us', 'Negotiating uses fall-rise a lot — firm but leaving room for discussion.', '{}'::text[], '[{"text": "I could do fifty, but not sixty. ↘↗", "pattern": "fall-rise = open to discussion"}, {"text": "That''s a bit more than I wanted to spend. ↘↗", "pattern": "fall-rise = softening a pushback"}]'::jsonb, '', false, 22, 'published'),
('intonation', 'Intonation when explaining steps to someone', 'intermediate', 'medium', 'us', 'Teaching intonation rises slightly at the end of each step to show ''more is coming'' and falls on the last step.', '{}'::text[], '[{"text": "First you open the app, ↗ then you log in, ↗ and finally you tap submit. ↘", "pattern": "rise, rise, fall"}]'::jsonb, '', false, 23, 'published'),
('intonation', 'Same words, different intonation, different meaning', 'advanced', 'hard', 'us', 'Identical words can be a plain statement or a real question — only the pitch tells you which.', '{}'::text[], '[{"text": "You''re coming. ↘", "pattern": "falling = a statement of fact"}, {"text": "You''re coming? ↗", "pattern": "rising = a genuine question"}]'::jsonb, '', false, 24, 'published'),
('intonation', 'Intonation in a sincere apology', 'intermediate', 'medium', 'us', 'Sincere apologies fall gently and slowly — a flat or fast fall can sound insincere.', '{}'::text[], '[{"text": "I''m really sorry about that.", "pattern": "I''m REALly SORry about THAT ↘ (slow, gentle fall)"}, {"text": "That was completely my fault.", "pattern": "that was comPLETEly my FAULT ↘"}]'::jsonb, '', false, 25, 'published'),
('intonation', 'Enthusiasm vs boredom: same sentence, opposite energy', 'advanced', 'hard', 'us', 'The exact same words can sound excited or bored depending only on pitch range and speed.', '{}'::text[], '[{"text": "That sounds great.", "pattern": "wide pitch range, fast ↗↘ = enthusiastic"}, {"text": "That sounds great.", "pattern": "narrow, flat, slow ↘ = bored/unenthusiastic"}]'::jsonb, '', false, 26, 'published'),
('intonation', 'Intonation in a formal announcement', 'advanced', 'hard', 'us', 'Formal announcements use clear, wide falls on each main point to sound authoritative and easy to follow.', '{}'::text[], '[{"text": "Ladies and gentlemen, thank you for joining us today.", "pattern": "wide falls on each phrase"}, {"text": "The meeting will begin in five minutes.", "pattern": "clear fall on ''five minutes''"}]'::jsonb, '', false, 27, 'published'),
('intonation', 'Continuing intonation mid-sentence', 'intermediate', 'medium', 'us', 'A slight rise or level pitch in the middle of a sentence signals ''I''m not finished yet.''', '{}'::text[], '[{"text": "When I got home ↗, I made dinner ↘.", "pattern": "level/rise mid-sentence, fall at the end"}, {"text": "Even though it was late ↗, we kept working ↘.", "pattern": "level/rise, then fall"}]'::jsonb, '', false, 28, 'published'),
('intonation', 'Intonation when checking you understood correctly', 'intermediate', 'medium', 'us', 'Checking understanding uses a rising tag or a rising echo to invite confirmation.', '{}'::text[], '[{"text": "So you''re saying we should wait? ↗", "pattern": "rising check"}, {"text": "If I understood right, the deadline is Friday? ↗", "pattern": "rising check"}]'::jsonb, '', false, 29, 'published'),
('intonation', 'Intonation when offering help', 'beginner', 'easy', 'us', 'Offers of help usually rise gently, sounding open and inviting rather than pushy.', '{}'::text[], '[{"text": "Can I help you with that?", "pattern": "can I HELP you with THAT ↗"}, {"text": "Would you like me to carry that?", "pattern": "would you LIKE me to CARry that ↗"}]'::jsonb, '', false, 30, 'published'),
('intonation', 'Intonation expressing disappointment', 'intermediate', 'medium', 'us', 'Disappointment often uses a falling pitch that starts lower than usual and drops further, sounding flat and deflated.', '{}'::text[], '[{"text": "Oh. I was really hoping we could go.", "pattern": "low start, falling ↘"}, {"text": "I guess that''s that, then.", "pattern": "low, flat, falling ↘"}]'::jsonb, '', false, 31, 'published'),
('intonation', 'Intonation in giving clear instructions', 'intermediate', 'medium', 'us', 'Instructions fall clearly at the end of each command so the listener knows exactly when one instruction ends.', '{}'::text[], '[{"text": "Turn left. ↘ Then go straight. ↘ Stop at the light. ↘", "pattern": "clear fall after each instruction"}]'::jsonb, '', false, 32, 'published'),
('intonation', 'Intonation building to a storytelling climax', 'advanced', 'hard', 'us', 'The pitch rises and the pace quickens as a story builds tension, then falls sharply at the climax.', '{}'::text[], '[{"text": "And then... ↗ the door slowly opened... ↗ and there was NOBODY there! ↗↘", "pattern": "rising tension, sharp fall-rise at the climax"}]'::jsonb, '', false, 33, 'published'),
('intonation', 'Intonation showing confusion', 'intermediate', 'medium', 'us', 'Confusion often uses a rising, questioning tone even on statements, with a slight pause before.', '{}'::text[], '[{"text": "Wait... I don''t get it. ↗", "pattern": "rising, questioning"}, {"text": "Hold on, what do you mean? ↗", "pattern": "rising, confused"}]'::jsonb, '', false, 34, 'published'),
('intonation', 'Intonation in a polite disagreement', 'advanced', 'hard', 'us', 'Disagreeing politely often starts with a fall-rise to soften it before the falling main point.', '{}'::text[], '[{"text": "I see what you mean, ↘↗ but I''m not sure I agree. ↘", "pattern": "fall-rise softener, then falling main point"}, {"text": "That''s a fair point, ↘↗ though I''d look at it differently. ↘", "pattern": "fall-rise, then fall"}]'::jsonb, '', false, 35, 'published'),
('intonation', 'Intonation reading a list vs a casual list', 'intermediate', 'medium', 'us', 'A formal, careful list uses clear rises on each item; a casual list runs the items together more.', '{}'::text[], '[{"text": "We need eggs, ↗ milk, ↗ butter, ↗ and flour. ↘", "pattern": "careful formal list"}, {"text": "Eggs, milk, butter, flour ↘", "pattern": "casual, fast, one small fall at the end"}]'::jsonb, '', false, 36, 'published'),
('intonation', 'Intonation correcting someone politely', 'advanced', 'hard', 'us', 'A gentle fall-rise softens a correction so it doesn''t sound like an attack.', '{}'::text[], '[{"text": "Actually, I think it''s the other way around. ↘↗", "pattern": "gentle fall-rise"}, {"text": "Just to clarify, the meeting''s at three, not four. ↘↗", "pattern": "gentle fall-rise"}]'::jsonb, '', false, 37, 'published'),
('intonation', 'Intonation giving a toast', 'advanced', 'hard', 'us', 'A toast uses a warm, rising build-up followed by a strong, confident fall on the final wish.', '{}'::text[], '[{"text": "To all of you, ↗ to good times, ↗ and to many more years ahead! ↘", "pattern": "rising build, strong final fall"}]'::jsonb, '', false, 38, 'published'),
('intonation', 'Intonation expressing relief', 'intermediate', 'medium', 'us', 'Relief often starts high and falls with a long, relaxed glide, almost like a sigh.', '{}'::text[], '[{"text": "Oh, thank goodness, it''s over.", "pattern": "high start, long relaxed fall ↘"}, {"text": "Phew, that was close.", "pattern": "high start, falling ↘"}]'::jsonb, '', false, 39, 'published'),
('intonation', 'Intonation introducing yourself formally vs casually', 'intermediate', 'medium', 'us', 'A formal introduction falls in a measured, even way; a casual one is faster with a friendlier rise.', '{}'::text[], '[{"text": "Good morning, my name is Sarah Johnson.", "pattern": "measured, even fall ↘"}, {"text": "Hey, I''m Sarah!", "pattern": "quick, friendly rise ↗"}]'::jsonb, '', false, 40, 'published'),
('intonation', 'Intonation cheering someone on', 'beginner', 'easy', 'us', 'Encouragement uses an energetic rise-fall to sound genuinely supportive.', '{}'::text[], '[{"text": "You can do this!", "pattern": "you CAN do THIS ↗↘!"}, {"text": "Come on, you''re almost there!", "pattern": "come ON, you''re ALmost THERE ↗↘!"}]'::jsonb, '', false, 41, 'published'),
('intonation', 'Intonation in a job interview answer', 'advanced', 'hard', 'us', 'Confident interview answers fall clearly and firmly at the end of each key point.', '{}'::text[], '[{"text": "I believe my experience makes me a strong fit for this role.", "pattern": "clear, confident fall ↘"}]'::jsonb, '', false, 42, 'published'),
('intonation', 'Intonation with contrast markers (however, but)', 'advanced', 'hard', 'us', 'A slight rise or pause before ''however'' or ''but'' signals a contrast is coming.', '{}'::text[], '[{"text": "The plan sounds good, ↗ however, there''s one issue. ↘", "pattern": "rise before contrast, then fall"}, {"text": "It''s cheap, ↗ but the quality isn''t great. ↘", "pattern": "rise before contrast, then fall"}]'::jsonb, '', false, 43, 'published'),
('intonation', 'Intonation asking permission', 'beginner', 'easy', 'us', 'Asking permission almost always rises to sound open and non-demanding.', '{}'::text[], '[{"text": "Can I ask you something? ↗", "pattern": "rising"}, {"text": "Is it okay if I leave early? ↗", "pattern": "rising"}]'::jsonb, '', false, 44, 'published'),
('intonation', 'Intonation delivering bad news gently', 'advanced', 'hard', 'us', 'Gentle bad news uses a soft, slow fall — a sudden hard fall can sound cold or blunt.', '{}'::text[], '[{"text": "I''m afraid we won''t be able to approve this.", "pattern": "soft, slow fall ↘"}, {"text": "Unfortunately, the flight''s been cancelled.", "pattern": "soft, slow fall ↘"}]'::jsonb, '', false, 45, 'published'),
('intonation', 'Intonation showing indifference', 'intermediate', 'medium', 'us', 'A flat, narrow pitch with little movement signals ''I don''t really care either way.''', '{}'::text[], '[{"text": "I guess it''s fine, whatever works.", "pattern": "flat, narrow range ↘"}, {"text": "Either one is okay with me.", "pattern": "flat, narrow range ↘"}]'::jsonb, '', false, 46, 'published'),
('intonation', 'Intonation reading prices and quantities', 'beginner', 'easy', 'us', 'Prices fall clearly on the final amount to sound definite and easy to note down.', '{}'::text[], '[{"text": "That''ll be twelve dollars fifty. ↘", "pattern": "falling on the final amount"}, {"text": "It comes to about forty euros. ↘", "pattern": "falling"}]'::jsonb, '', false, 47, 'published'),
('intonation', 'Intonation calling someone across a room', 'beginner', 'easy', 'us', 'Calling someone''s name to get attention uses a wide rise-fall so it carries and stands out.', '{}'::text[], '[{"text": "Hey, John! ↗↘", "pattern": "wide, carrying rise-fall"}, {"text": "Excuse me! ↗↘", "pattern": "wide, carrying rise-fall"}]'::jsonb, '', false, 48, 'published'),
('intonation', 'Intonation in a countdown', 'beginner', 'easy', 'us', 'A countdown rises with anticipation on each number and falls sharply on the final word.', '{}'::text[], '[{"text": "Three... ↗ two... ↗ one... ↗ GO! ↘", "pattern": "rising anticipation, sharp final fall"}]'::jsonb, '', false, 49, 'published'),
('intonation', 'Final mixed review: pick the right pattern', 'advanced', 'hard', 'us', 'A closing mixed set — decide falling, rising, rise-fall or fall-rise for each line before checking.', '{}'::text[], '[{"text": "Are you free tonight?", "pattern": "↗ rising yes/no question"}, {"text": "I can''t believe it worked!", "pattern": "↗↘ rise-fall, surprise"}, {"text": "I suppose it''s fine.", "pattern": "↘↗ fall-rise, uncertain"}, {"text": "That''s the end of the tour.", "pattern": "↘ falling, finished statement"}]'::jsonb, '', false, 50, 'published'),
('intonation', 'Practice', 'intermediate', 'medium', 'us', 'Master intonation across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "She graduated with honors.", "pattern": "She graduated with ↘honors.", "note": "Statement: falling intonation at the final content word."}, {"text": "I finished the assignment.", "pattern": "I finished the as↘signment.", "note": "Definite statement ends with a decisive drop in pitch."}, {"text": "We bought a new dining table.", "pattern": "We bought a new dining ↘table.", "note": "Standard downward cadence on completed facts."}, {"text": "The flight arrives at seven.", "pattern": "The flight arrives at ↘seven.", "note": "Clear drop signals the end of the informative thought."}, {"text": "They decided to stay home.", "pattern": "They decided to stay ↘home.", "note": "Finality indicated by pitch dropping below neutral."}, {"text": "Did you receive my package?", "pattern": "Did you receive my ↗package?", "note": "Yes/No question: rising pitch at the end."}, {"text": "Is this seat taken?", "pattern": "Is this seat ↗taken?", "note": "Polite inquiry: sharp rise on ''taken''."}, {"text": "Have you ever traveled to Spain?", "pattern": "Have you ever traveled to ↗Spain?", "note": "Yes/No query floats upward at the end."}, {"text": "Are we ready to start?", "pattern": "Are we ready to ↗start?", "note": "Anticipatory rising intonation."}, {"text": "Can I borrow your pencil?", "pattern": "Can I borrow your ↗pencil?", "note": "Friendly request ends with an upward sweep."}, {"text": "Where did you leave the keys?", "pattern": "↘Where did you leave the ↘keys?", "note": "Wh- question: starts high and finishes falling."}, {"text": "When does the seminar begin?", "pattern": "↘When does the seminar be↘gin?", "note": "Wh- inquiries demand a falling tone."}, {"text": "Why are the lights still on?", "pattern": "↘Why are the lights still ↘on?", "note": "Curiosity/inquiry: drop at the conclusion."}, {"text": "How much does this ticket cost?", "pattern": "↘How much does this ticket ↘cost?", "note": "Downward cadence on the final word."}, {"text": "Who is giving the keynote speech?", "pattern": "↘Who is giving the keynote ↘speech?", "note": "Wh- falling contour."}, {"text": "Would you like soup, salad, or bread?", "pattern": "Would you like ↗soup, ↗salad, or ↘bread?", "note": "List intonation: rise, rise, then fall on the final option."}, {"text": "We need apples, oranges, and bananas.", "pattern": "We need ↗apples, ↗oranges, and ba↘nanas.", "note": "Incomplete items rise; last item drops to close."}, {"text": "I packed a jacket, boots, and an umbrella.", "pattern": "I packed a ↗jacket, ↗boots, and an um↘brella.", "note": "Listing contour: pitch ascends until the finale."}, {"text": "Do you prefer tea or coffee?", "pattern": "Do you prefer ↗tea or ↘coffee?", "note": "Alternative question: first choice rises, second falls."}, {"text": "Is it blue, black, or grey?", "pattern": "Is it ↗blue, ↗black, or ↘grey?", "note": "Alternatives terminate with a definitive fall."}, {"text": "You are coming tomorrow, aren''t you?", "pattern": "You''re coming tomorrow, ↘aren''t you?", "note": "Confirmation tag (speaker is sure): falling pitch."}, {"text": "You didn''t lock the gate, did you?", "pattern": "You didn''t lock the gate, ↗did you?", "note": "Genuine doubt tag: rising pitch asks for truth."}, {"text": "It''s rather chilly outside, isn''t it?", "pattern": "It''s rather chilly outside, ↘isn''t it?", "note": "Seeking agreement: falling tag."}, {"text": "We haven''t met before, have we?", "pattern": "We haven''t met before, ↗have we?", "note": "Uncertain check: upward rise on ''have we''."}, {"text": "That was a thrilling match, wasn''t it?", "pattern": "That was a thrilling match, ↘wasn''t it?", "note": "Enthusiastic consensus: falling tag."}, {"text": "I really appreciate your kind help.", "pattern": "I ↘really appreciate your kind ↘help.", "note": "Sincere gratitude: low, grounded pitch."}, {"text": "What a breathtaking view!", "pattern": "What a ↘breathtaking ↘view!", "note": "Exclamation: high emotional peak followed by steep drop."}, {"text": "That''s fantastic news!", "pattern": "That''s fan↘tastic ↘news!", "note": "Excitement peaks on ''tastic'' and settles on ''news''."}, {"text": "How wonderful to see you!", "pattern": "How ↘wonderful to ↘see you!", "note": "Warm greeting with sweeping downward inflection."}, {"text": "Please sit down.", "pattern": "Please sit ↘down.", "note": "Polite command: firm falling tone."}, {"text": "Although it was freezing, we went hiking.", "pattern": "Although it was ↗freezing, we went ↘hiking.", "note": "Dependent clause rises; main clause falls."}, {"text": "If you need anything, just call me.", "pattern": "If you need ↗anything, just ↘call me.", "note": "Conditional ''if'' clause carries rising suspense."}, {"text": "Because it rained all morning, the game was postponed.", "pattern": "Because it rained all ↗morning, the game was post↘poned.", "note": "Subordinate clause rises to keep listener waiting."}, {"text": "When we arrived at the venue, the show had started.", "pattern": "When we arrived at the ↗venue, the show had ↘started.", "note": "Introductory time clause floats up."}, {"text": "While she was cooking dinner, he set the table.", "pattern": "While she was cooking ↗dinner, he set the ↘table.", "note": "Rise indicates unfinished thought until second half."}, {"text": "Well, I suppose that might work.", "pattern": "↘Well↗, I suppose that might ↘work.", "note": "Hesitation/reluctance: fall-rise on ''well''."}, {"text": "Actually, I have a different proposal.", "pattern": "↘Act↗ually, I have a different pro↘posal.", "note": "Diplomatic correction: fall-rise on ''actually''."}, {"text": "Fortunately, nobody was hurt.", "pattern": "↘For↗tunately, nobody was ↘hurt.", "note": "Sentence adverbial gets mild fall-rise emphasis."}, {"text": "Honestly, I haven''t thought about it.", "pattern": "↘Hon↗estly, I haven''t thought a↘bout it.", "note": "Candid reflection: fall-rise on ''honestly''."}, {"text": "To be frank, I am not convinced.", "pattern": "To be ↘frank↗, I am not con↘vinced.", "note": "Expressing mild skepticism."}, {"text": "Did she say fifty or fifteen?", "pattern": "Did she say ↗fifty or fif↘teen?", "note": "Clarification: first number rises, second falls."}, {"text": "Are we leaving now or later?", "pattern": "Are we leaving ↗now or ↘later?", "note": "Contrasting choices."}, {"text": "Was that your brother or your cousin?", "pattern": "Was that your ↗brother or your ↘cousin?", "note": "Alternative inquiry."}, {"text": "Should I call him or text him?", "pattern": "Should I ↗call him or ↘text him?", "note": "Action choices."}, {"text": "Is the museum open or closed today?", "pattern": "Is the museum ↗open or ↘closed today?", "note": "Status inquiry."}, {"text": "Could you possibly hold this for a second?", "pattern": "Could you possibly hold this for a ↗second?", "note": "Tentative polite request: gentle rise."}, {"text": "Would you mind if I opened the window?", "pattern": "Would you mind if I opened the ↗window?", "note": "Courteous softening: ending ascends gently."}, {"text": "Excuse me, where is the nearest pharmacy?", "pattern": "Ex↗cuse me, ↘where is the nearest ↘pharmacy?", "note": "Polite greeting rises; Wh- question drops."}, {"text": "Good morning everyone!", "pattern": "Good ↗morning ↘everyone!", "note": "Friendly professional greeting."}, {"text": "Have a wonderful weekend ahead!", "pattern": "Have a wonderful ↘weekend a↘head!", "note": "Warm sendoff with conclusive warmth."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published'),
('reductions', 'Everyday reductions', 'intermediate', 'medium', 'us', 'Reductions help you understand fast speech and sound relaxed in conversation.', ARRAY['going to → gonna', 'want to → wanna', 'have to → hafta', 'got to → gotta']::text[], '[{"text": "I''m going to call her.", "pattern": "I''m gonna call her."}, {"text": "I want to try again.", "pattern": "I wanna try again."}, {"text": "I have to leave now.", "pattern": "I hafta leave now."}, {"text": "You''ve got to see this.", "pattern": "You gotta see this."}]'::jsonb, 'These are informal spoken forms. Do not write them in essays, emails or formal exams, and avoid them in a formal presentation.', true, 1, 'published'),
('reductions', 'kinda, sorta, lemme, gimme', 'advanced', 'medium', 'us', 'More casual reductions you will hear constantly in films and real conversation.', ARRAY['kind of → kinda', 'sort of → sorta', 'let me → lemme', 'give me → gimme', 'what do you → whaddaya']::text[], '[{"text": "It''s kind of expensive.", "pattern": "It''s kinda expensive."}, {"text": "I sort of agree.", "pattern": "I sorta agree."}, {"text": "Let me think about it.", "pattern": "Lemme think about it."}, {"text": "What do you think?", "pattern": "Whaddaya think?"}]'::jsonb, 'Informal only. In an IELTS or job interview, keep the full forms.', true, 2, 'published'),
('reductions', 'hafta, needa, useta', 'intermediate', 'medium', 'us', 'More obligation and habit reductions common in relaxed spoken English.', ARRAY['have to → hafta', 'need to → needa', 'used to → useta']::text[], '[{"text": "I need to go now.", "pattern": "I needa go now."}, {"text": "I used to live there.", "pattern": "I useta live there."}, {"text": "She has to finish it today.", "pattern": "She hasta finish it today."}]'::jsonb, 'Informal spoken forms only — never write them.', true, 3, 'published'),
('reductions', 'coulda, woulda, shoulda', 'advanced', 'medium', 'us', 'Past modal reductions — very common when talking about regrets or hypothetical situations.', ARRAY['could have → coulda', 'would have → woulda', 'should have → shoulda']::text[], '[{"text": "I could have called you.", "pattern": "I coulda called you."}, {"text": "She would have said yes.", "pattern": "She woulda said yes."}, {"text": "You should have told me.", "pattern": "You shoulda told me."}]'::jsonb, 'Informal spoken only — write ''could have'' in full in formal writing.', true, 4, 'published'),
('reductions', 'dunno, dontcha, whatcha', 'advanced', 'medium', 'us', 'Very casual reductions common in songs, films and relaxed conversation among friends.', ARRAY['don''t know → dunno', 'don''t you → dontcha', 'what are you → whatcha']::text[], '[{"text": "I don''t know.", "pattern": "I dunno."}, {"text": "Don''t you want some?", "pattern": "Dontcha want some?"}, {"text": "What are you doing?", "pattern": "Whatcha doing?"}]'::jsonb, 'Very informal — only with close friends, never in professional or exam contexts.', true, 5, 'published'),
('reductions', 'outta, offa, cuppa', 'advanced', 'medium', 'us', 'Common preposition-linked reductions in casual speech.', ARRAY['out of → outta', 'off of → offa', 'cup of → cuppa']::text[], '[{"text": "Get out of here!", "pattern": "Get outta here!"}, {"text": "Take it off of the table.", "pattern": "Take it offa the table."}, {"text": "Want a cup of tea?", "pattern": "Want a cuppa tea?"}]'::jsonb, 'Informal only.', false, 6, 'published'),
('reductions', 'c''mon, gonna be, s''more', 'intermediate', 'medium', 'us', 'Everyday exclamations and casual phrases with heavy reduction.', ARRAY['come on → c''mon', 'going to be → gonna be', 'some more → s''more']::text[], '[{"text": "Come on, let''s go!", "pattern": "C''mon, let''s go!"}, {"text": "It''s going to be great.", "pattern": "It''s gonna be great."}, {"text": "Can I get some more?", "pattern": "Can I get s''more?"}]'::jsonb, 'Informal only.', false, 7, 'published'),
('reductions', 'Reductions in casual questions', 'intermediate', 'medium', 'us', 'Question-starters reduce heavily in fast, casual conversation.', ARRAY['did you → dja', 'do you → dya', 'would you → wouldja']::text[], '[{"text": "Did you see that?", "pattern": "Dja see that?"}, {"text": "Do you want to go?", "pattern": "Dya wanna go?"}, {"text": "Would you mind?", "pattern": "Wouldja mind?"}]'::jsonb, 'Only for casual, spoken contexts.', false, 8, 'published'),
('reductions', 'Reductions with numbers and time', 'advanced', 'medium', 'us', 'Casual speech often reduces time phrases too.', ARRAY['a couple of → a couple', 'in a minute → in a min']::text[], '[{"text": "Give me a couple of minutes.", "pattern": "Give me a couple minutes."}, {"text": "I''ll be there in a minute.", "pattern": "I''ll be there in a min."}]'::jsonb, 'Fine in casual talk, not in writing.', false, 9, 'published'),
('reductions', 'probably, trying to, supposed to', 'advanced', 'medium', 'us', 'More common casual reductions heard constantly in relaxed conversation.', ARRAY['probably → prolly', 'trying to → tryna', 'supposed to → s''posed to']::text[], '[{"text": "It''s probably fine.", "pattern": "It''s prolly fine."}, {"text": "I''m trying to focus.", "pattern": "I''m tryna focus."}, {"text": "You''re supposed to call first.", "pattern": "You''re s''posed to call first."}]'::jsonb, 'Informal spoken only.', false, 10, 'published'),
('reductions', 'let''s, gimme that, y''all', 'advanced', 'medium', 'us', 'Casual reductions common among friends and in American informal speech.', ARRAY['let''s go → less go', 'give it to me → gimme that', 'you all → y''all']::text[], '[{"text": "Let''s go already!", "pattern": "Less go already!"}, {"text": "Gimme that back.", "pattern": "Gimme that back."}, {"text": "Y''all wanna come with?", "pattern": "Y''all wanna come with?"}]'::jsonb, 'Very informal — ''y''all'' is regional (Southern US) but widely understood.', false, 11, 'published'),
('reductions', 'Casual numbers in fast speech', 'advanced', 'medium', 'us', 'Round numbers reduce their middle consonant sounds in fast, casual American speech.', ARRAY['twenty → twenny', 'hundred → hunnerd']::text[], '[{"text": "It''s twenty dollars.", "pattern": "It''s twenny dollars."}, {"text": "About a hundred people showed up.", "pattern": "About a hunnerd people showed up."}]'::jsonb, 'Informal spoken only — always say the full form in formal contexts.', false, 12, 'published'),
('reductions', 'Words that shrink one syllable in casual talk', 'advanced', 'medium', 'us', 'A different set of everyday words that regularly lose a syllable in fast, relaxed speech.', ARRAY['different → diff''rent', 'general → gen''ral', 'several → sev''ral', 'camera → cam''ra']::text[], '[{"text": "That''s a different story.", "pattern": "That''s a diff''rent story."}, {"text": "We need a general idea first.", "pattern": "We need a gen''ral idea first."}, {"text": "I''ve told you several times.", "pattern": "I''ve told you sev''ral times."}]'::jsonb, 'Fine in casual speech; say the full form clearly in formal presentations.', false, 13, 'published'),
('reductions', 'I''ma and other ultra-casual forms', 'advanced', 'hard', 'us', 'Very informal reductions you''ll hear in songs and casual American speech, but should never use in professional settings.', ARRAY['I''m going to → I''ma', 'kind of like → kinda like']::text[], '[{"text": "I''ma head out now.", "pattern": "I''ma head out now."}, {"text": "It''s kinda like a sequel.", "pattern": "It''s kinda like a sequel."}]'::jsonb, 'Extremely informal — friends/song lyrics only, never professional contexts.', false, 14, 'published'),
('reductions', 'More casual greeting reductions', 'intermediate', 'easy', 'us', 'Extra everyday greeting reductions beyond what''s up / how''s it going.', ARRAY['how are you → how ya doin''', 'good to see you → good to see ya']::text[], '[{"text": "Hey, how ya doin''?", "pattern": "Hey, how ya doin''?"}, {"text": "Good to see ya, man.", "pattern": "Good to see ya, man."}]'::jsonb, 'Casual spoken forms only.', false, 15, 'published'),
('reductions', 'oughta, don''t hafta, wantcha', 'advanced', 'medium', 'us', 'More obligation and desire reductions common in relaxed American speech.', ARRAY['ought to → oughta', 'don''t have to → don''t hafta', 'want you → wantcha']::text[], '[{"text": "You oughta try this place.", "pattern": "You oughta try this place."}, {"text": "You don''t hafta come if you don''t want to.", "pattern": "You don''t hafta come if you don''t want to."}, {"text": "I wantcha to meet someone.", "pattern": "I wantcha to meet someone."}]'::jsonb, 'Informal spoken only.', false, 16, 'published'),
('reductions', 'Famous extreme reduction: ''Did you eat yet?''', 'advanced', 'hard', 'us', 'This is a classic example of how far casual American reduction can go — several words blur into what sounds like one.', ARRAY['Did you eat yet? → Jeetyet?', 'Did you already? → Jeetalready?']::text[], '[{"text": "Did you eat yet?", "pattern": "Jeetyet?"}, {"text": "No, not yet, did you?", "pattern": "No, not yet, jou?"}]'::jsonb, 'Extremely informal — for recognizing fast native speech, not for your own formal speaking.', false, 17, 'published'),
('reductions', '''because of'' and ''sort of a''', 'intermediate', 'medium', 'us', 'Two more common phrase-level reductions in casual conversation.', ARRAY['because of → ''cause of', 'sort of a → sorta a']::text[], '[{"text": "We''re late because of traffic.", "pattern": "We''re late ''cause of traffic."}, {"text": "It''s sort of a weird situation.", "pattern": "It''s sorta a weird situation."}]'::jsonb, 'Informal spoken only.', false, 18, 'published'),
('reductions', 'Casual yes/no: yep, nope, uh-huh', 'beginner', 'easy', 'us', 'Very common casual alternatives to ''yes'' and ''no'' in relaxed spoken English.', ARRAY['yes → yep / uh-huh', 'no → nope / nah']::text[], '[{"text": "Yep, sounds good to me.", "pattern": "Yep, sounds good to me."}, {"text": "Nah, I''m good, thanks.", "pattern": "Nah, I''m good, thanks."}]'::jsonb, 'Casual conversation only — use ''yes''/''no'' in formal or exam contexts.', false, 19, 'published'),
('reductions', '''want a'' (thing) vs ''want to'' (action)', 'advanced', 'medium', 'us', 'Both reduce to a similar-sounding ''wanna'', but one is followed by a noun and the other by a verb — worth noticing the difference.', ARRAY['want a (coffee) → wanna coffee', 'want to (go) → wanna go']::text[], '[{"text": "I wanna coffee.", "pattern": "want A coffee (noun)"}, {"text": "I wanna go home.", "pattern": "want TO go (verb)"}]'::jsonb, 'Informal spoken only.', false, 20, 'published'),
('reductions', 'wouldn''t have → wouldn''ta', 'advanced', 'hard', 'us', 'The negative version of ''would have'' reduces the same way as the positive form.', ARRAY['wouldn''t have → wouldn''ta']::text[], '[{"text": "I wouldn''t have said that.", "pattern": "I wouldn''ta said that."}, {"text": "She wouldn''t have known anyway.", "pattern": "She wouldn''ta known anyway."}]'::jsonb, 'Informal spoken only — write ''wouldn''t have'' in full otherwise.', false, 21, 'published'),
('reductions', 'just ''cause, gonna need', 'advanced', 'medium', 'us', 'Two more everyday reductions common in casual explanations and requests.', ARRAY['just because → just ''cause', 'going to need → gonna need']::text[], '[{"text": "I did it just ''cause I wanted to.", "pattern": "I did it just ''cause I wanted to."}, {"text": "We''re gonna need more chairs.", "pattern": "We''re gonna need more chairs."}]'::jsonb, 'Informal spoken only.', false, 22, 'published'),
('reductions', 'ain''t — am not, is not, are not', 'advanced', 'medium', 'us', '''Ain''t'' replaces am not/is not/are not/has not/have not in very casual speech and is heard everywhere in songs and informal talk.', ARRAY['I am not → I ain''t', 'that is not → that ain''t', 'you have not → you ain''t']::text[], '[{"text": "I''m not doing that.", "pattern": "I ain''t doing that."}, {"text": "That''s not right.", "pattern": "That ain''t right."}, {"text": "You haven''t seen anything yet.", "pattern": "You ain''t seen nothing yet."}]'::jsonb, 'Never use in writing or formal speech — considered non-standard grammar, even though extremely common informally.', false, 23, 'published'),
('reductions', 'gotcha — got you', 'beginner', 'easy', 'us', 'A very common casual way to say ''I understand'' or literally ''caught you''.', ARRAY['got you (understand) → gotcha', 'got you (caught) → gotcha']::text[], '[{"text": "Got you — I''ll send it by five.", "pattern": "Gotcha — I''ll send it by five."}, {"text": "I got you! You looked so surprised.", "pattern": "Gotcha! You looked so surprised."}]'::jsonb, 'Informal spoken only — say ''I understand'' or ''got it'' in professional contexts.', false, 24, 'published'),
('reductions', 'musta, mighta — must have, might have', 'advanced', 'medium', 'us', 'Modal-perfect reductions used for guesses about the past, alongside coulda/woulda/shoulda.', ARRAY['must have → musta', 'might have → mighta']::text[], '[{"text": "She must have left already.", "pattern": "She musta left already."}, {"text": "He might have forgotten.", "pattern": "He mighta forgotten."}]'::jsonb, 'Informal spoken only — write ''must have''/''might have'' in full otherwise.', false, 25, 'published'),
('reductions', 'shouldn''ta, couldn''ta — negative past modals', 'advanced', 'hard', 'us', 'The negative counterparts of coulda/woulda/shoulda, common when talking about regrets.', ARRAY['shouldn''t have → shouldn''ta', 'couldn''t have → couldn''ta']::text[], '[{"text": "You shouldn''t have said that.", "pattern": "You shouldn''ta said that."}, {"text": "I couldn''t have known.", "pattern": "I couldn''ta known."}]'::jsonb, 'Informal spoken only — write ''shouldn''t have''/''couldn''t have'' in full in formal contexts.', false, 26, 'published'),
('reductions', 'g-dropping: doin'', goin'', talkin''', 'beginner', 'easy', 'us', 'In relaxed speech, the final -ing sound often drops its ''g'', so it sounds like -in''. This happens across almost any -ing verb.', ARRAY['doing → doin''', 'going → goin''', 'talking → talkin''', 'thinking → thinkin''']::text[], '[{"text": "What are you doing?", "pattern": "Whatcha doin''?"}, {"text": "I''m just thinking out loud.", "pattern": "I''m just thinkin'' out loud."}, {"text": "We were talking about you.", "pattern": "We were talkin'' about you."}]'::jsonb, 'Casual speech only — pronounce the full ''-ing'' clearly in presentations, interviews and exams.', false, 27, 'published'),
('reductions', 'somethin'', nothin'', anythin''', 'beginner', 'easy', 'us', 'The same g-dropping pattern applies to indefinite pronouns ending in -thing.', ARRAY['something → somethin''', 'nothing → nothin''', 'anything → anythin''']::text[], '[{"text": "I need something to drink.", "pattern": "I need somethin'' to drink."}, {"text": "There''s nothing to worry about.", "pattern": "There''s nothin'' to worry about."}, {"text": "Do you need anything else?", "pattern": "Do you need anythin'' else?"}]'::jsonb, 'Casual speech only.', false, 28, 'published'),
('reductions', '''em — them', 'intermediate', 'medium', 'us', '''Them'' reduces to ''em (the ''th'' drops) after a verb, in very common casual speech.', ARRAY['tell them → tell ''em', 'get them → get ''em', 'ask them → ask ''em']::text[], '[{"text": "Tell them I said hi.", "pattern": "Tell ''em I said hi."}, {"text": "Go get them from the car.", "pattern": "Go get ''em from the car."}]'::jsonb, 'Informal spoken only — say ''them'' in full in writing or formal speech.', false, 29, 'published'),
('reductions', '''n'' — and', 'intermediate', 'medium', 'us', '''And'' reduces to a quick ''n'' sound between two closely linked words, especially in set phrases.', ARRAY['rock and roll → rock ''n'' roll', 'fish and chips → fish ''n'' chips', 'back and forth → back ''n'' forth']::text[], '[{"text": "I love rock and roll.", "pattern": "I love rock ''n'' roll."}, {"text": "We went back and forth about it.", "pattern": "We went back ''n'' forth about it."}]'::jsonb, 'Common in set phrases and fast speech — say ''and'' clearly in formal writing.', false, 30, 'published'),
('reductions', 'standalone ''cause — because', 'beginner', 'easy', 'us', '''Because'' on its own (not just ''because of'') often shortens to ''cause in casual answers.', ARRAY['because → ''cause']::text[], '[{"text": "I''m tired because I didn''t sleep well.", "pattern": "I''m tired ''cause I didn''t sleep well."}, {"text": "Why? Because I said so.", "pattern": "Why? ''Cause I said so."}]'::jsonb, 'Informal spoken only — write ''because'' in full otherwise.', false, 31, 'published'),
('reductions', '''course — of course', 'beginner', 'easy', 'us', '''Of course'' often drops its first word in quick, casual replies.', ARRAY['of course → ''course']::text[], '[{"text": "Of course I''ll help you.", "pattern": "''Course I''ll help you."}, {"text": "Can you come? Of course!", "pattern": "Can you come? ''Course!"}]'::jsonb, 'Casual spoken only.', false, 32, 'published'),
('reductions', 'aight — all right', 'beginner', 'easy', 'us', 'A very common casual pronunciation of ''all right'', used to agree or acknowledge.', ARRAY['all right → aight']::text[], '[{"text": "All right, let''s do it.", "pattern": "Aight, let''s do it."}, {"text": "Is everything all right?", "pattern": "Is everything aight?"}]'::jsonb, 'Very informal — say ''all right'' or ''okay'' in professional contexts.', false, 33, 'published'),
('reductions', 'letcha — let you', 'advanced', 'medium', 'us', '''Let you'' reduces the same way ''want you''/''wantcha'' does.', ARRAY['let you → letcha']::text[], '[{"text": "I won''t let you down.", "pattern": "I won''t letcha down."}, {"text": "I''ll let you know tomorrow.", "pattern": "I''ll letcha know tomorrow."}]'::jsonb, 'Informal spoken only.', false, 34, 'published'),
('reductions', 'jever — did you ever', 'advanced', 'hard', 'us', 'Another extreme fast-speech blend, similar to ''jeetyet'' — several words compress into one sound.', ARRAY['did you ever → jever']::text[], '[{"text": "Did you ever try sushi?", "pattern": "Jever try sushi?"}]'::jsonb, 'For recognising fast native speech, not for your own formal speaking.', false, 35, 'published'),
('reductions', 'gonna hafta — going to have to', 'advanced', 'hard', 'us', 'Two reductions stack together when ''going to'' and ''have to'' appear side by side.', ARRAY['going to have to → gonna hafta']::text[], '[{"text": "We''re going to have to leave soon.", "pattern": "We''re gonna hafta leave soon."}, {"text": "I''m going to have to call you back.", "pattern": "I''m gonna hafta call you back."}]'::jsonb, 'Informal spoken only — write ''going to have to'' in full otherwise.', false, 36, 'published'),
('reductions', 'not gonna, wasn''t gonna', 'intermediate', 'medium', 'us', 'The ''gonna'' reduction still applies with negatives and past tense.', ARRAY['not going to → not gonna', 'wasn''t going to → wasn''t gonna']::text[], '[{"text": "I''m not going to argue.", "pattern": "I''m not gonna argue."}, {"text": "She wasn''t going to come.", "pattern": "She wasn''t gonna come."}]'::jsonb, 'Informal spoken only.', false, 37, 'published'),
('reductions', 'innit — isn''t it (British)', 'advanced', 'medium', 'uk', 'A very common British English tag question reduction, used to confirm or add emphasis.', ARRAY['isn''t it → innit']::text[], '[{"text": "It''s cold today, isn''t it?", "pattern": "It''s cold today, innit?"}, {"text": "That''s mad, isn''t it?", "pattern": "That''s mad, innit?"}]'::jsonb, 'Very informal British slang — don''t use in formal speech, even in the UK.', false, 38, 'published'),
('reductions', 'whaddya say — what do you say', 'advanced', 'medium', 'us', 'A casual way to propose something or ask for agreement.', ARRAY['what do you say → whaddya say']::text[], '[{"text": "What do you say we grab lunch?", "pattern": "Whaddya say we grab lunch?"}]'::jsonb, 'Informal spoken only.', false, 39, 'published'),
('reductions', 'y''know — you know (filler)', 'beginner', 'easy', 'us', 'An extremely common filler phrase in casual spoken English, used while thinking or for emphasis.', ARRAY['you know → y''know']::text[], '[{"text": "It was, you know, kind of awkward.", "pattern": "It was, y''know, kinda awkward."}, {"text": "You know what I mean?", "pattern": "Y''know what I mean?"}]'::jsonb, 'Casual filler only — overusing it sounds unpolished even informally.', false, 40, 'published'),
('reductions', 's''up — what''s up', 'beginner', 'easy', 'us', 'A very casual greeting, shortened from ''what''s up''.', ARRAY['what''s up → s''up']::text[], '[{"text": "Hey, what''s up?", "pattern": "Hey, s''up?"}]'::jsonb, 'Very informal greeting between friends only.', false, 41, 'published'),
('reductions', 'tell ''im, ask ''er — him, her', 'intermediate', 'medium', 'us', '''Him'' and ''her'' also weaken in casual speech, similar to ''them'' → ''em.', ARRAY['tell him → tell ''im', 'ask her → ask ''er']::text[], '[{"text": "Tell him I called.", "pattern": "Tell ''im I called."}, {"text": "Ask her what she thinks.", "pattern": "Ask ''er what she thinks."}]'::jsonb, 'Informal spoken only.', false, 42, 'published'),
('reductions', 'kinda sorta — combined hedge', 'intermediate', 'medium', 'us', '''Kinda'' and ''sorta'' are often combined for extra hedging in very casual speech.', ARRAY['kind of sort of → kinda sorta']::text[], '[{"text": "It''s kind of, sort of, complicated.", "pattern": "It''s kinda sorta complicated."}]'::jsonb, 'Very informal — avoid in any professional or exam context.', false, 43, 'published'),
('reductions', 'dincha — didn''t you', 'advanced', 'hard', 'us', 'Another fast-speech question-starter blend, alongside dja and wouldja.', ARRAY['didn''t you → dincha']::text[], '[{"text": "You saw that, didn''t you?", "pattern": "You saw that, dincha?"}]'::jsonb, 'For recognising fast native speech, not for your own formal speaking.', false, 44, 'published'),
('reductions', 'hadta — had to', 'intermediate', 'medium', 'us', 'The past-tense form of ''have to'' reduces the same way the present form does.', ARRAY['had to → hadta']::text[], '[{"text": "I had to leave early.", "pattern": "I hadta leave early."}]'::jsonb, 'Informal spoken only.', false, 45, 'published'),
('reductions', 'willcha — will you', 'advanced', 'medium', 'us', 'A casual reduction used in informal requests, alongside wouldja and couldja-style forms.', ARRAY['will you → willcha']::text[], '[{"text": "Will you help me with this?", "pattern": "Willcha help me with this?"}]'::jsonb, 'Informal spoken only.', false, 46, 'published'),
('reductions', 'lotsa, buncha — lots of, bunch of', 'intermediate', 'medium', 'us', 'Quantity phrases with ''of'' reduce the same way ''cup of'' does in ''cuppa''.', ARRAY['lots of → lotsa', 'bunch of → buncha']::text[], '[{"text": "There''s lots of food left.", "pattern": "There''s lotsa food left."}, {"text": "I have a bunch of questions.", "pattern": "I have a buncha questions."}]'::jsonb, 'Informal spoken only.', false, 47, 'published'),
('reductions', 'helluva — hell of a', 'advanced', 'medium', 'us', 'A strong informal intensifier meaning ''a very impressive/big''.', ARRAY['hell of a → helluva']::text[], '[{"text": "That was a hell of a game.", "pattern": "That was a helluva game."}]'::jsonb, 'Mildly crude — fine with friends, avoid in professional or polite settings.', false, 48, 'published'),
('reductions', 'howdy — how do you do', 'beginner', 'easy', 'us', 'A historical reduction of the old greeting ''how do you do'', now its own casual, friendly greeting (especially in the Southern US).', ARRAY['how do you do → howdy']::text[], '[{"text": "How do you do, folks?", "pattern": "Howdy, folks!"}]'::jsonb, 'Casual, friendly greeting only.', false, 49, 'published'),
('reductions', 's''pose — I suppose', 'intermediate', 'medium', 'us', '''I suppose'' commonly drops its middle syllable in casual speech, used to express mild uncertainty or reluctant agreement — distinct from ''supposed to'' → s''posed to.', ARRAY['I suppose → I s''pose']::text[], '[{"text": "I suppose you''re right.", "pattern": "I s''pose you''re right."}, {"text": "I suppose so.", "pattern": "I s''pose so."}]'::jsonb, 'Informal spoken only — write ''I suppose'' in full otherwise.', false, 50, 'published'),
('reductions', 'Practice', 'intermediate', 'medium', 'us', 'Master reductions across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "What do you want to do?", "pattern": "Whaddya wanna do?", "note": "Extreme reduction of helper words into natural flow."}, {"text": "I am going to call him back.", "pattern": "I''m gonna call ''im back.", "note": "''going to'' -> ''gonna''; ''him'' -> ''''im''."}, {"text": "We have got to hurry up.", "pattern": "We gotta hurry up.", "note": "''have got to'' reduces to ''gotta''."}, {"text": "Do you want a cup of coffee?", "pattern": "Wanna cup a coffee?", "note": "''want a'' -> ''wanna''; ''of'' -> ''a'' /ə/."}, {"text": "She has to study for the test.", "pattern": "She hasta study fer the test.", "note": "''has to'' -> ''hasta'' /hæstə/; ''for'' -> /fər/."}, {"text": "Let me know when you arrive.", "pattern": "Lemme know when ya arrive.", "note": "''let me'' -> ''lemme''; ''you'' -> ''ya''."}, {"text": "Give me a minute please.", "pattern": "Gimme a minute please.", "note": "''give me'' -> ''gimme''."}, {"text": "Could you pass the salt?", "pattern": "Couldja pass the salt?", "note": "''could you'' -> ''couldja'' /kʊdʒə/."}, {"text": "Would you mind waiting outside?", "pattern": "Wouldja mind waitin'' outside?", "note": "''would you'' -> ''wouldja''."}, {"text": "What did you say to him?", "pattern": "Whaddya say to ''im?", "note": "''what did you'' -> ''whaddya''; ''him'' -> ''''im''."}, {"text": "I should have told you earlier.", "pattern": "I shoulda told ya earlier.", "note": "''should have'' -> ''shoulda'' /ʃʊdə/."}, {"text": "We could have won that match.", "pattern": "We coulda won that match.", "note": "''could have'' -> ''coulda'' /kʊdə/."}, {"text": "They would have helped us if we asked.", "pattern": "They woulda helped us if we asked.", "note": "''would have'' -> ''woulda'' /wʊdə/."}, {"text": "You must have forgotten the keys.", "pattern": "You musta fergot the keys.", "note": "''must have'' -> ''musta'' /mʌstə/."}, {"text": "It might have been an honest mistake.", "pattern": "It mighta been an honest mistake.", "note": "''might have'' -> ''mighta'' /maɪtə/."}, {"text": "He used to live in Chicago.", "pattern": "He usta live in Chicago.", "note": "''used to'' -> ''usta'' /juːstə/."}, {"text": "I am supposed to meet her at noon.", "pattern": "I''m sposta meet ''er at noon.", "note": "''supposed to'' -> ''sposta'' /spoʊstə/."}, {"text": "Do you need to go to the store?", "pattern": "D''ya needa go da the store?", "note": "''need to'' -> ''needa''; ''to'' -> /də/."}, {"text": "Try to finish before lunch.", "pattern": "Try da finish fer lunch.", "note": "''to'' -> /də/; ''for'' -> /fər/."}, {"text": "I kind of like this design.", "pattern": "I kinda like this design.", "note": "''kind of'' -> ''kinda'' /kaɪndə/."}, {"text": "She is sort of upset about the delay.", "pattern": "She''s sorta upset about the delay.", "note": "''sort of'' -> ''sorta'' /sɔːrtə/."}, {"text": "Lots of people were in attendance.", "pattern": "Lotsa people were in attendance.", "note": "''lots of'' -> ''lotsa'' /lɒtsə/."}, {"text": "Out of nowhere a storm began.", "pattern": "Outta nowhere a storm began.", "note": "''out of'' -> ''outta'' /aʊtə/."}, {"text": "Front of the line was completely crowded.", "pattern": "Fronta the line was crowded.", "note": "''front of'' -> ''fronta''."}, {"text": "I am going to get some water.", "pattern": "I''mma get some water.", "note": "''I am going to'' reduces to ''I''mma'' in informal speech."}, {"text": "Don''t you want to join us?", "pattern": "Doncha wanna join us?", "note": "''don''t you'' -> ''doncha''; ''want to'' -> ''wanna''."}, {"text": "Didn''t you see the road sign?", "pattern": "Didn''tcha see the road sign?", "note": "''didn''t you'' -> ''didn''tcha''."}, {"text": "Haven''t you finished that chapter yet?", "pattern": "Haven''tcha finished that chapter yet?", "note": "''haven''t you'' -> ''haven''tcha''."}, {"text": "Can you bring some bread and butter?", "pattern": "Can ya bring some bread ''n butter?", "note": "''and'' reduces to syllabic ''n'' /n/."}, {"text": "We worked hard day and night.", "pattern": "We worked hard day ''n night.", "note": "''day and night'' -> ''day ''n night''."}, {"text": "Take it or leave it.", "pattern": "Take idder leave it.", "note": "''or'' reduces to /ər/; ''it or'' flaps seamlessly."}, {"text": "More or less what I expected.", "pattern": "More ''er less what I expected.", "note": "''or'' reduces to unstressed /ər/."}, {"text": "Black and white photography.", "pattern": "Black ''n white photography.", "note": "''and'' reduces to /n/ between stops."}, {"text": "He said that he was busy.", "pattern": "He said th''t he was busy.", "note": "Relative ''that'' reduces to /ðət/ with schwa."}, {"text": "I know that she is right.", "pattern": "I know th''t she''s right.", "note": "Conjunction ''that'' is weak and short."}, {"text": "We hope that everything goes smoothly.", "pattern": "We hope th''t everything goes smoothly.", "note": "''that'' takes /ðət/."}, {"text": "Tell them to wait downstairs.", "pattern": "Tell ''em to wait downstairs.", "note": "''them'' reduces to ''''em'' /əm/."}, {"text": "Show them around the new campus.", "pattern": "Show ''em around the new campus.", "note": "''them'' -> ''''em''."}, {"text": "Ask them if they are ready.", "pattern": "Ask ''em if they''re ready.", "note": "''them'' -> ''''em''."}, {"text": "I bought some apples for breakfast.", "pattern": "I bought s''m apples fer breakfast.", "note": "''some'' -> /səm/; ''for'' -> /fər/."}, {"text": "This gift is for you.", "pattern": "This gift is fer ya.", "note": "''for'' -> /fər/; ''you'' -> /jə/."}, {"text": "Are you ready to order?", "pattern": "Er ya ready ta order?", "note": "''are'' -> /ər/; ''you'' -> /jə/; ''to'' -> /tə/."}, {"text": "Where were you all morning?", "pattern": "Where wer ya all morning?", "note": "''were'' reduces to /wər/."}, {"text": "What can I do for you today?", "pattern": "What kn I do fer ya today?", "note": "''can'' -> /kən/; ''for'' -> /fər/; ''you'' -> /jə/."}, {"text": "As far as I can tell.", "pattern": "Ez far ez I kn tell.", "note": "''as'' -> /əz/; ''can'' -> /kən/."}, {"text": "He is as tall as his father.", "pattern": "He''s ez tall ez ''is father.", "note": "''as'' -> /əz/; ''his'' -> /ɪz/ without /h/."}, {"text": "Do they know what time it is?", "pattern": "D''they know what time iddis?", "note": "''do they'' -> /dðeɪ/; ''it is'' -> /ɪdɪz/."}, {"text": "Does she want to tag along?", "pattern": "D''she wanna tag along?", "note": "''does she'' -> /dʃiː/; ''want to'' -> ''wanna''."}, {"text": "Has he answered the email yet?", "pattern": "''Zhe answered the email yet?", "note": "''has he'' loses /h/ and reduces to /æzi/."}, {"text": "It has been raining all afternoon.", "pattern": "It''s bin raining all afternoon.", "note": "''has been'' contracts and reduces to /ɪts bɪn/."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published'),
('rhythm', 'English is stress-timed', 'beginner', 'medium', 'us', 'Stressed syllables land on a steady beat. The weak syllables between them get squeezed to keep the timing.', ARRAY['Tap the table on each capital letter.', 'Keep the beats even, however many small words sit between them.']::text[], '[{"text": "DOGS EAT BONES.", "pattern": "3 beats"}, {"text": "The DOGS will EAT the BONES.", "pattern": "still 3 beats"}, {"text": "The DOGS will have EAten the BONES.", "pattern": "still 3 beats"}, {"text": "I''ll SEE you at the STAtion at SEven.", "pattern": "3 beats"}]'::jsonb, '', true, 1, 'published'),
('rhythm', 'Rhythm in real conversation', 'advanced', 'hard', 'us', 'Shadow these lines and copy the timing before you worry about the individual sounds.', ARRAY['Keep the weak words fast and quiet.', 'Do not add a pause after every word.']::text[], '[{"text": "I was gonna call you, but I got stuck at work.", "pattern": "CALL … STUCK … WORK"}, {"text": "To be honest, I''d rather stay home tonight.", "pattern": "HONest … RAther … HOME … toNIGHT"}, {"text": "It depends on how much time we''ve got.", "pattern": "dePENDS … MUCH TIME … GOT"}]'::jsonb, '', true, 2, 'published'),
('rhythm', 'Counting beats, not syllables', 'beginner', 'medium', 'us', 'A sentence with more words can still have the same number of beats — that''s the key idea of stress-timing.', '{}'::text[], '[{"text": "JOHN likes TEA.", "pattern": "2 beats"}, {"text": "JOHN would like some TEA.", "pattern": "still 2 beats"}, {"text": "JOHN would have liked some TEA.", "pattern": "still 2 beats"}]'::jsonb, '', true, 3, 'published'),
('rhythm', 'Tongue twisters for rhythm control', 'advanced', 'hard', 'us', 'Tongue twisters force you to keep a steady rhythm even when the sounds are tricky — slow down before speeding up.', '{}'::text[], '[{"text": "Peter Piper picked a peck of pickled peppers.", "pattern": "PEter PIper PICKED a PECK"}, {"text": "She sells seashells by the seashore.", "pattern": "SHE SELLS SEAshells by the SEAshore"}, {"text": "Red lorry, yellow lorry.", "pattern": "RED LORry, YELLow LORry"}]'::jsonb, '', true, 4, 'published'),
('rhythm', 'Rhythm in short answers', 'beginner', 'easy', 'us', 'Even a short answer has a natural beat — don''t say every word with equal force.', '{}'::text[], '[{"text": "Yes, I THINK so.", "pattern": "1 beat"}, {"text": "No, not REALly.", "pattern": "1 beat"}, {"text": "Sure, why NOT?", "pattern": "1 beat"}]'::jsonb, '', true, 5, 'published'),
('rhythm', 'Rhythm in numbers and lists', 'intermediate', 'medium', 'us', 'Reciting numbers or a list still keeps a steady beat on each stressed item.', '{}'::text[], '[{"text": "ONE, TWO, THREE, FOUR, FIVE.", "pattern": "even beats"}, {"text": "MONday, TUESday, WEDnesday.", "pattern": "even beats on each day"}]'::jsonb, '', false, 6, 'published'),
('rhythm', 'Rhythm practice with nursery-rhyme patterns', 'intermediate', 'medium', 'us', 'Simple rhymes have an obvious, exaggerated beat — great for building a feel for stress-timing.', '{}'::text[], '[{"text": "TWINkle TWINkle LITtle STAR.", "pattern": "4 even beats"}, {"text": "JACK and JILL went UP the HILL.", "pattern": "4 even beats"}]'::jsonb, '', false, 7, 'published'),
('rhythm', 'Rhythm in a longer natural sentence', 'advanced', 'hard', 'us', 'Longer sentences keep the same stress-timed feel — the weak words between beats just move faster.', '{}'::text[], '[{"text": "I would have called you earlier, but my phone was dead all afternoon.", "pattern": "CALLED … EARLier … PHONE … DEAD … AFternoon"}]'::jsonb, '', false, 8, 'published'),
('rhythm', 'Rhythm in questions', 'intermediate', 'medium', 'us', 'Questions keep the same stress-timed beat as statements — the question words and key content words carry the rhythm.', '{}'::text[], '[{"text": "WHERE did you PUT the KEYS?", "pattern": "3 beats"}, {"text": "WHY would he DO that?", "pattern": "3 beats"}]'::jsonb, '', false, 9, 'published'),
('rhythm', 'Rhythm buildup drill', 'advanced', 'hard', 'us', 'The classic buildup drill: the same core beats stay steady as you add more small words around them.', '{}'::text[], '[{"text": "CATS CHASE MICE.", "pattern": "3 beats"}, {"text": "The CATS will CHASE the MICE.", "pattern": "still 3 beats"}, {"text": "The CATS would have CHASED the MICE.", "pattern": "still 3 beats"}, {"text": "The CATS would have been CHASing the MICE all NIGHT.", "pattern": "4 beats now — one new idea added"}]'::jsonb, '', false, 10, 'published'),
('rhythm', 'Rhythm in idioms', 'advanced', 'hard', 'us', 'Idioms have a fixed, sing-song rhythm as a whole chunk — say them as one rhythmic unit.', '{}'::text[], '[{"text": "BETTER late than NEVer.", "pattern": "2 beats"}, {"text": "ACtions speak LOUDer than WORDS.", "pattern": "3 beats"}]'::jsonb, '', false, 11, 'published'),
('rhythm', 'Rhythm in advertising slogans', 'intermediate', 'medium', 'us', 'Slogans are written to have a catchy, very regular beat — great, memorable rhythm practice.', '{}'::text[], '[{"text": "JUST DO it.", "pattern": "2 strong beats"}, {"text": "Have it YOUR way.", "pattern": "2 beats"}]'::jsonb, '', false, 12, 'published'),
('rhythm', 'How English rhythm differs from syllable-timed languages', 'advanced', 'hard', 'us', 'In syllable-timed languages every syllable takes roughly equal time; English is stress-timed, so only the stressed syllables are evenly spaced and everything else speeds up or slows down to fit.', ARRAY['This is why English can sound ''fast'' in the unstressed parts and ''slow'' on stressed words.']::text[], '[{"text": "I want to go.", "pattern": "3 words, 1 beat: I want to GO."}, {"text": "I would like to be able to go.", "pattern": "8 words, still close to 1-2 beats: I''d LIKE to be Able to GO."}]'::jsonb, '', false, 13, 'published'),
('rhythm', 'Rhythm giving a short toast or speech', 'advanced', 'hard', 'us', 'Toasts and short speeches use a slow, deliberate, evenly-spaced rhythm for effect.', '{}'::text[], '[{"text": "To FRIENDship, to LAUGHter, and to many more YEARS together.", "pattern": "3 strong evenly-spaced beats"}]'::jsonb, '', false, 14, 'published'),
('rhythm', 'Clapping out the beat', 'beginner', 'easy', 'us', 'A simple physical drill: clap only on the stressed syllables while saying the sentence, keeping the claps perfectly even.', '{}'::text[], '[{"text": "(clap) SHE (clap) LIKES (clap) TEA.", "pattern": "3 even claps"}, {"text": "(clap) SHE would (clap) LIKE some (clap) TEA.", "pattern": "still 3 even claps"}]'::jsonb, '', false, 15, 'published'),
('rhythm', 'Rhythm in a fast native dialogue snippet', 'advanced', 'hard', 'us', 'Real fast dialogue keeps a steady stress beat even though a lot of small words are squeezed in between.', '{}'::text[], '[{"text": "A: You comin'' or what? B: Yeah, gimme a sec, I''m almost ready.", "pattern": "COMin'' … WHAT / YEAH … SEC … ALmost … REAdy"}]'::jsonb, '', false, 16, 'published'),
('rhythm', 'Rhythm in a short poem', 'advanced', 'hard', 'us', 'Poetry often has a very deliberate, regular beat — a great way to feel stress-timing clearly.', '{}'::text[], '[{"text": "The ROAD not TAKen MADE all the DIFference.", "pattern": "4 even beats"}]'::jsonb, '', false, 17, 'published'),
('rhythm', 'Rhythm: excited fast beats vs calm slow beats', 'intermediate', 'medium', 'us', 'The same sentence structure can sound excited or calm just by changing the speed between beats, not the beats themselves.', '{}'::text[], '[{"text": "WE WON the GAME!", "pattern": "fast, energetic beats = excited"}, {"text": "We WON the game.", "pattern": "slow, even beats = calm"}]'::jsonb, '', false, 18, 'published'),
('rhythm', 'Rhythm with names and greetings', 'beginner', 'easy', 'us', 'Greeting someone by name keeps a natural two-beat rhythm.', '{}'::text[], '[{"text": "HI, SARah!", "pattern": "2 beats"}, {"text": "MORNing, JOHN!", "pattern": "2 beats"}]'::jsonb, '', false, 19, 'published'),
('rhythm', 'Rhythm in an emphatic argument', 'advanced', 'hard', 'us', 'Making a firm point uses stronger, more forceful beats on the key words than normal conversation.', '{}'::text[], '[{"text": "That is NOT what I SAID.", "pattern": "strong, forceful beats"}, {"text": "I have TOLD you THREE times.", "pattern": "strong, forceful beats"}]'::jsonb, '', false, 20, 'published'),
('rhythm', 'Rhythm reading numbers aloud', 'beginner', 'easy', 'us', 'Reading a string of numbers keeps a light, even beat on each digit or group.', '{}'::text[], '[{"text": "oh SEven, TWO, THREE, FIVE", "pattern": "even beats"}, {"text": "TWENty, FORty, SIXty", "pattern": "even beats"}]'::jsonb, '', false, 21, 'published'),
('rhythm', 'Rhythm in customer service scripts', 'intermediate', 'medium', 'us', 'Service phrases have a friendly, even, welcoming rhythm.', '{}'::text[], '[{"text": "WELcome IN, how can I HELP you toDAY?", "pattern": "even, friendly beats"}]'::jsonb, '', false, 22, 'published'),
('rhythm', 'Repetition drill for rhythm confidence', 'beginner', 'easy', 'us', 'Repeat the same short sentence five times, keeping the beat perfectly identical each time — builds automatic rhythm control.', '{}'::text[], '[{"text": "I LIKE it. I LIKE it. I LIKE it.", "pattern": "identical 2-beat rhythm each repeat"}]'::jsonb, '', false, 23, 'published'),
('rhythm', 'Rhythm in a weather report', 'intermediate', 'medium', 'us', 'Weather reports have a brisk, professional, evenly-paced rhythm.', '{}'::text[], '[{"text": "TOday we''re LOOKing at CLEAR SKIES and MILD TEMPeratures.", "pattern": "brisk, even beats"}]'::jsonb, '', false, 24, 'published'),
('rhythm', 'Rhythm contrast: formal vs casual delivery', 'advanced', 'hard', 'us', 'The same message keeps stress-timed rhythm in both registers, but casual speech squeezes the weak words much more.', '{}'::text[], '[{"text": "I would like to request some additional information.", "pattern": "formal — weak words still fairly clear"}, {"text": "Can you send me more info?", "pattern": "casual — weak words squeezed hard"}]'::jsonb, '', false, 25, 'published'),
('rhythm', 'Rhythm with consonant-cluster tongue twisters', 'advanced', 'hard', 'us', 'Harder tongue twisters test whether you can keep the beat steady even when individual sounds are tricky.', '{}'::text[], '[{"text": "Six thick thistle sticks.", "pattern": "SIX THICK THIStle STICKS"}, {"text": "Trucks try to track the tracks.", "pattern": "TRUCKS TRY to TRACK the TRACKS"}]'::jsonb, '', false, 26, 'published'),
('rhythm', 'Rhythm across a two-sentence mini exchange', 'intermediate', 'medium', 'us', 'Practise keeping a natural beat across a full back-and-forth exchange, not just one sentence.', '{}'::text[], '[{"text": "A: WHAT time is the MEETing? B: It''s at THREE, I THINK.", "pattern": "even beats across both turns"}]'::jsonb, '', false, 27, 'published'),
('rhythm', 'Rhythm in giving commands', 'beginner', 'easy', 'us', 'Short commands keep a punchy, even beat on each key word.', '{}'::text[], '[{"text": "STOP right THERE.", "pattern": "2 beats"}, {"text": "SIT down and LISten.", "pattern": "3 beats"}]'::jsonb, '', false, 28, 'published'),
('rhythm', 'Rhythm reading a menu aloud', 'beginner', 'easy', 'us', 'Reading menu items keeps a light, even rhythm on each dish name.', '{}'::text[], '[{"text": "GRILLED SALmon, ROAST CHICKen, VEGgie PASta.", "pattern": "even beats on each dish"}]'::jsonb, '', false, 29, 'published'),
('rhythm', 'Rhythm in a simple children''s song', 'beginner', 'easy', 'us', 'Children''s songs have an exaggerated, super-regular beat — perfect for feeling stress-timing.', '{}'::text[], '[{"text": "ROW, ROW, ROW your BOAT.", "pattern": "4 even beats"}]'::jsonb, '', false, 30, 'published'),
('rhythm', 'Rhythm mini-dialogue with contrastive stress', 'advanced', 'hard', 'us', 'Practise keeping even beats even when a word is extra-stressed for contrast.', '{}'::text[], '[{"text": "A: Did SHE call you? B: No, HE called me.", "pattern": "contrastive stress, still even beats"}]'::jsonb, '', false, 31, 'published'),
('rhythm', 'Rhythm plus linking combined', 'advanced', 'hard', 'us', 'Real fluent speech combines a steady beat with linked, reduced words between the beats.', '{}'::text[], '[{"text": "I WANna GO to the STORE.", "pattern": "3 beats, ''wanna/to the'' squeezed between"}]'::jsonb, '', false, 32, 'published'),
('rhythm', 'Rhythm in famous movie quotes', 'intermediate', 'medium', 'us', 'Iconic movie lines have a very deliberate, memorable rhythm — great, fun practice material.', '{}'::text[], '[{"text": "MAY the FORCE be with YOU.", "pattern": "3 even beats"}, {"text": "I''ll be BACK.", "pattern": "1 strong beat"}]'::jsonb, '', false, 33, 'published'),
('rhythm', 'Rhythm building intensity across a short speech', 'advanced', 'hard', 'us', 'A motivational speech often speeds up and strengthens the beats as it builds toward the end.', '{}'::text[], '[{"text": "We CAN do this. We WILL do this. We''re GOing to WIN.", "pattern": "beats get stronger and closer together"}]'::jsonb, '', false, 34, 'published'),
('rhythm', 'Rhythm in group chants and cheers', 'beginner', 'easy', 'us', 'Chants use a very simple, repeated, rock-solid beat.', '{}'::text[], '[{"text": "LET''S GO TEAM! LET''S GO TEAM!", "pattern": "identical repeated beat"}]'::jsonb, '', false, 35, 'published'),
('rhythm', 'Rhythm with alliteration', 'advanced', 'hard', 'us', 'Alliterative phrases (repeated starting sounds) still follow the same stress-timed beat rules.', '{}'::text[], '[{"text": "BIG BLUE BALLoons BOUNCED by.", "pattern": "4 beats"}]'::jsonb, '', false, 36, 'published'),
('rhythm', 'Rhythm describing a weather map', 'intermediate', 'medium', 'us', 'Weather-map narration has a brisk, list-like rhythm moving from region to region.', '{}'::text[], '[{"text": "RAIN in the NORTH, SUN in the SOUTH, CLOUDS in beTWEEN.", "pattern": "even beats across the list"}]'::jsonb, '', false, 37, 'published'),
('rhythm', 'Rhythm reading a recipe step by step', 'intermediate', 'medium', 'us', 'Recipe steps have a calm, even beat guiding the listener through each action.', '{}'::text[], '[{"text": "MIX the FLOUR, ADD the EGGS, STIR it WELL.", "pattern": "even beats on each action"}]'::jsonb, '', false, 38, 'published'),
('rhythm', 'Rhythm and pausing combined drill', 'advanced', 'hard', 'us', 'Even with a pause between chunks, the beat inside each chunk should still feel steady and even.', '{}'::text[], '[{"text": "When I WAS a KID / I LOVED to CLIMB TREES.", "pattern": "even beats within each chunk, pause between"}]'::jsonb, '', false, 39, 'published'),
('rhythm', 'Rhythm giving genuine compliments', 'beginner', 'easy', 'us', 'Compliments keep a warm, even beat on the praised quality.', '{}'::text[], '[{"text": "That''s a GREAT idea!", "pattern": "2 beats"}, {"text": "You did REALly WELL.", "pattern": "2 beats"}]'::jsonb, '', false, 40, 'published'),
('rhythm', 'Rhythm counting objects', 'beginner', 'easy', 'us', 'Counting things aloud naturally falls into a light, even beat.', '{}'::text[], '[{"text": "ONE apple, TWO oranges, THREE bananas.", "pattern": "even beats on each number"}]'::jsonb, '', false, 41, 'published'),
('rhythm', 'Rhythm describing a daily schedule', 'intermediate', 'medium', 'us', 'Schedule descriptions keep an even beat on each time and activity.', '{}'::text[], '[{"text": "MEETing at NINE, LUNCH at NOON, GYM at SIX.", "pattern": "even beats across the schedule"}]'::jsonb, '', false, 42, 'published'),
('rhythm', 'Rhythm in short exclaimed reactions', 'beginner', 'easy', 'us', 'Quick reactions have a snappy, single strong beat.', '{}'::text[], '[{"text": "NO way!", "pattern": "1 beat"}, {"text": "So COOL!", "pattern": "1 beat"}]'::jsonb, '', false, 43, 'published'),
('rhythm', 'Rhythm in minimal-word answers', 'intermediate', 'medium', 'us', 'Even a one- or two-word answer carries a clear beat, not a flat mumble.', '{}'::text[], '[{"text": "PRObably.", "pattern": "1 beat"}, {"text": "NOT REALly.", "pattern": "2 beats"}]'::jsonb, '', false, 44, 'published'),
('rhythm', 'Rhythm in a radio advertisement', 'intermediate', 'medium', 'us', 'Radio ads use an energetic, punchy, very regular beat to stay memorable.', '{}'::text[], '[{"text": "COME on DOWN to SUPer SAVE, where PRICes NEVer STOP FALLing!", "pattern": "punchy, regular beats"}]'::jsonb, '', false, 45, 'published'),
('rhythm', 'Rhythm building from one word to a full sentence', 'beginner', 'easy', 'us', 'Start with just the stressed word, then rebuild the full sentence around it, keeping that word''s beat unchanged.', '{}'::text[], '[{"text": "GO.", "pattern": "1 beat"}, {"text": "Let''s GO.", "pattern": "1 beat, same weight"}, {"text": "I think we should GO now.", "pattern": "1 beat, same weight on ''go''"}]'::jsonb, '', false, 46, 'published'),
('rhythm', 'Rhythm in a short apology speech', 'advanced', 'hard', 'us', 'A sincere apology keeps a slow, steady, even beat — rushing it can sound insincere.', '{}'::text[], '[{"text": "I''m SORry. I was WRONG. It won''t HAPpen aGAIN.", "pattern": "slow, even, deliberate beats"}]'::jsonb, '', false, 47, 'published'),
('rhythm', 'Rhythm reading a short news headline', 'intermediate', 'medium', 'us', 'News headlines are read with clear, confident, evenly-spaced beats on the key facts.', '{}'::text[], '[{"text": "CITY COUNcil APproves NEW PARK PLAN.", "pattern": "even, confident beats"}]'::jsonb, '', false, 48, 'published'),
('rhythm', 'Rhythm: yes/no answer plus a quick follow-up', 'intermediate', 'medium', 'us', 'A short answer plus a quick extra detail still keeps one connected, even rhythm.', '{}'::text[], '[{"text": "YEAH, I''m PRETty SURE.", "pattern": "one connected rhythm"}]'::jsonb, '', false, 49, 'published'),
('rhythm', 'Rhythm in a short farewell speech', 'advanced', 'hard', 'us', 'A warm goodbye speech uses a slow, even, heartfelt beat, similar to a toast.', '{}'::text[], '[{"text": "It''s been an HONor WORKing with all of YOU.", "pattern": "slow, even, heartfelt beats"}]'::jsonb, '', false, 50, 'published'),
('rhythm', 'Practice', 'intermediate', 'medium', 'us', 'Master rhythm across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "Dogs bark loudly.", "pattern": "DOGS BARK LOUD-ly.", "note": "Three content beats in a row: equal spacing between pulses."}, {"text": "The dogs will bark quite loudly.", "pattern": "the DOGS will BARK quite LOUD-ly.", "note": "Grammar words compress so the three beats stay evenly timed."}, {"text": "Birds sing songs.", "pattern": "BIRDS SING SONGS.", "note": "Three staccato beats at constant musical intervals."}, {"text": "The wild birds were singing their sweet songs.", "pattern": "the WILD BIRDS were SING-ing their SWEET SONGS.", "note": "Unstressed syllables squeeze into the tempo."}, {"text": "Rain falls down.", "pattern": "RAIN FALLS DOWN.", "note": "Slow, deliberate three-beat pulse."}, {"text": "Cold rain was falling all afternoon.", "pattern": "COLD RAIN was FALL-ing all af-ter-NOON.", "note": "Maintain identical time intervals between the stress peaks."}, {"text": "Clock ticks fast.", "pattern": "CLOCK TICKS FAST.", "note": "Three punchy, equal beats."}, {"text": "The old wall clock was ticking away so fast.", "pattern": "the OLD WALL CLOCK was TICK-ing a-way so FAST.", "note": "Notice how ''was'', ''a-way'', ''so'' speed up to preserve the beat."}, {"text": "Trains stop here.", "pattern": "TRAINS STOP HERE.", "note": "Three heavy content monosyllables."}, {"text": "All the express trains must stop right over here.", "pattern": "ALL the ex-PRESS TRAINS must STOP right O-ver HERE.", "note": "Rhythmic constancy despite multiple syllables."}, {"text": "Fire burns bright.", "pattern": "FIRE BURNS BRIGHT.", "note": "Three resonant stress peaks."}, {"text": "A warm camp fire was burning extremely bright.", "pattern": "a WARM CAMP FIRE was BURN-ing ex-TREME-ly BRIGHT.", "note": "Keep the metronome ticking evenly across the beats."}, {"text": "Stars shine bright at night.", "pattern": "STARS SHINE BRIGHT at NIGHT.", "note": "Four beats: steady musical progression."}, {"text": "Millions of bright stars were shining throughout the dark night.", "pattern": "MIL-lions of BRIGHT STARS were SHIN-ing through-OUT the DARK NIGHT.", "note": "Squeeze unstressed syllables without rushing the main beats."}, {"text": "Kids love sweets.", "pattern": "KIDS LOVE SWEETS.", "note": "Tri-syllabic stress beat."}, {"text": "Most young kids really love tasty sweet snacks.", "pattern": "MOST YOUNG KIDS REAL-ly LOVE TAST-y SWEET SNACKS.", "note": "Clustered stresses followed by rapid reductions."}, {"text": "Wind blows hard.", "pattern": "WIND BLOWS HARD.", "note": "Three monosyllabic hammer beats."}, {"text": "A chilly north wind had been blowing unusually hard.", "pattern": "a CHIL-ly NORTH WIND had been BLOW-ing un-U-su-al-ly HARD.", "note": "Notice how ''had been'' and ''unusually'' glide between beats."}, {"text": "Cook good food.", "pattern": "COOK GOOD FOOD.", "note": "Three heavy vowel beats."}, {"text": "Always cook fresh, delicious food for your dinner.", "pattern": "AL-ways COOK FRESH de-LI-cious FOOD for your DIN-ner.", "note": "Equal spacing between prominent syllables."}, {"text": "Ships cross seas.", "pattern": "SHIPS CROSS SEAS.", "note": "Three rhythmic pulses."}, {"text": "Enormous cargo ships were crossing rough stormy seas.", "pattern": "e-NOR-mous CAR-go SHIPS were CROSS-ing ROUGH STOR-my SEAS.", "note": "Stress-timed acceleration of weak syllables."}, {"text": "Bears sleep through winter.", "pattern": "BEARS SLEEP through WIN-ter.", "note": "Three content beats."}, {"text": "Wild brown bears always sleep peacefully throughout the harsh winter.", "pattern": "WILD BROWN BEARS AL-ways SLEEP PEACE-ful-ly through-OUT the HARSH WIN-ter.", "note": "Polysyllabic words compressed between peaks."}, {"text": "Bells chime loud.", "pattern": "BELLS CHIME LOUD.", "note": "Three resonant bell-strike beats."}, {"text": "Ancient bronze bells were chiming remarkably loud.", "pattern": "AN-cient BRONZE BELLS were CHIM-ing re-MARK-a-bly LOUD.", "note": "Feel the alternating peaks and valleys."}, {"text": "Leaves turn red in fall.", "pattern": "LEAVES TURN RED in FALL.", "note": "Four evenly spaced autumn beats."}, {"text": "Maple leaves quickly turn bright red during late autumn.", "pattern": "MA-ple LEAVES QUICK-ly TURN BRIGHT RED dur-ing LATE AU-tumn.", "note": "Keep the cadence steady despite the added words."}, {"text": "Tigers hunt wild prey.", "pattern": "TI-gers HUNT WILD PREY.", "note": "Four strong beats."}, {"text": "Fierce royal tigers will hunt their wild prey in the jungle.", "pattern": "FIERCE ROY-al TI-gers will HUNT their WILD PREY in the JUN-gle.", "note": "Smooth foot transitions across syllables."}, {"text": "Sun heats earth.", "pattern": "SUN HEATS EARTH.", "note": "Three core beats."}, {"text": "The blazing desert sun heats the dry rocky earth.", "pattern": "the BLAZ-ing DE-sert SUN HEATS the DRY ROCK-y EARTH.", "note": "Multiple stresses grouped together naturally."}, {"text": "Waves crash on rocks.", "pattern": "WAVES CRASH on ROCKS.", "note": "Three dynamic crests."}, {"text": "Huge ocean waves were crashing violently upon the dark rocks.", "pattern": "HUGE O-cean WAVES were CRASH-ing VI-o-lent-ly up-on the DARK ROCKS.", "note": "Rapid compression of unstressed functional syllables."}, {"text": "Snow covered fields.", "pattern": "SNOW COV-ered FIELDS.", "note": "Three clear beats."}, {"text": "Fresh white snow had completely covered the distant mountain fields.", "pattern": "FRESH WHITE SNOW had com-PLETE-ly COV-ered the DIS-tant MOUN-tain FIELDS.", "note": "Stress timing: length of phrase matches beat count, not syllable count."}, {"text": "Wolves howl at moon.", "pattern": "WOLVES HOWL at MOON.", "note": "Three primal pulses."}, {"text": "Hungry grey wolves were howling mournfully beneath the full moon.", "pattern": "HUN-gry GREY WOLVES were HOWL-ing MOURN-ful-ly be-NEATH the FULL MOON.", "note": "Rhythmic balance between content peaks."}, {"text": "Fish swim deep in sea.", "pattern": "FISH SWIM DEEP in SEA.", "note": "Four steady beats."}, {"text": "Strange tropical fish will swim incredibly deep in the silent sea.", "pattern": "STRANGE TROP-i-cal FISH will SWIM in-CRED-i-bly DEEP in the SI-lent SEA.", "note": "Notice how syllables expand and compress naturally."}, {"text": "Bees make sweet honey.", "pattern": "BEES MAKE SWEET HON-ey.", "note": "Four warm beats."}, {"text": "Tiny worker bees diligently make delicious sweet golden honey.", "pattern": "TI-ny WORK-er BEES DIL-i-gent-ly MAKE de-LI-cious SWEET GOLD-en HON-ey.", "note": "Keep your vocal energy centered on the stressed syllables."}, {"text": "Planes fly high in clouds.", "pattern": "PLANES FLY HIGH in CLOUDS.", "note": "Four soaring beats."}, {"text": "Modern passenger planes can fly remarkably high above the white clouds.", "pattern": "MOD-ern PAS-sen-ger PLANES can FLY re-MARK-a-bly HIGH a-bove the WHITE CLOUDS.", "note": "Even cadence across varied phrase lengths."}, {"text": "Books teach great truths.", "pattern": "BOOKS TEACH GREAT TRUTHS.", "note": "Four heavy monosyllabic beats."}, {"text": "Classical history books have always taught profound great truths.", "pattern": "CLAS-si-cal HIS-to-ry BOOKS have AL-ways TAUGHT pro-FOUND GREAT TRUTHS.", "note": "Feel the steady pendulum swing of English rhythm."}, {"text": "Hands hold warm cups.", "pattern": "HANDS HOLD WARM CUPS.", "note": "Four comforting beats."}, {"text": "Cold weary hands were holding warm fragrant cups of herbal tea.", "pattern": "COLD WEA-ry HANDS were HOLD-ing WARM FRA-grant CUPS of HER-bal TEA.", "note": "Flawless stress-timed flow from start to finish."}, {"text": "Drums beat loud.", "pattern": "DRUMS BEAT LOUD.", "note": "Three pounding stress beats."}, {"text": "Huge ceremonial drums were beating remarkably loud.", "pattern": "HUGE cer-e-MO-ni-al DRUMS were BEAT-ing re-MARK-a-bly LOUD.", "note": "Polysyllabic words compressed into the steady beat."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published'),
('sentence-stress', 'Content words vs function words', 'beginner', 'easy', 'us', 'English is stress-timed: you stress the words that carry meaning and squeeze the rest.', ARRAY['Strong: nouns, main verbs, adjectives, adverbs, question words.', 'Weak: articles, prepositions, auxiliaries, pronouns.']::text[], '[{"text": "I want to go to the store.", "pattern": "I WANT to GO to the STORE."}, {"text": "She is looking for a new job.", "pattern": "she''s LOOKing for a NEW JOB."}, {"text": "Can you give me a hand?", "pattern": "can you GIVE me a HAND?"}, {"text": "We have been waiting for an hour.", "pattern": "we''ve been WAITing for an HOUR."}]'::jsonb, '', true, 1, 'published'),
('sentence-stress', 'Emphasis changes the meaning', 'intermediate', 'medium', 'us', 'Move the strongest word and the message changes completely. Say each line and hear the new meaning.', ARRAY['Stress the word you want to correct or highlight.', 'Everything around it gets weaker.']::text[], '[{"text": "I never said she stole it.", "pattern": "I NEVER said she stole it.", "note": "I deny saying it."}, {"text": "I never said she stole it.", "pattern": "I never SAID she stole it.", "note": "Maybe I hinted it."}, {"text": "I never said she stole it.", "pattern": "I never said SHE stole it.", "note": "Someone else did."}, {"text": "I never said she stole it.", "pattern": "I never said she stole IT.", "note": "She stole something else."}]'::jsonb, '', true, 2, 'published'),
('sentence-stress', 'Question words carry the stress', 'beginner', 'easy', 'us', 'In WH- questions, the question word itself is usually strong.', '{}'::text[], '[{"text": "What time is it?", "pattern": "WHAT time is it?"}, {"text": "Where do you live?", "pattern": "WHERE do you LIVE?"}, {"text": "Why did you do that?", "pattern": "WHY did you DO that?"}, {"text": "Who told you that?", "pattern": "WHO told you THAT?"}]'::jsonb, '', true, 3, 'published'),
('sentence-stress', 'Contrastive stress', 'intermediate', 'medium', 'us', 'When comparing two things, stress the word that shows the difference.', '{}'::text[], '[{"text": "I ordered coffee, not tea.", "pattern": "I ordered COFfee, not TEA."}, {"text": "She''s my sister, not my friend.", "pattern": "she''s my SIStr, not my FRIEND."}, {"text": "We''re leaving today, not tomorrow.", "pattern": "we''re leaving toDAY, not toMORrow."}, {"text": "He''s the manager, not the owner.", "pattern": "he''s the MANager, not the OWner."}]'::jsonb, '', true, 4, 'published'),
('sentence-stress', 'New information gets the stress', 'advanced', 'hard', 'us', 'In a conversation, the newest piece of information is usually the strongest word — already-known information gets weaker.', '{}'::text[], '[{"text": "A: Where''s John? B: John is in the KITCHen.", "pattern": "''John'' is already known, so ''kitchen'' is stressed."}, {"text": "A: What did you buy? B: I bought a NEW LAPtop.", "pattern": "''bought'' is known from the question, so the object is stressed."}, {"text": "A: Who called? B: My BROTHer called.", "pattern": "new info = brother."}]'::jsonb, '', true, 5, 'published'),
('sentence-stress', 'Stress in negative sentences', 'intermediate', 'medium', 'us', 'The negative word (not / never / n''t) is often stressed to make the denial clear.', '{}'::text[], '[{"text": "I don''t like it.", "pattern": "I DON''T like it."}, {"text": "She isn''t coming tonight.", "pattern": "she ISn''t coming tonight."}, {"text": "We can''t afford it.", "pattern": "we CAN''T afford it."}, {"text": "That''s not what I meant.", "pattern": "that''s NOT what I meant."}]'::jsonb, '', false, 6, 'published'),
('sentence-stress', 'Stress in polite requests', 'beginner', 'easy', 'us', 'Even polite, softly-spoken requests keep clear stress on the content words.', '{}'::text[], '[{"text": "Could you help me, please?", "pattern": "could you HELP me, please?"}, {"text": "Would you mind closing the window?", "pattern": "would you mind CLOsing the WINdow?"}, {"text": "Do you have a minute?", "pattern": "do you have a MINute?"}]'::jsonb, '', false, 7, 'published'),
('sentence-stress', 'Stress on modal verbs for meaning', 'advanced', 'hard', 'us', 'Modals like can, should and must are usually weak — but stressing them changes the meaning to add certainty or surprise.', '{}'::text[], '[{"text": "You should call her.", "pattern": "you should CALL her.", "note": "Neutral advice."}, {"text": "You SHOULD call her.", "pattern": "you SHOULD call her.", "note": "Strong recommendation, maybe a warning."}, {"text": "He CAN speak French!", "pattern": "he CAN speak French!", "note": "Surprise — I didn''t expect that."}]'::jsonb, '', false, 8, 'published'),
('sentence-stress', 'Everyday small talk sentences', 'beginner', 'easy', 'us', 'Practise stress on common small-talk lines you''ll say every day.', '{}'::text[], '[{"text": "How''s it going?", "pattern": "HOW''s it GOing?"}, {"text": "Long time no see!", "pattern": "LONG time no SEE!"}, {"text": "Nice to meet you.", "pattern": "NICE to MEET you."}, {"text": "Have a good weekend.", "pattern": "have a GOOD WEEKend."}]'::jsonb, '', false, 9, 'published'),
('sentence-stress', 'Stress in comparisons', 'intermediate', 'medium', 'us', 'In comparative sentences, both the adjective and the comparison word usually get stress.', '{}'::text[], '[{"text": "This one is bigger than that one.", "pattern": "this one is BIGger than THAT one."}, {"text": "She''s much taller than her brother.", "pattern": "she''s MUCH TALLer than her BROther."}, {"text": "It''s the best restaurant in town.", "pattern": "it''s the BEST resTAUrant in TOWN."}]'::jsonb, '', false, 10, 'published'),
('sentence-stress', 'Stress in giving opinions', 'intermediate', 'medium', 'us', 'Opinion phrases carry stress on the key opinion word, not on ''I think'' itself.', '{}'::text[], '[{"text": "I think it''s a great idea.", "pattern": "I think it''s a GREAT idea."}, {"text": "In my opinion, it''s too expensive.", "pattern": "in my oPINion, it''s too exPENsive."}, {"text": "Personally, I''d rather stay home.", "pattern": "PERsonally, I''d RAther stay HOME."}]'::jsonb, '', false, 11, 'published'),
('sentence-stress', 'Stress in phone conversations', 'beginner', 'easy', 'us', 'Phone-call English has its own set of common stressed phrases.', '{}'::text[], '[{"text": "Can I speak to Sarah, please?", "pattern": "can I SPEAK to SARah, please?"}, {"text": "She''s not available right now.", "pattern": "she''s not aVAILable right NOW."}, {"text": "Can I take a message?", "pattern": "can I TAKE a MESsage?"}]'::jsonb, '', false, 12, 'published'),
('sentence-stress', 'Stress when giving directions', 'intermediate', 'medium', 'us', 'Direction-giving relies on clear stress so the listener catches the key landmarks and turns.', '{}'::text[], '[{"text": "Turn left at the traffic light.", "pattern": "TURN LEFT at the TRAFfic light."}, {"text": "It''s right next to the bank.", "pattern": "it''s RIGHT NEXT to the BANK."}, {"text": "Go straight for two blocks.", "pattern": "go STRAIGHT for TWO BLOCKS."}]'::jsonb, '', false, 13, 'published'),
('sentence-stress', 'Stress in requests for clarification', 'beginner', 'easy', 'us', 'When you didn''t understand, stress the question word or the part you missed.', '{}'::text[], '[{"text": "Sorry, what did you say?", "pattern": "SORry, WHAT did you SAY?"}, {"text": "Could you repeat that, please?", "pattern": "could you rePEAT that, please?"}, {"text": "What do you mean by that?", "pattern": "WHAT do you MEAN by that?"}]'::jsonb, '', false, 14, 'published'),
('sentence-stress', 'Stress with ''too'' and ''either''', 'advanced', 'hard', 'us', '''Too'' and ''either'' at the end of a sentence usually take their own beat of stress.', '{}'::text[], '[{"text": "I love this song too.", "pattern": "I LOVE this SONG TOO."}, {"text": "I don''t like it either.", "pattern": "I DON''T like it EIther."}, {"text": "She''s coming too.", "pattern": "she''s COming TOO."}]'::jsonb, '', false, 15, 'published'),
('sentence-stress', 'Stress in job-interview answers', 'advanced', 'hard', 'us', 'Interview English needs confident, clear stress on your strongest selling points.', '{}'::text[], '[{"text": "I''m a fast learner and a team player.", "pattern": "I''m a FAST LEARner and a TEAM PLAYer."}, {"text": "My biggest strength is problem-solving.", "pattern": "my BIGgest STRENGTH is PROBlem-SOLving."}, {"text": "I''m excited about this opportunity.", "pattern": "I''m exCIted aBOUT this opporTUNity."}]'::jsonb, '', false, 16, 'published'),
('sentence-stress', 'Stress when correcting a mistake', 'intermediate', 'medium', 'us', 'When correcting yourself or someone else, the corrected word gets extra stress.', '{}'::text[], '[{"text": "No, I said Tuesday, not Thursday.", "pattern": "no, I said TUESday, not THURSday."}, {"text": "It''s spelled with an ''e'', not an ''a''.", "pattern": "it''s spelled with an ''E'', not an ''A''."}, {"text": "Actually, it''s twenty dollars, not twelve.", "pattern": "actually, it''s TWENty dollars, not TWELVE."}]'::jsonb, '', false, 17, 'published'),
('sentence-stress', 'Stress in shopping conversations', 'beginner', 'easy', 'us', 'Shopping English — practise clear stress so you''re understood at the till or in a fitting room.', '{}'::text[], '[{"text": "Do you have this in a smaller size?", "pattern": "do you have this in a SMALLer SIZE?"}, {"text": "How much does it cost?", "pattern": "HOW MUCH does it COST?"}, {"text": "Can I try it on?", "pattern": "can I TRY it ON?"}]'::jsonb, '', false, 18, 'published'),
('sentence-stress', 'Stress with reflexive emphasis (myself, himself)', 'advanced', 'hard', 'us', 'Reflexive pronouns used for emphasis (''I did it myself'') always get a strong stress.', '{}'::text[], '[{"text": "I did it myself.", "pattern": "I did it my-SELF."}, {"text": "She fixed the car herself.", "pattern": "she fixed the car her-SELF."}, {"text": "They built the house themselves.", "pattern": "they built the house them-SELVES."}]'::jsonb, '', false, 19, 'published'),
('sentence-stress', 'Stress in giving instructions', 'intermediate', 'medium', 'us', 'Clear, imperative instructions rely on stress to sound confident and easy to follow.', '{}'::text[], '[{"text": "Press the button and wait.", "pattern": "PRESS the BUTton and WAIT."}, {"text": "Don''t forget to save your work.", "pattern": "DON''T forGET to SAVE your WORK."}, {"text": "Make sure it''s plugged in.", "pattern": "make SURE it''s PLUGGED in."}]'::jsonb, '', false, 20, 'published'),
('sentence-stress', 'Stress in apologies', 'beginner', 'easy', 'us', 'Apology phrases still need the right stress to sound sincere, not flat.', '{}'::text[], '[{"text": "I''m really sorry about that.", "pattern": "I''m REAlly SORry about THAT."}, {"text": "It won''t happen again.", "pattern": "it WON''T HAPpen aGAIN."}, {"text": "I should have told you sooner.", "pattern": "I SHOULD have TOLD you SOOner."}]'::jsonb, '', false, 21, 'published'),
('sentence-stress', 'Stress on numbers in context', 'intermediate', 'medium', 'us', 'When giving prices, dates or quantities, the number itself is almost always the strongest word.', '{}'::text[], '[{"text": "It costs fifty dollars.", "pattern": "it costs FIFty DOllars."}, {"text": "The meeting is at three o''clock.", "pattern": "the MEEting is at THREE o''clock."}, {"text": "We need six more copies.", "pattern": "we need SIX more COpies."}]'::jsonb, '', false, 22, 'published'),
('sentence-stress', 'Stress in storytelling', 'advanced', 'hard', 'us', 'Good storytelling exaggerates the stress on the most dramatic or surprising words.', '{}'::text[], '[{"text": "And then, suddenly, the lights went out!", "pattern": "and then, SUDdenly, the LIGHTS went OUT!"}, {"text": "I couldn''t believe what I was seeing.", "pattern": "I COULDn''t beLIEVE what I was SEEing."}, {"text": "It was the best day of my life.", "pattern": "it was the BEST day of my LIFE."}]'::jsonb, '', false, 23, 'published'),
('sentence-stress', 'Stress with ''even'' for emphasis', 'advanced', 'hard', 'us', '''Even'' adds surprise, and the word right after it usually carries the strongest stress.', '{}'::text[], '[{"text": "Even my dad likes this song.", "pattern": "even my DAD likes this song."}, {"text": "I didn''t even notice.", "pattern": "I didn''t even NOtice."}, {"text": "She finished even faster than me.", "pattern": "she finished even FASTer than me."}]'::jsonb, '', false, 24, 'published'),
('sentence-stress', 'Stress in conditional sentences', 'intermediate', 'medium', 'us', 'In ''if'' sentences, stress the condition and the result — the connecting words stay weak.', '{}'::text[], '[{"text": "If it rains, we''ll stay home.", "pattern": "if it RAINS, we''ll STAY HOME."}, {"text": "If I were you, I''d apologize.", "pattern": "if I were YOU, I''d aPOLogize."}, {"text": "I would have come if you''d asked.", "pattern": "I WOULD have COME if you''d ASKED."}]'::jsonb, '', false, 25, 'published'),
('sentence-stress', 'Stress in reported speech', 'advanced', 'hard', 'us', 'Reporting verbs (said, told, asked) are usually weak — the actual message carries the stress.', '{}'::text[], '[{"text": "She said she''d be late.", "pattern": "she said she''d be LATE."}, {"text": "He told me not to worry.", "pattern": "he told me not to WORry."}, {"text": "They asked if we were coming.", "pattern": "they asked if we were COMing."}]'::jsonb, '', false, 26, 'published'),
('sentence-stress', 'Stress when making suggestions', 'beginner', 'easy', 'us', 'Suggestion phrases stress the activity being suggested, not the suggestion frame itself.', '{}'::text[], '[{"text": "Why don''t we get some coffee?", "pattern": "why don''t we get some COFfee?"}, {"text": "How about going for a walk?", "pattern": "how about going for a WALK?"}, {"text": "Let''s try that new restaurant.", "pattern": "let''s try that NEW resTAUrant."}]'::jsonb, '', false, 27, 'published'),
('sentence-stress', 'Stress in talking about future plans', 'beginner', 'easy', 'us', 'Plans and intentions stress the activity and the time reference.', '{}'::text[], '[{"text": "I''m meeting a friend tomorrow.", "pattern": "I''m MEETing a FRIEND toMORrow."}, {"text": "We''re planning to move next year.", "pattern": "we''re PLANning to MOVE next YEAR."}, {"text": "I might travel this summer.", "pattern": "I might TRAVel this SUMmer."}]'::jsonb, '', false, 28, 'published'),
('sentence-stress', 'Stress in talking about past experiences', 'intermediate', 'medium', 'us', 'Past experience talk stresses the event and any time markers, common in IELTS Speaking Part 2.', '{}'::text[], '[{"text": "I visited Japan two years ago.", "pattern": "I VISited JaPAN two YEARS ago."}, {"text": "I''ve never tried sushi before.", "pattern": "I''ve NEver TRIED SUshi beFORE."}, {"text": "That was the best trip I''ve ever had.", "pattern": "that was the BEST TRIP I''ve Ever had."}]'::jsonb, '', false, 29, 'published'),
('sentence-stress', 'Stress when expressing likes and dislikes', 'beginner', 'easy', 'us', 'The verb of feeling and the thing you like or dislike both usually get stress.', '{}'::text[], '[{"text": "I really love this song.", "pattern": "I REALly LOVE this SONG."}, {"text": "I can''t stand waiting in line.", "pattern": "I CAN''T STAND WAITing in LINE."}, {"text": "I''m not really a fan of spicy food.", "pattern": "I''m not REALly a FAN of SPIcy FOOD."}]'::jsonb, '', false, 30, 'published'),
('sentence-stress', 'Stress describing a process step by step', 'intermediate', 'medium', 'us', 'Sequence words (first, then, after that, finally) get their own beat when explaining a process.', '{}'::text[], '[{"text": "First, you boil the water.", "pattern": "FIRST, you BOIL the WAter."}, {"text": "Then you add the pasta.", "pattern": "THEN you ADD the PASta."}, {"text": "Finally, drain it and serve.", "pattern": "FInally, DRAIN it and SERVE."}]'::jsonb, '', false, 31, 'published'),
('sentence-stress', 'Stress comparing pros and cons', 'advanced', 'hard', 'us', 'Balanced pro/con sentences stress the contrasting sides clearly, common in IELTS Part 3 discussion answers.', '{}'::text[], '[{"text": "On the one hand it''s cheaper, but on the other hand it takes longer.", "pattern": "CHEAPer ... LONGer"}, {"text": "The main advantage is speed, while the main drawback is cost.", "pattern": "SPEED ... COST"}]'::jsonb, '', false, 32, 'published'),
('sentence-stress', 'Stress agreeing and disagreeing', 'beginner', 'easy', 'us', 'Agreement and disagreement phrases stress the key word that shows your position.', '{}'::text[], '[{"text": "I completely agree with you.", "pattern": "I comPLETEly aGREE with you."}, {"text": "I see your point, but I disagree.", "pattern": "I SEE your POINT, but I disaGREE."}, {"text": "That''s exactly what I think too.", "pattern": "that''s exACTly what I THINK too."}]'::jsonb, '', false, 33, 'published'),
('sentence-stress', 'Stress in restaurant ordering', 'beginner', 'easy', 'us', 'Ordering food stresses the dish name and any specific requests.', '{}'::text[], '[{"text": "I''ll have the grilled chicken, please.", "pattern": "I''ll have the GRILLED CHICKen, please."}, {"text": "Could I get that without onions?", "pattern": "could I get that withOUT ONions?"}, {"text": "Can we get the check, please?", "pattern": "can we get the CHECK, please?"}]'::jsonb, '', false, 34, 'published'),
('sentence-stress', 'Stress apologizing for being late', 'beginner', 'easy', 'us', 'A sincere apology stresses the reason and the apology word itself.', '{}'::text[], '[{"text": "Sorry I''m late, the traffic was terrible.", "pattern": "SORry I''m LATE, the TRAFfic was TERrible."}, {"text": "I''m so sorry for the delay.", "pattern": "I''m SO SORry for the deLAY."}]'::jsonb, '', false, 35, 'published'),
('sentence-stress', 'Stress describing someone''s appearance', 'intermediate', 'medium', 'us', 'Descriptions of people stress the distinguishing feature you''re highlighting.', '{}'::text[], '[{"text": "She''s the one with the curly hair.", "pattern": "she''s the ONE with the CURly HAIR."}, {"text": "He''s tall and always wears glasses.", "pattern": "he''s TALL and ALways wears GLASSes."}]'::jsonb, '', false, 36, 'published'),
('sentence-stress', 'Stress in emergency and urgent phrases', 'intermediate', 'medium', 'us', 'Urgent phrases exaggerate stress on the key danger word so the listener reacts fast.', '{}'::text[], '[{"text": "Call an ambulance now!", "pattern": "CALL an AMbulance NOW!"}, {"text": "Watch out, the floor is wet!", "pattern": "WATCH OUT, the FLOOR is WET!"}, {"text": "We need help immediately.", "pattern": "we NEED HELP imMEdiately."}]'::jsonb, '', false, 37, 'published'),
('sentence-stress', 'Stress talking about deadlines and time pressure', 'intermediate', 'medium', 'us', 'Workplace time-pressure phrases stress the deadline and the consequence.', '{}'::text[], '[{"text": "The report is due by Friday.", "pattern": "the rePORT is DUE by FRIday."}, {"text": "We''re really pressed for time.", "pattern": "we''re REALly PRESSED for TIME."}, {"text": "Can we push the meeting back an hour?", "pattern": "can we PUSH the MEETing BACK an HOUR?"}]'::jsonb, '', false, 38, 'published'),
('sentence-stress', 'Stress in casual invitations', 'beginner', 'easy', 'us', 'Casual invites stress the activity and the time, keeping the invitation frame itself weak.', '{}'::text[], '[{"text": "Do you want to grab lunch later?", "pattern": "do you want to GRAB LUNCH LAter?"}, {"text": "We''re having a party this weekend.", "pattern": "we''re HAVing a PARty this WEEKend."}, {"text": "You should totally come with us.", "pattern": "you should TOtally COME with us."}]'::jsonb, '', false, 39, 'published'),
('sentence-stress', 'Stress talking about abilities and skills', 'intermediate', 'medium', 'us', 'Talking about what you can and can''t do stresses the skill itself, not the modal verb.', '{}'::text[], '[{"text": "I can speak three languages.", "pattern": "I can SPEAK THREE LANGuages."}, {"text": "I''m not very good at cooking.", "pattern": "I''m not VEry GOOD at COOKing."}, {"text": "She''s really talented at drawing.", "pattern": "she''s REALly TALented at DRAWing."}]'::jsonb, '', false, 40, 'published'),
('sentence-stress', 'Stress expressing surprise', 'beginner', 'easy', 'us', 'Surprised reactions stress the unexpected part of the news heavily, often with extra pitch too.', '{}'::text[], '[{"text": "I can''t believe you did that!", "pattern": "I CAN''T beLIEVE you DID that!"}, {"text": "No way, that''s amazing!", "pattern": "no WAY, that''s aMAZing!"}, {"text": "Seriously? I had no idea.", "pattern": "SEriously? I had NO iDEa."}]'::jsonb, '', false, 41, 'published'),
('sentence-stress', 'Stress making a complaint', 'advanced', 'hard', 'us', 'Complaints stress the problem word clearly, so the listener understands exactly what''s wrong.', '{}'::text[], '[{"text": "This isn''t what I ordered.", "pattern": "this ISN''T what I orDERED."}, {"text": "I''ve been waiting for over an hour.", "pattern": "I''ve been WAITing for Over an HOUR."}, {"text": "This is the second time this has happened.", "pattern": "this is the SECond TIME this has HAPPened."}]'::jsonb, '', false, 42, 'published'),
('sentence-stress', 'Stress describing your daily routine', 'beginner', 'easy', 'us', 'Routine descriptions stress the action verbs and time markers, common in IELTS Part 1.', '{}'::text[], '[{"text": "I usually wake up at seven.", "pattern": "I usually WAKE UP at SEVen."}, {"text": "I always check my email first.", "pattern": "I ALways CHECK my EMail FIRST."}, {"text": "I try to exercise every morning.", "pattern": "I TRY to EXercise EVery MORNing."}]'::jsonb, '', false, 43, 'published'),
('sentence-stress', 'Stress talking about the weather forecast', 'beginner', 'easy', 'us', 'Weather talk stresses the condition and the time it''s expected.', '{}'::text[], '[{"text": "It''s supposed to rain tomorrow.", "pattern": "it''s supposed to RAIN toMORrow."}, {"text": "It''s going to be really hot this week.", "pattern": "it''s gonna be REALly HOT this WEEK."}]'::jsonb, '', false, 44, 'published'),
('sentence-stress', 'Stress discussing a news story', 'advanced', 'hard', 'us', 'Talking about news stresses the key facts — who, what and the outcome.', '{}'::text[], '[{"text": "Did you hear about the new policy?", "pattern": "did you HEAR about the NEW POLicy?"}, {"text": "Apparently the price is going up next month.", "pattern": "apPARently the PRICE is going UP next MONTH."}]'::jsonb, '', false, 45, 'published'),
('sentence-stress', 'Stress giving a warning', 'intermediate', 'medium', 'us', 'Warnings stress the danger and the action needed, spoken with extra force.', '{}'::text[], '[{"text": "Be careful, the road is icy.", "pattern": "be CAREful, the ROAD is ICy."}, {"text": "Watch your step, it''s slippery here.", "pattern": "WATCH your STEP, it''s SLIPPery HERE."}]'::jsonb, '', false, 46, 'published'),
('sentence-stress', 'Stress offering choices at a shop or counter', 'beginner', 'easy', 'us', 'Offering options stresses each choice being offered.', '{}'::text[], '[{"text": "Would you like paper or plastic?", "pattern": "would you like PAper or PLAStic?"}, {"text": "Do you want that for here or to go?", "pattern": "do you want that for HERE or to GO?"}]'::jsonb, '', false, 47, 'published'),
('sentence-stress', 'Stress with wishes and hypotheticals', 'advanced', 'hard', 'us', 'Wishes and hypothetical statements stress the imagined situation strongly.', '{}'::text[], '[{"text": "I wish I had more free time.", "pattern": "I WISH I had MORE FREE time."}, {"text": "If only I''d studied harder.", "pattern": "if ONly I''d STUDied HARDer."}]'::jsonb, '', false, 48, 'published'),
('sentence-stress', 'Stress talking about birthdays and celebrations', 'beginner', 'easy', 'us', 'Celebration talk stresses the event and the special detail about it.', '{}'::text[], '[{"text": "We''re throwing a surprise party for her.", "pattern": "we''re THROWing a surPRISE PARty for her."}, {"text": "It''s my brother''s birthday next week.", "pattern": "it''s my BROTHer''s BIRTHday next WEEK."}]'::jsonb, '', false, 49, 'published'),
('sentence-stress', 'Final mixed review', 'advanced', 'hard', 'us', 'A closing mixed set pulling together content words, emphasis and negatives — mark the stress before checking.', '{}'::text[], '[{"text": "I really need this done by Friday.", "pattern": "I REALly NEED this DONE by FRIday."}, {"text": "I didn''t say it was easy.", "pattern": "I DIDn''t SAY it was EAsy."}, {"text": "She''s the one who called, not him.", "pattern": "she''s the ONE who CALLED, not HIM."}]'::jsonb, '', false, 50, 'published'),
('sentence-stress', 'Practice', 'intermediate', 'medium', 'us', 'Master sentence stress across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "I lost my phone yesterday.", "pattern": "I LOST my PHONE YES-ter-day.", "note": "Main emphasis on ''lost'', ''phone'', and ''yesterday''."}, {"text": "She bought a beautiful new car.", "pattern": "she BOUGHT a BEAU-ti-ful NEW CAR.", "note": "''bought'', ''beautiful'', ''new'', ''car'' carry the sentence beats."}, {"text": "Can you pick me up at the airport?", "pattern": "can you PICK me UP at the AIR-port?", "note": "Stress on phrasal verb ''pick up'' and ''airport''."}, {"text": "We need to discuss the project schedule.", "pattern": "we NEED to dis-CUSS the PRO-ject SCHED-ule.", "note": "Grammar words ''we'', ''to'', ''the'' are quick and soft."}, {"text": "He didn''t know the answer to the question.", "pattern": "he DID-n''t KNOW the AN-swer to the QUES-tion.", "note": "''didn''t'' and ''know'' take focus."}, {"text": "I was waiting for you in the lobby.", "pattern": "I was WAIT-ing for you in the LOB-by.", "note": "''waiting'' and ''lobby'' carry the content."}, {"text": "Could you send me the report by five?", "pattern": "could you SEND me the re-PORT by FIVE?", "note": "Stress on ''send'', ''report'', and ''five''."}, {"text": "They decided to cancel the outdoor concert.", "pattern": "they de-CI-ded to CAN-cel the OUT-door CON-cert.", "note": "Four content beats drive the rhythm."}, {"text": "My sister lives in a small apartment downtown.", "pattern": "my SIS-ter LIVES in a SMALL a-PART-ment DOWN-town.", "note": "Notice the quick unstressed words between beats."}, {"text": "I really appreciate all your valuable support.", "pattern": "I REAL-ly ap-PRE-ci-ate ALL your VAL-u-a-ble sup-PORT.", "note": "''really'', ''appreciate'', ''all'', ''valuable'', ''support''."}, {"text": "Are you going to the party tonight?", "pattern": "are you GO-ing to the PAR-ty to-NIGHT?", "note": "''going'', ''party'', ''tonight'' take the pitch peaks."}, {"text": "The train leaves in ten minutes.", "pattern": "the TRAIN LEAVES in TEN MIN-utes.", "note": "''train'', ''leaves'', ''ten'', ''minutes'' are stressed."}, {"text": "I don''t think that''s a good idea.", "pattern": "I DON''T THINK that''s a GOOD i-DEA.", "note": "Negatives like ''don''t'' always receive stress."}, {"text": "What time does your plane arrive?", "pattern": "what TIME does your PLANE ar-RIVE?", "note": "Question word ''time'', ''plane'', ''arrive''."}, {"text": "Please turn off your mobile devices.", "pattern": "please TURN OFF your MO-bile de-VI-ces.", "note": "''turn off'', ''mobile'', ''devices''."}, {"text": "She graduated at the top of her class.", "pattern": "she GRAD-u-at-ed at the TOP of her CLASS.", "note": "''graduated'', ''top'', ''class'' take prominence."}, {"text": "We should grab a cup of coffee.", "pattern": "we should GRAB a CUP of COF-fee.", "note": "''should'', ''a'', ''of'' are reduced; ''grab'', ''cup'', ''coffee'' stressed."}, {"text": "I left my wallet on the kitchen table.", "pattern": "I LEFT my WAL-let on the KITCH-en TA-ble.", "note": "Four clear peaks: ''left'', ''wallet'', ''kitchen'', ''table''."}, {"text": "Why didn''t anyone tell me about this?", "pattern": "WHY DID-n''t AN-y-one TELL me a-bout THIS?", "note": "Question word ''why'', ''didn''t'', ''tell'', ''this''."}, {"text": "The doctor advised him to rest for a week.", "pattern": "the DOC-tor ad-VISED him to REST for a WEEK.", "note": "''doctor'', ''advised'', ''rest'', ''week''."}, {"text": "I told him to call me, but he emailed instead.", "pattern": "I TOLD him to CALL me, but he E-mailed in-STEAD.", "note": "Contrastive stress between ''call'' and ''emailed''."}, {"text": "I said fifteen dollars, not fifty dollars.", "pattern": "I said fif-TEEN DOL-lars, not FIF-ty DOL-lars.", "note": "Contrastive stress highlights ''fifTEEN'' vs ''FIFty''."}, {"text": "Do you want green tea or black tea?", "pattern": "do you want GREEN tea or BLACK tea?", "note": "Contrastive stress highlights ''GREEN'' and ''BLACK''."}, {"text": "She wanted a red dress, not a blue one.", "pattern": "she wanted a RED dress, not a BLUE one.", "note": "Contrast between colors ''RED'' and ''BLUE''."}, {"text": "I asked for hot coffee, but this is iced.", "pattern": "I asked for HOT cof-fee, but this is ICED.", "note": "Contrast on temperature ''HOT'' vs ''ICED''."}, {"text": "We booked the morning flight to avoid delays.", "pattern": "we BOOKED the MORN-ing FLIGHT to a-VOID de-LAYS.", "note": "Content words carry the sentence forward."}, {"text": "Can anyone recommend a reliable plumber?", "pattern": "can AN-y-one rec-om-MEND a re-LI-a-ble PLUM-ber?", "note": "Four stressed peaks in the question."}, {"text": "He always forgets to lock the front door.", "pattern": "he AL-ways for-GETS to LOCK the FRONT DOOR.", "note": "Adverbs of frequency like ''always'' often take stress."}, {"text": "I rarely eat fast food on weekdays.", "pattern": "I RARE-ly EAT FAST FOOD on WEEK-days.", "note": "''rarely'', ''eat'', ''fast food'', ''weekdays''."}, {"text": "She never drinks sugary beverages in the evening.", "pattern": "she NEV-er DRINKS SUG-ar-y BEV-er-a-ges in the EVE-ning.", "note": "Rhythmic peaks on descriptive words."}, {"text": "Could you explain that concept one more time?", "pattern": "could you ex-PLAIN that CON-cept ONE MORE TIME?", "note": "''explain'', ''concept'', ''one more time''."}, {"text": "The manager wants everyone in the conference room.", "pattern": "the MAN-a-ger WANTS EV-ery-one in the CON-fer-ence ROOM.", "note": "Emphasis on key nouns and verb."}, {"text": "I can hardly hear what the speaker is saying.", "pattern": "I can HARD-ly HEAR what the SPEAK-er is SAY-ing.", "note": "''hardly'', ''hear'', ''speaker'', ''saying''."}, {"text": "They promised to deliver the package by noon.", "pattern": "they PROM-ised to de-LIV-er the PACK-age by NOON.", "note": "''promised'', ''deliver'', ''package'', ''noon''."}, {"text": "You shouldn''t have opened that attachment.", "pattern": "you SHOULD-n''t have O-pened that at-TACH-ment.", "note": "Negative modal ''shouldn''t'' is heavily emphasized."}, {"text": "Nobody expected such an incredible outcome.", "pattern": "NO-bod-y ex-PEC-ted such an in-CRED-i-ble OUT-come.", "note": "''nobody'', ''expected'', ''incredible'', ''outcome''."}, {"text": "We must submit the final draft before midnight.", "pattern": "we MUST sub-MIT the FI-nal DRAFT be-fore MID-night.", "note": "''must'' takes emphatic modal stress."}, {"text": "How much did you pay for those tickets?", "pattern": "how MUCH did you PAY for those TICK-ets?", "note": "Question focus on ''much'', ''pay'', ''tickets''."}, {"text": "Where did you put the spare keys?", "pattern": "WHERE did you PUT the SPARE KEYS?", "note": "Focus on location ''where'', action ''put'', and ''spare keys''."}, {"text": "Who told you about the secret surprise?", "pattern": "WHO TOLD you a-bout the SE-cret sur-PRISE?", "note": "Focus on identity ''who'', ''told'', ''secret surprise''."}, {"text": "I thought you were studying for the exam.", "pattern": "I THOUGHT you were STUD-y-ing for the ex-AM.", "note": "''thought'', ''studying'', ''exam''."}, {"text": "She looked everywhere for her missing cat.", "pattern": "she looked EV-ery-where for her MISS-ing CAT.", "note": "''everywhere'', ''missing'', ''cat''."}, {"text": "Our team won the national championship today.", "pattern": "our TEAM WON the NA-tion-al CHAM-pi-on-ship to-DAY.", "note": "''team'', ''won'', ''national'', ''championship'', ''today''."}, {"text": "I honestly believe we can finish on schedule.", "pattern": "I HON-est-ly be-LIEVE we can FIN-ish on SCHED-ule.", "note": "''honestly'', ''believe'', ''finish'', ''schedule''."}, {"text": "The traffic was terrible on the bridge.", "pattern": "the TRAF-fic was TER-ri-ble on the BRIDGE.", "note": "''traffic'', ''terrible'', ''bridge''."}, {"text": "He offered to drive us straight to the station.", "pattern": "he OF-fered to DRIVE us STRAIGHT to the STA-tion.", "note": "''offered'', ''drive'', ''straight'', ''station''."}, {"text": "We ordered pizza because nobody wanted to cook.", "pattern": "we OR-dered PIZ-za be-cause NO-bod-y WANT-ed to COOK.", "note": "Two balanced clauses with 2-3 beats each."}, {"text": "She plays the piano with extraordinary skill.", "pattern": "she PLAYS the pi-AN-o with ex-TRAOR-di-nar-y SKILL.", "note": "''plays'', ''piano'', ''extraordinary'', ''skill''."}, {"text": "Never assume anything without checking the facts.", "pattern": "NEV-er as-SUME AN-y-thing with-out CHECK-ing the FACTS.", "note": "Imperative warning: ''never'', ''assume'', ''checking'', ''facts''."}, {"text": "Make sure you double-check all the figures.", "pattern": "make SURE you DOU-ble-CHECK all the FIG-ures.", "note": "''sure'', ''double-check'', ''figures''."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published'),
('word-stress', 'What is word stress?', 'beginner', 'easy', 'us', 'Every English word of two or more syllables has one strong syllable. The strong one is longer, louder and clearer.', ARRAY['Stressed syllable: longer, louder, clear vowel.', 'Unstressed syllable: short and often a schwa /ə/.', 'Only one primary stress per word.']::text[], '[{"text": "water", "pattern": "WA-ter", "note": "Two syllables, stress on the first."}, {"text": "hotel", "pattern": "ho-TEL", "note": "Stress on the second."}, {"text": "computer", "pattern": "com-PU-ter", "note": "Middle syllable is strongest."}, {"text": "important", "pattern": "im-POR-tant", "note": "The two weak syllables use /ə/."}, {"text": "beautiful", "pattern": "BEAU-ti-ful", "note": "First syllable carries the beat."}]'::jsonb, '', true, 1, 'published'),
('word-stress', 'Stress that changes the word', 'intermediate', 'medium', 'us', 'Some words change meaning or word class when the stress moves. Say both versions and feel the difference.', ARRAY['Nouns often stress the first syllable.', 'Verbs often stress the second syllable.']::text[], '[{"text": "a REcord", "pattern": "REcord (noun)", "note": "I bought a record."}, {"text": "to reCORD", "pattern": "reCORD (verb)", "note": "I want to record my voice."}, {"text": "a PREsent", "pattern": "PREsent (noun)", "note": "Here is your present."}, {"text": "to preSENT", "pattern": "preSENT (verb)", "note": "I will present the plan."}, {"text": "an INcrease", "pattern": "INcrease (noun)", "note": "There is an increase in price."}, {"text": "to inCREASE", "pattern": "inCREASE (verb)", "note": "Prices increase every year."}]'::jsonb, '', true, 2, 'published'),
('word-stress', 'Word families and secondary stress', 'advanced', 'hard', 'us', 'When you add an ending, the stress often moves. Longer words also have a weaker secondary beat.', ARRAY['Primary stress: the strongest beat.', 'Secondary stress: a smaller beat, usually earlier in the word.']::text[], '[{"text": "photograph", "pattern": "PHO-to-graph"}, {"text": "photographer", "pattern": "pho-TO-gra-pher"}, {"text": "photographic", "pattern": "pho-to-GRAPH-ic"}, {"text": "pronunciation", "pattern": "pro-nun-ci-A-tion", "note": "Secondary beat on ''pro''."}, {"text": "international", "pattern": "in-ter-NA-tio-nal", "note": "Secondary beat on ''in''."}]'::jsonb, '', true, 3, 'published'),
('word-stress', 'More noun/verb stress pairs', 'intermediate', 'medium', 'us', 'This noun/verb pattern is very common — dozens of English words work this way.', ARRAY['Noun = stress first syllable.', 'Verb = stress second syllable.']::text[], '[{"text": "a CONtract", "pattern": "CONtract (noun)", "note": "Sign the contract."}, {"text": "to conTRACT", "pattern": "conTRACT (verb)", "note": "Muscles contract when you exercise."}, {"text": "an OBject", "pattern": "OBject (noun)", "note": "What is that object?"}, {"text": "to obJECT", "pattern": "obJECT (verb)", "note": "I object to this plan."}, {"text": "a PROject", "pattern": "PROject (noun)", "note": "This is a big project."}, {"text": "to proJECT", "pattern": "proJECT (verb)", "note": "They project a small loss."}]'::jsonb, '', true, 4, 'published'),
('word-stress', 'Even more noun/verb pairs', 'advanced', 'medium', 'us', 'Keep practising this pattern until switching the stress feels automatic.', ARRAY['Listen for the vowel quality change too, not just loudness.']::text[], '[{"text": "an EXport", "pattern": "EXport (noun)", "note": "Coffee is a major export."}, {"text": "to exPORT", "pattern": "exPORT (verb)", "note": "We export coffee worldwide."}, {"text": "a PERmit", "pattern": "PERmit (noun)", "note": "You need a permit."}, {"text": "to perMIT", "pattern": "perMIT (verb)", "note": "They don''t permit smoking."}, {"text": "a SUSpect", "pattern": "SUSpect (noun)", "note": "The police have a suspect."}, {"text": "to susPECT", "pattern": "susPECT (verb)", "note": "I suspect he is lying."}]'::jsonb, '', true, 5, 'published'),
('word-stress', 'Two-syllable nouns: first-syllable stress', 'beginner', 'easy', 'us', 'Most two-syllable English nouns stress the first syllable.', ARRAY['This is the default pattern for nouns — assume first syllable unless you learn otherwise.']::text[], '[{"text": "table", "pattern": "TA-ble"}, {"text": "window", "pattern": "WIN-dow"}, {"text": "garden", "pattern": "GAR-den"}, {"text": "office", "pattern": "OF-fice"}, {"text": "picture", "pattern": "PIC-ture"}]'::jsonb, '', false, 6, 'published'),
('word-stress', 'Two-syllable verbs: second-syllable stress', 'beginner', 'easy', 'us', 'Most two-syllable English verbs stress the second syllable — the opposite of nouns.', ARRAY['This is the default pattern for verbs.']::text[], '[{"text": "begin", "pattern": "be-GIN"}, {"text": "forget", "pattern": "for-GET"}, {"text": "arrive", "pattern": "ar-RIVE"}, {"text": "decide", "pattern": "de-CIDE"}, {"text": "suggest", "pattern": "sug-GEST"}]'::jsonb, '', false, 7, 'published'),
('word-stress', '-tion and -sion always take the stress before them', 'intermediate', 'medium', 'us', 'Words ending in -tion or -sion always stress the syllable right before the ending.', ARRAY['-tion / -sion → stress moves to the syllable just before it.']::text[], '[{"text": "information", "pattern": "in-for-MA-tion"}, {"text": "decision", "pattern": "de-CI-sion"}, {"text": "celebration", "pattern": "ce-le-BRA-tion"}, {"text": "television", "pattern": "TE-le-vi-sion", "note": "Exception pattern — check a dictionary if unsure."}, {"text": "organization", "pattern": "or-ga-ni-ZA-tion"}]'::jsonb, '', false, 8, 'published'),
('word-stress', '-ic and -ical always take the stress before them', 'intermediate', 'medium', 'us', 'Words ending in -ic or -ical stress the syllable right before the ending, just like -tion.', ARRAY['-ic / -ical → stress the syllable before the ending.']::text[], '[{"text": "economic", "pattern": "e-co-NO-mic"}, {"text": "photographic", "pattern": "pho-to-GRAPH-ic"}, {"text": "historical", "pattern": "his-TO-ri-cal"}, {"text": "scientific", "pattern": "sci-en-TI-fic"}, {"text": "athletic", "pattern": "ath-LE-tic"}]'::jsonb, '', false, 9, 'published'),
('word-stress', '-ity and -ety always take the stress before them', 'advanced', 'hard', 'us', 'Another reliable rule: -ity and -ety pull the stress onto the syllable right before them.', ARRAY['-ity / -ety → stress the syllable before the ending.']::text[], '[{"text": "ability", "pattern": "a-BI-li-ty"}, {"text": "university", "pattern": "u-ni-VER-si-ty"}, {"text": "curiosity", "pattern": "cu-ri-O-si-ty"}, {"text": "variety", "pattern": "va-RI-e-ty"}, {"text": "responsibility", "pattern": "re-spon-si-BI-li-ty"}]'::jsonb, '', false, 10, 'published'),
('word-stress', 'Prefixes usually don''t take the stress', 'intermediate', 'medium', 'us', 'Adding un-, re-, dis- or non- to a word doesn''t move the stress — the prefix stays weak.', ARRAY['un- / re- / dis- / non- are almost never stressed.']::text[], '[{"text": "happy → unhappy", "pattern": "un-HAP-py"}, {"text": "do → redo", "pattern": "re-DO"}, {"text": "agree → disagree", "pattern": "dis-a-GREE"}, {"text": "sense → nonsense", "pattern": "NON-sense", "note": "A common exception — ''nonsense'' stresses the first syllable."}, {"text": "possible → impossible", "pattern": "im-POS-si-ble"}]'::jsonb, '', false, 11, 'published'),
('word-stress', 'Compound nouns: stress the first word', 'intermediate', 'medium', 'us', 'When two words combine into one noun, the first word usually carries the stress.', ARRAY['Compound NOUN → stress word 1.', 'Compare with phrasal adjectives, which stress word 2 (see next lesson).']::text[], '[{"text": "blackbird", "pattern": "BLACK-bird", "note": "One kind of bird."}, {"text": "greenhouse", "pattern": "GREEN-house"}, {"text": "keyboard", "pattern": "KEY-board"}, {"text": "sunrise", "pattern": "SUN-rise"}, {"text": "toothbrush", "pattern": "TOOTH-brush"}]'::jsonb, '', false, 12, 'published'),
('word-stress', 'Adjective + noun phrases: stress the second word', 'advanced', 'hard', 'us', 'Compare this to the last lesson: when it''s really an adjective describing a noun (two separate words, two meanings), the stress moves to the noun.', ARRAY['black BIRD = a bird that is black (any bird).', 'BLACKbird = one specific kind of bird.']::text[], '[{"text": "black bird", "pattern": "black BIRD", "note": "Any bird that happens to be black."}, {"text": "green house", "pattern": "green HOUSE", "note": "A house painted green."}, {"text": "White House", "pattern": "White HOUSE", "note": "Compare: WHITEhouse (compound) doesn''t exist — this stays two words."}, {"text": "hot dog", "pattern": "hot DOG", "note": "A dog that is hot (not the food, HOT dog)."}]'::jsonb, '', false, 13, 'published'),
('word-stress', 'Numbers: -teen vs -ty', 'beginner', 'medium', 'us', 'Thirteen and thirty are often confused. The stress placement is the main difference.', ARRAY['-TEEN numbers: stress the second syllable.', '-ty numbers: stress the first syllable.']::text[], '[{"text": "thirteen", "pattern": "thir-TEEN"}, {"text": "thirty", "pattern": "THIR-ty"}, {"text": "fourteen", "pattern": "four-TEEN"}, {"text": "forty", "pattern": "FOR-ty"}, {"text": "She''s thirteen, not thirty.", "pattern": "thir-TEEN ... THIR-ty", "note": "Exaggerate the contrast so listeners can tell them apart."}]'::jsonb, '', false, 14, 'published'),
('word-stress', 'Job titles and professions', 'beginner', 'easy', 'us', 'Job-title vocabulary you''ll use constantly in small talk and interviews.', ARRAY['Most end in -er/-or/-ist and stress the syllable before that ending.']::text[], '[{"text": "teacher", "pattern": "TEA-cher"}, {"text": "engineer", "pattern": "en-gi-NEER", "note": "Exception — stress falls on the last syllable."}, {"text": "photographer", "pattern": "pho-TO-gra-pher"}, {"text": "journalist", "pattern": "JOUR-na-list"}, {"text": "accountant", "pattern": "ac-COUN-tant"}]'::jsonb, '', false, 15, 'published'),
('word-stress', 'Technology vocabulary', 'intermediate', 'medium', 'us', 'Common tech words — useful for work meetings and everyday conversation about phones and computers.', '{}'::text[], '[{"text": "software", "pattern": "SOFT-ware"}, {"text": "database", "pattern": "DA-ta-base"}, {"text": "algorithm", "pattern": "AL-go-rithm"}, {"text": "application", "pattern": "ap-pli-CA-tion"}, {"text": "download", "pattern": "DOWN-load", "note": "Noun/verb — stress stays on the first syllable in both."}]'::jsonb, '', false, 16, 'published'),
('word-stress', 'Business and office vocabulary', 'intermediate', 'medium', 'us', 'Words you''ll say in every meeting — get the stress right and you''ll sound confident at work.', '{}'::text[], '[{"text": "manager", "pattern": "MA-na-ger"}, {"text": "colleague", "pattern": "COL-league"}, {"text": "deadline", "pattern": "DEAD-line"}, {"text": "budget", "pattern": "BUD-get"}, {"text": "negotiate", "pattern": "ne-GO-ti-ate"}]'::jsonb, '', false, 17, 'published'),
('word-stress', 'Travel and tourism vocabulary', 'beginner', 'easy', 'us', 'Practise these before your next trip — mispronouncing ''hotel'' or ''airport'' is a common stumbling block.', '{}'::text[], '[{"text": "airport", "pattern": "AIR-port"}, {"text": "hotel", "pattern": "ho-TEL"}, {"text": "passport", "pattern": "PASS-port"}, {"text": "luggage", "pattern": "LUG-gage"}, {"text": "itinerary", "pattern": "i-TI-ne-ra-ry"}]'::jsonb, '', false, 18, 'published'),
('word-stress', 'Food and cooking vocabulary', 'beginner', 'easy', 'us', 'Everyday food words — great for restaurant conversations.', '{}'::text[], '[{"text": "restaurant", "pattern": "RES-tau-rant"}, {"text": "vegetable", "pattern": "VE-ge-ta-ble"}, {"text": "delicious", "pattern": "de-LI-cious"}, {"text": "ingredient", "pattern": "in-GRE-di-ent"}, {"text": "recipe", "pattern": "RE-ci-pe"}]'::jsonb, '', false, 19, 'published'),
('word-stress', 'Family and relationship words', 'beginner', 'easy', 'us', 'Talking about family is one of the first things learners need — stress these correctly from the start.', '{}'::text[], '[{"text": "parents", "pattern": "PA-rents"}, {"text": "grandmother", "pattern": "GRAND-mo-ther"}, {"text": "relative", "pattern": "RE-la-tive"}, {"text": "marriage", "pattern": "MAR-riage"}, {"text": "divorce", "pattern": "di-VORCE"}]'::jsonb, '', false, 20, 'published'),
('word-stress', 'Emotion words', 'intermediate', 'medium', 'us', 'Describing feelings accurately needs the right stress, or listeners may mishear the word entirely.', '{}'::text[], '[{"text": "excited", "pattern": "ex-CI-ted"}, {"text": "nervous", "pattern": "NER-vous"}, {"text": "confident", "pattern": "CON-fi-dent"}, {"text": "embarrassed", "pattern": "em-BAR-rassed"}, {"text": "frustrated", "pattern": "FRUS-tra-ted"}]'::jsonb, '', false, 21, 'published'),
('word-stress', 'Countries and nationalities', 'beginner', 'easy', 'us', 'Country and nationality names often have unexpected stress for learners.', '{}'::text[], '[{"text": "Japan", "pattern": "Ja-PAN"}, {"text": "Japanese", "pattern": "Ja-pa-NESE"}, {"text": "Vietnam", "pattern": "Vi-et-NAM"}, {"text": "Vietnamese", "pattern": "Vi-et-na-MESE"}, {"text": "Italy", "pattern": "I-ta-ly"}, {"text": "Italian", "pattern": "I-TAL-ian"}]'::jsonb, '', false, 22, 'published'),
('word-stress', '-ous and -eous adjectives', 'advanced', 'hard', 'us', 'Adjectives ending in -ous almost always stress the syllable right before the ending.', ARRAY['-ous → stress the syllable before it.']::text[], '[{"text": "dangerous", "pattern": "DAN-ge-rous"}, {"text": "curious", "pattern": "CU-ri-ous"}, {"text": "enormous", "pattern": "e-NOR-mous"}, {"text": "ambitious", "pattern": "am-BI-tious"}, {"text": "courageous", "pattern": "cou-RA-geous"}]'::jsonb, '', false, 23, 'published'),
('word-stress', '-ial and -ual adjectives', 'advanced', 'hard', 'us', 'Like -ous, endings -ial and -ual usually pull stress onto the syllable right before them.', '{}'::text[], '[{"text": "official", "pattern": "of-FI-cial"}, {"text": "essential", "pattern": "es-SEN-tial"}, {"text": "individual", "pattern": "in-di-VI-dual"}, {"text": "usual", "pattern": "U-sual"}, {"text": "commercial", "pattern": "com-MER-cial"}]'::jsonb, '', false, 24, 'published'),
('word-stress', '-ate: noun/adjective vs verb', 'advanced', 'hard', 'us', 'Words ending in -ate can be a noun/adjective (shorter vowel, earlier stress) or a verb (long ''ate'' /eɪt/, later stress).', ARRAY['Noun/adjective -ate: shorter, earlier stress.', 'Verb -ate: full /eɪt/ sound, often later stress.']::text[], '[{"text": "a graduate (noun)", "pattern": "GRA-du-ate", "note": "Weak final syllable."}, {"text": "to graduate (verb)", "pattern": "GRA-du-ATE", "note": "Full /eɪt/ at the end."}, {"text": "a certificate (noun)", "pattern": "cer-TI-fi-cate"}, {"text": "to certificate", "pattern": "cer-TI-fi-cate", "note": "Rarely used as a verb — ''certify'' is more common."}, {"text": "an estimate (noun)", "pattern": "ES-ti-mate"}, {"text": "to estimate (verb)", "pattern": "ES-ti-MATE"}]'::jsonb, '', false, 25, 'published'),
('word-stress', 'Acronyms and abbreviations', 'beginner', 'easy', 'us', 'When you spell out an abbreviation letter by letter, the LAST letter usually gets the strongest stress.', ARRAY['Spelling out letters: last letter is strongest.']::text[], '[{"text": "USA", "pattern": "U-S-A ↗↗↘", "note": "Stress falls on ''A''."}, {"text": "CEO", "pattern": "C-E-O ↗↗↘"}, {"text": "ID", "pattern": "I-D ↗↘"}, {"text": "ATM", "pattern": "A-T-M ↗↗↘"}]'::jsonb, '', false, 26, 'published'),
('word-stress', 'Days, months and time words', 'beginner', 'easy', 'us', 'Time vocabulary is used in every conversation, so get the stress automatic early.', '{}'::text[], '[{"text": "Monday", "pattern": "MON-day"}, {"text": "September", "pattern": "Sep-TEM-ber"}, {"text": "yesterday", "pattern": "YES-ter-day"}, {"text": "tomorrow", "pattern": "to-MOR-row"}, {"text": "weekend", "pattern": "WEEK-end"}]'::jsonb, '', false, 27, 'published'),
('word-stress', 'Loanwords from French', 'advanced', 'hard', 'us', 'English borrowed many French words and often keeps the final-syllable stress they had in French.', ARRAY['French loanwords often stress the LAST syllable — the opposite of typical English nouns.']::text[], '[{"text": "ballet", "pattern": "bal-LET"}, {"text": "garage", "pattern": "ga-RAGE", "note": "British English often says GAR-age instead."}, {"text": "cliché", "pattern": "cli-CHÉ"}, {"text": "café", "pattern": "ca-FÉ"}, {"text": "buffet", "pattern": "buf-FET"}]'::jsonb, '', false, 28, 'published'),
('word-stress', 'Compound adjectives with hyphens', 'intermediate', 'medium', 'us', 'Hyphenated adjectives before a noun usually stress the second part more when spoken alone, but level out when placed before the noun they describe.', '{}'::text[], '[{"text": "well-known", "pattern": "well-KNOWN", "note": "A well-known author."}, {"text": "part-time", "pattern": "part-TIME", "note": "A part-time job."}, {"text": "self-employed", "pattern": "self-em-PLOYED"}, {"text": "old-fashioned", "pattern": "old-FASH-ioned"}]'::jsonb, '', false, 29, 'published'),
('word-stress', 'Three-syllable words: pattern practice', 'intermediate', 'medium', 'us', 'Three-syllable words often stress the first syllable, but not always — always double-check unfamiliar words.', '{}'::text[], '[{"text": "yesterday", "pattern": "YES-ter-day"}, {"text": "wonderful", "pattern": "WON-der-ful"}, {"text": "difficult", "pattern": "DIF-fi-cult"}, {"text": "eleven", "pattern": "e-LE-ven", "note": "Exception — stress on the middle syllable."}, {"text": "banana", "pattern": "ba-NA-na", "note": "Exception — stress on the middle syllable."}]'::jsonb, '', false, 30, 'published'),
('word-stress', 'Adjective/noun pairs with the -al ending', 'advanced', 'hard', 'us', 'Words ending in -al often keep the stress in the same place as their root word.', '{}'::text[], '[{"text": "nature → natural", "pattern": "NA-ture → NA-tu-ral"}, {"text": "culture → cultural", "pattern": "CUL-ture → CUL-tu-ral"}, {"text": "person → personal", "pattern": "PER-son → PER-so-nal"}, {"text": "origin → original", "pattern": "O-ri-gin → o-RI-gi-nal", "note": "Stress does shift here — an exception to watch for."}]'::jsonb, '', false, 31, 'published'),
('word-stress', 'Sports and hobbies vocabulary', 'beginner', 'easy', 'us', 'Talking about hobbies is classic small-talk material — get comfortable with this vocabulary.', '{}'::text[], '[{"text": "basketball", "pattern": "BAS-ket-ball"}, {"text": "swimming", "pattern": "SWIM-ming"}, {"text": "photography", "pattern": "pho-TO-gra-phy"}, {"text": "gardening", "pattern": "GAR-de-ning"}, {"text": "volleyball", "pattern": "VOL-ley-ball"}]'::jsonb, '', false, 32, 'published'),
('word-stress', 'Weather vocabulary', 'beginner', 'easy', 'us', 'Weather talk is universal small talk — make sure the stress is automatic.', '{}'::text[], '[{"text": "temperature", "pattern": "TEM-pe-ra-ture"}, {"text": "humidity", "pattern": "hu-MI-di-ty"}, {"text": "thunderstorm", "pattern": "THUN-der-storm"}, {"text": "forecast", "pattern": "FORE-cast"}, {"text": "umbrella", "pattern": "um-BREL-la"}]'::jsonb, '', false, 33, 'published'),
('word-stress', 'Health and medical vocabulary', 'intermediate', 'medium', 'us', 'Useful, sometimes urgent vocabulary — worth practising until it''s automatic.', '{}'::text[], '[{"text": "medicine", "pattern": "ME-di-cine"}, {"text": "hospital", "pattern": "HOS-pi-tal"}, {"text": "appointment", "pattern": "ap-POINT-ment"}, {"text": "symptom", "pattern": "SYMP-tom"}, {"text": "prescription", "pattern": "pre-SCRIP-tion"}]'::jsonb, '', false, 34, 'published'),
('word-stress', 'Education vocabulary', 'beginner', 'easy', 'us', 'School and study vocabulary — common in IELTS Speaking Part 1 too.', '{}'::text[], '[{"text": "university", "pattern": "u-ni-VER-si-ty"}, {"text": "graduate", "pattern": "GRA-du-ate"}, {"text": "curriculum", "pattern": "cur-RI-cu-lum"}, {"text": "scholarship", "pattern": "SCHO-lar-ship"}, {"text": "assignment", "pattern": "as-SIGN-ment"}]'::jsonb, '', false, 35, 'published'),
('word-stress', 'Finance and money vocabulary', 'intermediate', 'medium', 'us', 'Money vocabulary shows up constantly — from shopping to salary negotiations.', '{}'::text[], '[{"text": "economy", "pattern": "e-CO-no-my"}, {"text": "investment", "pattern": "in-VEST-ment"}, {"text": "insurance", "pattern": "in-SUR-ance"}, {"text": "mortgage", "pattern": "MORT-gage"}, {"text": "currency", "pattern": "CUR-ren-cy"}]'::jsonb, '', false, 36, 'published'),
('word-stress', 'Verb + noun stress-shift practice', 'advanced', 'hard', 'us', 'Final round of the noun/verb stress-shift pattern — by now it should start to feel automatic.', '{}'::text[], '[{"text": "a CONflict", "pattern": "CONflict (noun)"}, {"text": "to conFLICT", "pattern": "conFLICT (verb)"}, {"text": "a PROgress", "pattern": "PROgress (noun)"}, {"text": "to proGRESS", "pattern": "proGRESS (verb)"}, {"text": "an ADdress", "pattern": "ADdress (noun)", "note": "British English often stresses the second syllable for both."}, {"text": "to adDRESS", "pattern": "adDRESS (verb)"}]'::jsonb, '', false, 37, 'published'),
('word-stress', 'Adjective endings: -able and -ible', 'intermediate', 'medium', 'us', '-able and -ible usually don''t change the stress of the root word.', '{}'::text[], '[{"text": "comfort → comfortable", "pattern": "COM-fort → COM-for-ta-ble"}, {"text": "reason → reasonable", "pattern": "REA-son → REA-so-na-ble"}, {"text": "afford → affordable", "pattern": "af-FORD → af-FOR-da-ble"}, {"text": "response → responsible", "pattern": "re-SPONSE → re-SPON-si-ble"}]'::jsonb, '', false, 38, 'published'),
('word-stress', 'Longer academic words', 'advanced', 'hard', 'us', 'Academic English uses long, Latin-based words — apply the -tion/-ity/-ic rules you''ve already learned.', '{}'::text[], '[{"text": "methodology", "pattern": "me-tho-DO-lo-gy"}, {"text": "hypothesis", "pattern": "hy-PO-the-sis"}, {"text": "characteristic", "pattern": "cha-rac-te-RIS-tic"}, {"text": "identification", "pattern": "i-den-ti-fi-CA-tion"}]'::jsonb, '', false, 39, 'published'),
('word-stress', 'Everyday greetings and expressions', 'beginner', 'easy', 'us', 'You''ll say these words every single day — stress them naturally from day one.', '{}'::text[], '[{"text": "welcome", "pattern": "WEL-come"}, {"text": "goodbye", "pattern": "good-BYE"}, {"text": "congratulations", "pattern": "con-gra-tu-LA-tions"}, {"text": "apology", "pattern": "a-PO-lo-gy"}, {"text": "attention", "pattern": "at-TEN-tion"}]'::jsonb, '', false, 40, 'published'),
('word-stress', 'City and place-name stress', 'intermediate', 'medium', 'us', 'Place names sometimes break the usual rules — worth practising the common ones by heart.', '{}'::text[], '[{"text": "Chicago", "pattern": "Chi-CA-go"}, {"text": "Toronto", "pattern": "To-RON-to"}, {"text": "Amsterdam", "pattern": "AM-ster-dam"}, {"text": "Bangkok", "pattern": "Bang-KOK", "note": "Often BANG-kok in casual American speech too."}]'::jsonb, '', false, 41, 'published'),
('word-stress', 'Verbs ending in -ize / -ise', 'advanced', 'hard', 'us', 'Verbs ending in -ize (US) or -ise (UK) keep the stress on the syllable before the ending.', '{}'::text[], '[{"text": "organize", "pattern": "OR-ga-nize"}, {"text": "realize", "pattern": "REA-lize"}, {"text": "specialize", "pattern": "SPE-cial-ize"}, {"text": "memorize", "pattern": "ME-mo-rize"}]'::jsonb, '', false, 42, 'published'),
('word-stress', 'Emphatic stress on longer descriptive adjectives', 'intermediate', 'medium', 'us', 'Descriptive adjectives you''ll use to make small talk more vivid.', '{}'::text[], '[{"text": "incredible", "pattern": "in-CRE-di-ble"}, {"text": "unbelievable", "pattern": "un-be-LIE-va-ble"}, {"text": "spectacular", "pattern": "spec-TA-cu-lar"}, {"text": "extraordinary", "pattern": "ex-TRAOR-di-na-ry"}]'::jsonb, '', false, 43, 'published'),
('word-stress', 'Words that look similar but stress differently', 'advanced', 'hard', 'us', 'Spelling doesn''t always predict stress — these near-twins trip up even advanced learners.', '{}'::text[], '[{"text": "desert (dry land)", "pattern": "DE-sert"}, {"text": "dessert (sweet food)", "pattern": "des-SERT"}, {"text": "content (satisfied)", "pattern": "con-TENT"}, {"text": "content (what''s inside)", "pattern": "CON-tent"}]'::jsonb, '', false, 44, 'published'),
('word-stress', 'Practice set: mixed review', 'advanced', 'hard', 'us', 'A final mixed set pulling together nouns, verbs, suffix rules and compounds — say each one before checking the pattern.', '{}'::text[], '[{"text": "photograph, photographer, photographic", "pattern": "PHO-to-graph / pho-TO-gra-pher / pho-to-GRAPH-ic"}, {"text": "a REcord / to reCORD", "pattern": "noun vs verb"}, {"text": "unhappy", "pattern": "un-HAP-py"}, {"text": "responsibility", "pattern": "re-spon-si-BI-li-ty"}, {"text": "well-known author", "pattern": "well-KNOWN AU-thor"}]'::jsonb, '', false, 45, 'published'),
('word-stress', 'Phrasal verb vs compound noun', 'advanced', 'hard', 'us', 'A phrasal verb stresses the particle; the noun made from it stresses the first part instead.', ARRAY['Verb: break DOWN, print OUT.', 'Noun: a BREAKdown, a PRINTout.']::text[], '[{"text": "to break down", "pattern": "break DOWN (verb)"}, {"text": "a breakdown", "pattern": "BREAKdown (noun)"}, {"text": "to check in", "pattern": "check IN (verb)"}, {"text": "a check-in", "pattern": "CHECK-in (noun)"}, {"text": "to set up", "pattern": "set UP (verb)"}, {"text": "a setup", "pattern": "SETup (noun)"}]'::jsonb, '', false, 46, 'published'),
('word-stress', 'Big numbers and money amounts', 'intermediate', 'medium', 'us', 'Hundred, thousand and million are never stressed themselves — the number just before them carries the beat.', '{}'::text[], '[{"text": "two hundred dollars", "pattern": "TWO hundred DOLlars"}, {"text": "fifteen thousand", "pattern": "fifTEEN thousand"}, {"text": "three million people", "pattern": "THREE million PEOple"}, {"text": "nine ninety-nine", "pattern": "NINE NINEty-NINE", "note": "A common price pattern: $9.99."}]'::jsonb, '', false, 47, 'published'),
('word-stress', 'Common idioms and fixed expressions', 'advanced', 'hard', 'us', 'Idioms have their own fixed stress pattern learners should memorise as a whole chunk.', '{}'::text[], '[{"text": "piece of cake", "pattern": "piece of CAKE"}, {"text": "break a leg", "pattern": "break a LEG"}, {"text": "under the weather", "pattern": "under the WEAther"}, {"text": "once in a blue moon", "pattern": "once in a blue MOON"}]'::jsonb, '', false, 48, 'published'),
('word-stress', 'Words that lose a syllable in fast speech', 'advanced', 'hard', 'us', 'Some common words are almost always said with one fewer syllable than they''re spelled with — this changes where the stress lands.', '{}'::text[], '[{"text": "comfortable", "pattern": "COMF-ta-ble", "note": "3 syllables in fast speech, not 4."}, {"text": "vegetable", "pattern": "VEDGE-ta-ble", "note": "3 syllables, not 4."}, {"text": "chocolate", "pattern": "CHOC-late", "note": "2 syllables, not 3."}, {"text": "every", "pattern": "EV-ry", "note": "2 syllables, not 3."}]'::jsonb, '', false, 49, 'published'),
('word-stress', 'Final mixed review', 'advanced', 'hard', 'us', 'One last mixed set — nouns, verbs, compounds and suffix rules together. Say each one before checking the pattern.', '{}'::text[], '[{"text": "an EXport / to exPORT", "pattern": "noun vs verb"}, {"text": "unbelievable", "pattern": "un-be-LIEV-a-ble"}, {"text": "a CONTRACT (noun)", "pattern": "CON-tract"}, {"text": "part-time job", "pattern": "part-TIME JOB"}, {"text": "comfortable chair", "pattern": "COMF-ta-ble CHAIR"}]'::jsonb, '', false, 50, 'published'),
('word-stress', 'Practice', 'intermediate', 'medium', 'us', 'Master word stress across 50 targeted drills. Listen closely to the AI model, repeat, and record your voice to receive detailed real-time pronunciation scoring and feedback.', ARRAY['Focus on the rhythm, stress, and flow highlighted in each drill.', 'Listen to the reference model audio before each recording attempt.', 'Review your AI score and phoneme-level feedback to pinpoint areas for improvement.']::text[], '[{"text": "avocado", "pattern": "a-vo-CA-do", "note": "Third syllable ''CA'' carries the primary stress."}, {"text": "certificate", "pattern": "cer-TIF-i-cate", "note": "Second syllable ''TIF'' is stressed."}, {"text": "caterpillar", "pattern": "CAT-er-pil-lar", "note": "Primary stress on the first syllable ''CAT''."}, {"text": "refrigerator", "pattern": "re-FRIG-er-a-tor", "note": "Second syllable ''FRIG'' is stressed; other syllables compress."}, {"text": "enthusiastic", "pattern": "en-thu-si-AS-tic", "note": "Stress on ''AS'' directly before -tic."}, {"text": "personality", "pattern": "per-son-AL-i-ty", "note": "Stress on ''AL'' right before -ity."}, {"text": "electricity", "pattern": "e-lec-TRIC-i-ty", "note": "Stress on ''TRIC'' before -ity."}, {"text": "administration", "pattern": "ad-min-is-TRA-tion", "note": "Primary stress on ''TRA'' before -tion."}, {"text": "qualification", "pattern": "qual-i-fi-CA-tion", "note": "Primary stress on ''CA'' before -tion."}, {"text": "investigation", "pattern": "in-ves-ti-GA-tion", "note": "Primary stress on ''GA'' before -tion."}, {"text": "magnificent", "pattern": "mag-NIF-i-cent", "note": "Second syllable ''NIF'' takes the beat."}, {"text": "laboratory", "pattern": "LAB-o-ra-to-ry", "note": "First syllable ''LAB'' is stressed in American English."}, {"text": "particular", "pattern": "par-TIC-u-lar", "note": "Second syllable ''TIC'' takes the stress."}, {"text": "coincidence", "pattern": "co-IN-ci-dence", "note": "Second syllable ''IN'' carries the main stress."}, {"text": "fascinating", "pattern": "FAS-ci-nat-ing", "note": "First syllable ''FAS'' carries the stress."}, {"text": "architect", "pattern": "AR-chi-tect", "note": "First syllable ''AR'' is stressed."}, {"text": "architecture", "pattern": "AR-chi-tec-ture", "note": "First syllable ''AR'' carries primary stress."}, {"text": "architectural", "pattern": "ar-chi-TEC-tur-al", "note": "Stress shifts to the third syllable ''TEC''."}, {"text": "geography", "pattern": "ge-OG-ra-phy", "note": "Second syllable ''OG'' takes the stress."}, {"text": "geographic", "pattern": "ge-o-GRAPH-ic", "note": "Stress shifts to ''GRAPH'' before -ic."}, {"text": "philosophy", "pattern": "phi-LOS-o-phy", "note": "Second syllable ''LOS'' is stressed."}, {"text": "philosophical", "pattern": "phil-o-SOPH-i-cal", "note": "Stress shifts to ''SOPH'' before -ical."}, {"text": "psychology", "pattern": "psy-CHOL-o-gy", "note": "Second syllable ''CHOL'' is stressed."}, {"text": "psychological", "pattern": "psy-cho-LOG-i-cal", "note": "Stress shifts to ''LOG'' before -ical."}, {"text": "astronomy", "pattern": "as-TRON-o-my", "note": "Second syllable ''TRON'' takes the stress."}, {"text": "astronomical", "pattern": "as-tro-NOM-i-cal", "note": "Stress shifts to ''NOM'' before -ical."}, {"text": "appreciate", "pattern": "ap-PRE-ci-ate", "note": "Second syllable ''PRE'' carries the stress."}, {"text": "encyclopedia", "pattern": "en-cy-clo-PE-di-a", "note": "Stress on the fourth syllable ''PE''."}, {"text": "anticipate", "pattern": "an-TIC-i-pate", "note": "Second syllable ''TIC'' is stressed."}, {"text": "congratulate", "pattern": "con-GRAT-u-late", "note": "Second syllable ''GRAT'' carries primary stress."}, {"text": "accelerate", "pattern": "ac-CEL-er-ate", "note": "Second syllable ''CEL'' is stressed."}, {"text": "refugee", "pattern": "ref-u-GEE", "note": "Suffix -ee attracts stress to the last syllable."}, {"text": "pioneer", "pattern": "pi-o-NEER", "note": "Suffix -eer takes the final stress."}, {"text": "souvenir", "pattern": "sou-ve-NIR", "note": "Final syllable ''NIR'' receives primary stress."}, {"text": "cigarette", "pattern": "cig-a-RETTE", "note": "Stress on the final syllable ''RETTE''."}, {"text": "kitchenware", "pattern": "KITCH-en-ware", "note": "Compound noun: primary stress on first noun ''KITCH''."}, {"text": "sunflower", "pattern": "SUN-flow-er", "note": "Compound noun: stress the first element ''SUN''."}, {"text": "raincoat", "pattern": "RAIN-coat", "note": "Compound noun: strong first syllable ''RAIN''."}, {"text": "headphones", "pattern": "HEAD-phones", "note": "Compound noun: stress on ''HEAD''."}, {"text": "earthquake", "pattern": "EARTH-quake", "note": "Compound noun: ''EARTH'' is emphasized."}, {"text": "firefighter", "pattern": "FIRE-fight-er", "note": "Compound noun: stress on ''FIRE''."}, {"text": "traffic jam", "pattern": "TRAF-fic jam", "note": "Compound noun: primary stress falls on ''TRAF''."}, {"text": "swimming pool", "pattern": "SWIM-ming pool", "note": "Gerund compound: primary stress on ''SWIM''."}, {"text": "a RE-fund", "pattern": "RE-fund (noun)", "note": "Noun: stress on the first syllable ''RE''."}, {"text": "to re-FUND", "pattern": "re-FUND (verb)", "note": "Verb: stress moves to the second syllable ''FUND''."}, {"text": "a PRO-test", "pattern": "PRO-test (noun)", "note": "Noun: stress on the first syllable ''PRO''."}, {"text": "to pro-TEST", "pattern": "pro-TEST (verb)", "note": "Verb: stress moves to the second syllable ''TEST''."}, {"text": "an UP-date", "pattern": "UP-date (noun)", "note": "Noun: stress on the prefix ''UP''."}, {"text": "to up-DATE", "pattern": "up-DATE (verb)", "note": "Verb: stress moves to ''DATE''."}, {"text": "deliberate", "pattern": "de-LIB-er-ate", "note": "Second syllable ''LIB'' is stressed."}]'::jsonb, 'Do not rush through the drills; prioritize clarity, natural cadence, and accurate articulation.', false, 51, 'published')
